window.QUIZ_LOCAL = (window.QUIZ_LOCAL||[]).concat([{"q":"1930년대에 일본인 내곡만평(內谷萬平)이 지은 정원으로, 우리나라의 서원양식으로 꾸며 놓았다. 입구정원·안뜰정원·임천정원·후원으로 이루어져 있으며, 일본식 석등과 일본식 석탑이 배치되어 있어 일본식 정원의 분위기가 물씬 풍긴다. 입구정원에는 향나무·종려나무·얼룩식나무·다매화·은테사철나무·모과나무·배롱나무·사스끼철쭉 등을 심고, 안뜰정원에는 잔디로 마당을 만들어 후박나무와 후파향나무·종가시나무 등을 심어놓았다. 임천정원에는 히말라야시이다·주목·삼나무·편백나무·종가시·위성류·다매화 등을 빈틈없이 심었는데, 수풀 속으로 좁다란 시냇물이 흐른다.","a":"이훈동정원","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"목포시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662148.jpg"},{"q":"여덟 분(정함일의 부인 이씨와 그의 딸 정씨·정경득의 부인 박씨·정희득의 부인 이씨·정운길의 부인 오씨·정주일의 부인 이씨·정절의 부인 김씨·정호인의 부인 이씨)의 열녀를 추모하기 위해 세운 정각이다. 이들은 선조 30년(1592) 정유재란 때 왜군들과 맞서 싸운 남편들의 전사소식을 듣고 피난을 가다 왜군들의 추격을 받고 칠산 앞바다에 투신함으로서 정절을 지켰다고 한다. 숙종 7년(1681) 함평에 정각을 세우고 순절지인 묵방포에는 순절비를 세웠다. 앞면 3칸·옆면 1칸 규모이며, 지붕은 옆면에서 보았을 때 사람 인(人)자 모양과 비슷한 맞배지붕이다.","a":"팔열부정각","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"함평군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653962.jpg"},{"q":"서민금융의 전당을 목표로 했던 ○○○○○ 사옥이다. 1913년 국내 건물로는 처음으로 국제 현상 설계에 의해 1933∼1935년에 지어졌다. 한국전쟁 때에도 피해가 없어 원래의 모습을 그대로 보존하고 있다. 지하 1층·지상 5층 건물로서 은행 건물로는 한국 최초의 철골·철근 구조를 사용하였으며, 한국산 화강석을 사용하여 마감하였다. 영업장 천장의 꽃 모양 석고부조는 근대 건축 양식의 걸작이라는 평을 받고있다. 전체적으로 화려하고 단아한 모양의 비례감을 보여주고 있는 전형적인 네오-바로크 양식의 건물이다.","a":"옛 제일은행 본점","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636229.jpg"},{"q":"임진왜란 때 의병장으로 활약했던 김덕령(1567∼1596)과 그의 부인 흥양 이씨, 그의 형 김덕홍(1558∼1592), 그의 아우 김덕보(1571∼1596) 등 일가족의 충효와 절개를 기리기 위해 나라에서 마을 앞에 세운 비석과 비각이다. 김덕령은 그의 형이 고경명의 지휘 아래 참전한 금산전투에서 전사하자 상중(喪中)인데도 의병을 모집하여 왜군의 전라도 진출을 막기 위해 진해와 고성 등지에서 싸웠다. 그러나 이몽학의 반란에 연루되었다는 모함으로 혹독한 고문 끝에 20일만에 옥사하였다.","a":"충효동정려비각","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"북구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645736.jpg"},{"q":"소유자 남정구 씨의 3대조 남용진이 지은 주택이다. 1800년 말경에 지은 것으로 전하며, 안채, 사랑채, 곳간채, 문간채로 구성되어 있다. 대문을 들어서면 넓은 사랑마당이 있고 북쪽에 一자형 사랑채를 남향으로 배치하였고 뒤쪽에 ㄷ자형 안채가 있어 전체적으로 튼 ㅁ자형 구조를 보인다. 안채 서쪽에는 방앗간채가 있다. 하인들이 살던 3칸 초가와 우물 등이 울타리 안에 남아 있고, 옛 생활의 자취를 많이 볼 수 있어 보존할만한 가치가 있다.","a":"의성서계당","c":"문화유산자료","nc":"","r":"경상북도","s":"의성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663239.jpg"},{"q":"이 삼존불은 대웅전 중앙에 위치한 장방형 불단 위에 각각의 연화좌를 두고 그 위에 봉안되어 있다. 머리 뒤편 정수리 쪽으로 서너 개의 나발이 결손 되었거나 소매와 군의자락에 도금이 탈락한 것을 제외하면 전반적인 보존상태는 비교적 양호한 편이다. 세 구의 불상은 저부에 마련된 복장공이 모두 열려 있었고, 복장물 역시 대부분이 도난당한 상태였으며, 그중 경전 · 다라니 등이 불상 내부의 목 부분과 팔, 다리 쪽으로 끼워져 남아 있었다. 또한 양측 협시상은 저부의 복장공 외에 배면 중앙에 타원형의 복장공을 따로 만들어 다른 판재로 엉성하게 덧대어 마감되어 있었다.","a":"남해 용문사 목조아미타여래삼존좌상","c":"시도유형문화유산","nc":"","r":"경상남도","s":"남해군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642699.jpg"},{"q":"본 작품은 족자형이며, 안료의 변색과 박락으로 인해 보존상태는 전체적으로 양호하지 못하다. 배면 중앙에는 세로 3행의 다라니가 주서로 적혀 있고, 네면 모서리에 주서(朱書) 범자가 한자(一字)씩 적혀 있다. 화면 중앙에 여래좌상을 중심으로 좌우에 보살입상을 배치한 여래삼존상이다. 본 존불은 두광과 신광을 갖추고 아래에서 솟아 오른 청색 연화좌 위에 앉아 오른손은 항마인, 가슴 앞까지 올린 왼손은 엄지와 중지를 맞댄 미타정인이다.","a":"운수사아미타삼존도","c":"문화유산자료","nc":"","r":"부산광역시","s":"사상구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659395.jpg"},{"q":"이 영정은 ○○○○○선사의 좌안7분면 바닥가부좌상으로, 돗자리위에 방석을 깔고 왼손에는 주장자를 오른손에는 염주를 쥐고 있다. 인물 뒤편으로는 주색바탕에 연속 모란문이 그려진 상단벽면과 하단돗자리의 이단구도를 배경으로 하여 도식화된 등받이 장식을 배치하였다. 그리고 화면 위편으로는 운보문이 그려진 녹색풍대를 묘사하였다. 화면 향좌측으로는 ‘○○○○○지진(鶴松堂理性之眞)’의 화제가 있다. 화면크기는 가로 78.6cm, 세로 120.3cm이며, 바탕은 1폭의 면본으로 이루어져 있다.","a":"학송당 이성 진영","c":"시도유형문화유산","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/0000000001643026.JPG"},{"q":"연대란 옛 군사적 통신수단으로 적의 침입이나 위급한 일이 일어났을 때, 낮에는 연기를 피우고 밤에는 횃불을 사용하여 인근 마을이나 군대가 있는 곳에 빠르게 연락하던 시설이다. 봉수대와 차이점이 있다면 연대는 해변 가까운 높은 지대에 설치하는 반면 봉수대는 산 정상에 위치한다는 점이다. 수산진에 소속된 ○○○○는 해안 절벽과 푸른바다, 선돌바위같은 주변경관이 뛰어난 곳에 자리잡고 있다. 이 연대는 옛 모습이 잘 남아 있으며, 연대 위에는 화덕자리도 남아 있다.","a":"협자연대","c":"시도기념물","nc":"","r":"제주특별자치도","s":"서귀포시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657799.jpg"},{"q":"이 정려는 고려 때 ○○○을 지낸 ○○○의 처 이씨의 지조를 기리기 위하여 세운 것이다. 이씨 부인은 남편 ○○○이 죽은 후, 당시의 풍습대로 개가를 하라는 부모의 청을 거절하고, 이곳 구미리로 내려와 살면서 아들 양은보를 키워 가문을 잇도록 하였다. 양은보의 후손 중에서 훌륭한 인물이 많이 나오게 된 것도 모두 이씨부인의 노력 때문이었다고 한다. 이씨 부인이 세상을 떠난 후에, 부인의 행실을 알게 된 조선 세조는 1467년에 정려를 내려 후세 사람들에게 귀감이 되도록 하였다.","a":"고려직제학양수생처열부이씨려","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"순창군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661846.jpg"},{"q":"경주 정씨 노송정 정지년을 중심으로 하여 옥계 정승복, 그의 아들 성은 정사준, 매헌 정사횡, 손자 정소빈, 정소선의 위패를 모시고 제사지내는 서원이다. 정지년은 세종 20년(1438) 문과에 급제하여 벼슬을 하다가 수양대군이 단종의 왕위를 빼앗자 관직을 버리고 유교경전을 연구한 사람이다. 이 서원은 순조 21년(1821)에 성의 남쪽 장천리에 세웠다고 『순천속지』에 기록되어 있다. 그 뒤 고종 5년(1868) 흥선대원군의 서원철폐령으로 철거된 뒤 1953년 지금 있는 자리로 옮겨 세웠다.","a":"옥계서원","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"순천시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661899.jpg"},{"q":"○○ 대승사 ○○○○○은 옥개석에 층급받침이 없이 복화반의 문양을 띠고 있는 것은 이 탑이 유일하다 할 수 있다. 고려시대에 건립된 것으로 추정되는 석탑으로 이러한 양식은 흔치 않은 예라 할 수 있다. 또한 옥개석 네 면의 귀퉁이에 풍경을 달 수 있도록 작은 홈을 만들어 화려하게 보이려 노력한 흔적이 보인다. 특히 풍경을 단 흔적이 옥개석 네 귀퉁이에 각각 2곳씩 되어 있는 것이 아니라 윗면에도 구멍이 있어 각각 세 곳의 구멍을 뚫은 형태이다. 기단부는 자연 암반을 이용하였으며, 상층기단의 크기가 초층과 이층의 옥개석보다 작아 균형감이 낮아 보인다.","a":"문경 윤필암 삼층이형석탑","c":"문화유산자료","nc":"","r":"경상북도","s":"문경시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663742.jpg"},{"q":"○○○란 옛 선현의 자취를 살피어 후세에 알리고 이를 계기로 그를 추모하기 위하여 세워두는 비로, 이 비는 조선시대 전기의 문신이자 생육신의 한 사람인 ○○○ 선생의 공적을 기리고 있다. 선생의 호는 ○○으로, 길재의 제자가 되어 가르침을 받고 과거에 급제하여 벼슬길에 올랐다. 거창 지역에 현감으로 있을 때에는 어진 다스림을 베풀어 고을 사람들의 칭송을 받았으며 ‘청백리’라는 호칭을 얻었다.","a":"경은 이맹전 유허비 및 묘비","c":"문화유산자료","nc":"","r":"경상북도","s":"구미시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663184.jpg"},{"q":"○○○은 약 500여년전 현감벼슬을 지냈던 김자간이 경주에서 울산 명촌리에 들어와 자리를 잡으면서 세운 경주 김씨의 정각이다. 현재 건물은 약 200여년 전에 고쳐 지은 것으로 1칸이던 온돌방을 2칸으로 늘려 지었다. 규모는 앞면이 3칸인데 비해 옆면은 왼쪽이 3칸·오른쪽이 2칸으로 되어 있다. 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕이다. 앞면에는 ‘명헌’이라는 현판이 걸려 있으며, 둥근기둥(두리기둥)에 싸리나무를 사용한 것이 특징이다.","a":"만정헌","c":"문화유산자료","nc":"","r":"울산광역시","s":"울주군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659772.jpg"},{"q":"조선시대의 보(堡)는 제진(諸鎭)의 보조적 방어시설로서 최전방에서 적의 동태 감시나 인근주민 대피, 유사시 전투를 하는 소규모 성으로서 중요한 기능을 가지고 있었다. 또한, 보 주변에는 봉수가 설치되어 즉시 신호나 포성 같은 소리를 통하여 주변의 주민과 인근 지역 및 내지에 알리는 역할을 하였다. ○○○○는 『조선왕조실록(朝鮮王朝實錄)』에 의하면, 삼도 도체찰사 정분(鄭苯)의 건의로 왜구를 막기 위해 1450년(문종 즉위년)부터 처음 목책성(木柵城)으로 설치되었다.","a":"유포석보","c":"시도기념물","nc":"","r":"울산광역시","s":"북구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645886.jpg"},{"q":"○○○는 횃불과 연기를 이용하여 급한 소식을 전하던 옛날의 통신수단을 말한다. 높은 산에 올라가서 불을 피워 낮에는 연기로 밤에는 불빛으로 신호를 보냈다. 경상남도 ○○시의 ○○○○○는 해발 370m의 ○○○ 정상에 있으며 산 정상에서 덕포동과 장목면의 경계를 형성한다. 봉화를 피우기 위한 연대(煙臺)는 자연석을 이용하여 축대를 쌓고 잔돌을 채워 넣어 만들었다. 현재는 바깥 2단까지 흔적이 남아 있으나 그 위는 경사가 급해 확인할 수 없고 다만 3단까지 연통이 있었을 것으로 예상한다.","a":"거제 강망산 봉수대","c":"시도기념물","nc":"","r":"경상남도","s":"거제시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1656560.jpg"},{"q":"이 책은 조선과 러시아 간에 체결한 조약문서이다. 그 내용은 조선과 러시아가 자유롭게 영원히 통상하자는 것이다. 당시 조선이 수입한 것은 농기, 주류 등 39종, 호박 등 32종, 약품 등 4종이며, 수출은 금은 등 5종, 홍삼 등 다수이다. 조선에서는 고종 21년(1884) 5월 15일에 특간전권대신 김병시가 서명을 하였고 같은해 6월 25일에 러시아 전권대신이 서명을 하였다. 또한 고종 22년(1885) 8월 16일에 고종이 경복궁에서 직접 서명한 것이다. 이것은 러시아와의 외교사를 연구하는데 중요한 자료이다.","a":"조아통상조약(한문, 아문)","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"서초구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2587935.jpg"},{"q":"○○○○○는 조선 영조 때의 무신 남연년(1653∼1728)의 1책본 시집으로, 조선 영조 24년(1748)에 ○○본으로 간행되었다. 남연년의 자는 수백이고, 호는 현암이다. 24세에 무과에 급제한 후 선전관을 거쳐 여러 벼슬을 지냈다. 조선 영조 4년(1728) 이인좌의 난이 일어나자 청주영을 지키다 순절하였다. 이에 조정에서 그 충절을 기리기 위하여 ‘○○○’이라는 시호를 내렸다.","a":"남충장공시고 목판","c":"시도유형문화유산","nc":"","r":"충청북도","s":"음성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638790.jpg"},{"q":"임진왜란시 제2차 진주성 싸움에서 활약한 최경회(1532~1593) 장군의 위패를 모신 사당이다. 조선 순조 때 세운 이 사당은 처음에 능주목 동면 금전리에 세웠다가 1963년 금전 저수지 축조로 지금 있는 자리에 옮겨 세웠다. 최경회 장군은 임진왜란 때 의병장으로 전라남도 능주에서 태어났다. 명종 16년(1561) 생원시에 합격하였으며, 1567년에는 과거에 급제하였다. 임진왜란이 일어나자 의병을 모집하여 일본군을 장수에서 막아 싸웠고 금산에서 퇴각하는 적을 공격하여 격파하였다.","a":"최경회사당","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"화순군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661998.jpg"},{"q":"동지중추부사를 지낸 화림재 전시서(全時敍)선생이 1640년경 서산서원을 짓고 그 곁인 현 거연정 위치에 억새로 만든 정자를 최초로 건립하였으며 1853년 화재로 서원이 불타자 이듬해 복구하였으나 1868년 서원철폐령에 따라 서원이 훼철되자 1872년 화림재 선생의 7대손인 전재학 등이 억새로 된 정자를 철거하고 훼철된 서산서원의 재목으로 재 건립되었으며 1901년 중수가 있었다.","a":"함양거연정","c":"시도유형문화유산","nc":"","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642626.jpg"},{"q":"성주 ○○○○○은 1936년에 도문환(都文煥)이 건립한 살림집으로, 결혼한 아들 도재림(都在琳) 내외가 분가하여 살도록 한 집이다. 택호(宅號)는 도재림의 부인이 배리(裵里)마을에서 시집온 데서 연유한다. 가옥의 건립자인 도문환(都文煥, 1887~1970)은 성주 지역의 선각적인 유림으로 계몽운동에 앞장 선 만산(晩山) 도갑모(都甲模, 1864~1937)의 아들로서, 1920년대 성주지역의 청년운동과 신간회운동 등 여러 사회운동에 활동하였던 인물이다.","a":"성주예산리배리댁","c":"문화유산자료","nc":"","r":"경상북도","s":"성주군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663608.jpg"},{"q":"전북특별자치도 남원 선원사 대웅전 안에 있는 높이 66cm, 입 지름 47cm의 조선시대 범종이다. 종의 맨 위, 매다는 고리 역할을 하는 용뉴는 한 마리 용이 웅크리고 있는 모습인데, 세부적인 표현은 따로 만들어 붙여서 완성하였다. 종의 몸체는 먼저 4줄의 가로선을 그어 5구역으로 나누었다. 맨 위에는 작은 원 11개를 나열하고, 원 안에 범자를 1자씩 새겨 넣었다. 그 아래로는 보살상을 4곳에 두었고, 보살상 사이에 꽃과 덮개, 관(冠)을 불규칙하게 나열하였다. 가운데 가장 넓은 곳에는 4개의 사각형 모양의 유곽을 만들어 둘레를 파도무늬로 장식하였다.","a":"선원사동종","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"남원시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639392.jpg"},{"q":"향교는 지방에 설립된 국립교육기관으로, 교육과 더불어 성현들에 대한 제사도 같이 행했던 곳이다. 조선 고종 광무 4년(1900)에 진남군이 고성현에서 분리됨에 따라 1901년에 고성향교에서 떨어져 나와 지금의 위치에 세웠다. 공부하는 곳인 명륜당과 동·서재가 앞쪽에 위치하고 제사지내는 곳인 대성전과 동·서무가 뒤쪽에 위치하는 전학후묘의 배치를 보이고 있다. 대성전에는 공자와 그의 제자, 우리나라의 여러 성현들을 모셨다. 그 밖의 건물들은 정문인 풍화루, 사당의 출입문인 내삼문, 제사지낼 때 쓰는 그릇을 보관하는 제기고가 있다.","a":"통영향교","c":"시도유형문화유산","nc":"","r":"경상남도","s":"통영시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641899.jpg"},{"q":"○○○ 소장 ○○○○○상도는 1901년에 조성된 것으로 본존을 중심으로 보살상, 사천왕, 제자상과 그 외 권속들이 좌우대칭을 이룬 군집구도이다. 도상구성은 화면 중앙의 석가를 중심으로 대좌 전면 좌우에 합장한 아난과 가섭을 배치하고, 본존의 양쪽에 보살상 3위, 사천왕상 2위씩 각각 배치하고, 화면 가장 위쪽에는 두광 좌우측에 분신불과 제자상을 각각 나타내고 있다. 본존은 연화좌 위에 결가부좌한 자세로 오른손은 가슴 위로 들고 왼손은 무릎 위에 두어 중품하생의 수인을 결하고 있다.","a":"산청문수암석가영산회후불탱","c":"시도유형문화유산","nc":"","r":"경상남도","s":"산청군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642655.jpg"},{"q":"경상남도 ○○시 일운면 ○○○ 앞산 능선에 있는 이 성은 조선시대 왜적을 막기 위하여 전방의 진지로 쌓은 것이다. 지세포성의 경계임무 구실을 하고, 선조 37년(1604)에 옥포 진지로 옮겼다가 다시 이곳으로 옮겼다. 성 아래에 있는 ○○○ 마을이 있고, 성 안은 모두 논과 밭이며 성 가운데에 우물이 있다. 사방에 성문을 두고 성문과 성문 사이에는 성루를 두었다. 『조선왕조실록』을 비롯한 여러 자료의 내용을 종합하여 살펴보면 ○○○성은 성종 21년(1490)지금의 옥포 북쪽 조라를 신조라라 불렀는데 지금은 신자가 빠지고 조라라 한다.","a":"거제 구조라진성","c":"시도기념물","nc":"","r":"경상남도","s":"거제시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1656584.jpg"},{"q":"○○○ 명부전에 모셔져 있는 본존인 지장보살을 중심으로 하여 왼쪽에 도명존자(道明尊者)와 오른쪽에 무독귀왕(無毒鬼王), 그리고 그 좌우에 명부시왕(冥府十王)·귀왕·판관·사자상 등 모두 21구의 불상들이다. 이 시왕상 등은 경남 함양군 백전면 백운리에 소재했던 영은사(靈隱寺)가 폐사되면서 1903년에 ○○○로 옮겨져 온 것으로 전해진다. 지장보살을 비롯한 도명존자와 무독귀왕 등은 대체적으로 양호한 상태로 도금 또는 채색되었고, 그 밖의 다른 시왕상 등은 퇴색되었거나 훼손부분을 약간씩 보수한 흔적이 있다.","a":"통영 용화사 목조지장시왕상","c":"시도유형문화유산","nc":"","r":"경상남도","s":"통영시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642338.jpg"},{"q":"1894년 동학농민혁명에 가담하여 1907년 하와이로 피신하고 국권회복을 목적으로 대동보국회를 결성하여 대동공보 간행, 1908년 스티븐스가 일제의 침략을 정당화하자 그를 방문하여 발언 취소를 요구하고, 장인환, 전명운 의거를 지원, 1908년 7월 한인소년병학교 사관양성을 통한 항일 무장투쟁을 지원 1910년 대한인국민회 북미지방총회 총회장으로 활동하면서 1940년 서거 하실 때 까지 독립운동을 행하신 분이다.","a":"태안 문양목생가터","c":"문화유산자료","nc":"","r":"충청남도","s":"태안군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2019042417300000.png"},{"q":"○○○는 고려시대 견성사로 불리웠으며, 조선 연산군 4년(1498) 정현왕후가 성종(재위 1469∼1494)의 릉인 선릉의 원찰로 견성사를 중창하면서 이름을 ○○○로 고쳤다. 조선 최대의 명찰 중에 하나였고 불교 중흥의 역할이 컸으나 임진왜란 등 전란으로 불타 몇 차례 중건 및 중수된 바 있다. 현재 문화유산으로 지정된 ○○○○○도 1939년에 화재로 전소된 것을 1941년에 중건한 것으로 대중들이 참선하는 선방이다. 명종 7년에 ○○○에서 스님이 되기 위해 치러야하는 시험인 승과를 실시하였다는 기록이 확인되고 있어 ○○○이라는 이름이 붙게 되었다.","a":"봉은사 선불당","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"강남구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636214.jpg"},{"q":"퇴계 이황(1501∼1570)과 우복 정경세(1563∼1633) 선생을 기리기 위해 세운 서당이다. 처음 지은 연대는 알 수 없으나, 이곳에서 이황 선생과 정경세 선생이 강의하였던 곳이라하여 1500년대로 추정하고 있다. 숙종 16년(1690)에는 서당 뒤편에 사당을 지어 서원이라 하였다. 고종 5년(1868)에는 흥선대원군의 서원철폐령으로 철거되었다가, 고종 16년(1879)에 서원 옛터에 강당만을 다시 지어 고산서당이라 하였다. 그 뒤 1964년 수리하여 오늘에 이르고 있다.","a":"고산서당터","c":"문화유산자료","nc":"","r":"대구광역시","s":"수성구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659473.jpg"},{"q":"고종 32년(1895)에 지은 집으로 크게 안채, 사랑채, 행랑채, 대문채로 구성되어 있다. 안채는 앞면 6칸·옆면 2칸 크기로 옆면의 지붕선이 여덟 팔(八)자 모양과 비슷한 팔작지붕이다. 사랑채는 앞면 7칸·옆면 2칸 크기이며 팔작지붕에 안채와 병렬로 배치되어 있다. 가운데에서 오른쪽으로 이어지는 마루는 난간을 둘러 아름답게 처리하였다. 여러 채의 건물을 원형대로 잘 보존하고 있어 조선 후기 전통 민가를 살필 수 있는 좋은 자료가 되고 있다.","a":"합천 팔심리 윤씨고가","c":"시도민속문화유산","nc":"","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1659058.jpg"},{"q":"안채와 사랑채, 광으로 이루어진 ㅁ자형 주택으로 1903년 서석의 부호이던 엄근호가 지어 45년간 살던 집이다. 안채의 평면은 부엌을 중심으로 앞면에는 부엌광을 배치하고, 뒷면에 툇마루가 있는 안방을 두었다. 그 옆에는 대청과 건넌방을 들였다. 이 집은 안채와 사랑채 출입 대문을 분리하였고 그 사이 좁은 안마당에도 담장을 설치하여 남녀가 쓰는 공간을 따로 나누어 놓았다. 안채와 사랑채는 초가집이었던 것을 1970년대에 슬레이트와 함석으로 교체하였다. 여유있게 꾸민 집으로 영서·중부지방에서 흔히 볼 수 있는 가옥 형태를 갖추고 있다.","a":"홍천 풍암리 고택","c":"문화유산자료","nc":"","r":"강원특별자치도","s":"홍천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660461.jpg"},{"q":"향교는 공자와 성현께 제사를 지내고, 지방민의 교육과 교화를 위해 나라에서 세운 교육기관이다. 조선 전기에 세운 이 향교는 임진왜란 때 불에 타 다시 세워졌으며 그 뒤로도 여러 차례 보수하여 현재 모습을 갖추었다. 남아 있는 건물로는 대성전, 명륜당, 동재, 내삼문, 외삼문이 있다. 대성전에는 공자를 비롯한 5성(聖)과 중국·우리나라 성현의 위패를 모시고 있다. 조선시대에는 국가로부터 토지와 서적·노비를 지급받아 가르쳤으나, 갑오개혁 이후로 교육 기능은 없어지고 지금은 봄·가을에 제사를 지내고 있다.","a":"직산향교","c":"시도기념물","nc":"","r":"충청남도","s":"천안시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1652876.jpg"},{"q":"청풍자 정윤목(1571∼1629)이 후진을 양성하기 위해 세운 건물이다. 정윤목은 서원부원군 정탁의 아들로 초서에 뛰어난 학자이다. 광해군의 실정에 불만을 품고 지방으로 내려와 후진양성에 힘썼다. 삼강마을 동쪽 낙동강변에 자리잡은 이 강당은 앞쪽으로 둥근기둥을 세우고 옆면과 뒤쪽으로는 네모기둥을 세워 건물을 지었다. 가운데에 개방된 구조의 마루를 두고 양쪽에 온돌방을 배치하였다. ‘백세청풍(百世淸風)’이라는 현판 글씨는 정윤목이 선조 22년(1589)에 부친을 따라 중국에 가서 백이숙제의 묘를 참배하고 돌아올 때 베껴온 것이다.","a":"삼강강당","c":"문화유산자료","nc":"","r":"경상북도","s":"예천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662826.jpg"},{"q":"남파 설진영(1869∼1940) 선생이 후학을 양성하고 민족사상을 배향하였던 곳으로 1910년에 세웠다. 선생은 고종 32년(1895) 기우만과 함께 장성에서 의병활동을 하였으며 1910년 한일합방이 되자 오랑캐는 상대할 수 없다고 하여 아미산 남쪽에 남파 서실을 세우고, 학문 연구와 후진양성에 심혈을 기울여 많은 영재와 항일 애국지사를 배출하였다. 1940년 일제 민족말살정책의 하나인 창씨개명에 분한 마음을 참지 못하다가 성(姓)을 절대로 고치지 않겠다는 절명서와 유서를 남긴 채 서실 앞 우물에 투신 자결하였다.","a":"설진영서실","c":"시도기념물","nc":"","r":"전북특별자치도","s":"순창군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653667.jpg"},{"q":"이 지방 출신으로 과거에 합격한 사람들이 고장의 발전과 미풍양속을 위해 함께 모여 의논하던 곳이다. 조선초에 지어졌으나 훼손되어 순조 10년(1810) 다시 건립하였다. 생원, 진사에 합격한 사람과 대과에 합격한 사람들이 ○○○에 모여 자신들의 우의를 두텁게 하고 주민의 교화와 풍속을 바로 잡는데 힘썼다. 또한 정치활동에 대한 건의와 자문도 하던 원로원 구실을 하였다. 고종 31년(1894) 과거제도가 없어짐에 따라 모임도 함께 없어졌는데, 그 후손들이 모선계를 조직하여 관리해 오고있다.","a":"계련당","c":"시도유형문화유산","nc":"","r":"강원특별자치도","s":"강릉시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637950.jpg"},{"q":"조선 숙종 때 성리학자인 정규양(1667∼1732) 선생이 숙종 27년(1701)에 지은 집으로 처음에는 태고와라 하였으나, 영조 6년(1730)에 문인들이 수리해서 ○○○이라 하였다. 선생은 형인 정만양 선생과 이곳에서 제자를 양성하기 위해 세운 옥간정을 왕래하였으며, 형제간의 우애를 상징하는 뜻으로 훈과 지를 호로 삼았다. 건물의 규모는 앞면 2칸·옆면 2칸으로 지붕은 옆면이 여덟 팔(八)자 모양인 팔작지붕이며, 4면에 툇간을 둔 독특한 건물이다.","a":"모고헌","c":"시도유형문화유산","nc":"","r":"경상북도","s":"영천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640850.jpg"},{"q":"영조 23년(1747년)에 이재< 李縡 >가 쓴 비로써 현재 비각안에 보호되어 있다. ○○○○은 송시열< 宋時烈 >이 정읍에서 사약을 받은 후, 그 무고함이 밝혀져 숙종 21년(1695년) 사액< 賜額 >이 내려 세워졌으나, 고종 8년(1871년) 철거되었다. 그 유허에 비를 세웠는데 높이 195㎝, 너비 78㎝, 두께 19㎝이다.","a":"고암서원묘정비","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"정읍시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661696.jpg"},{"q":"경상남도 ○○군 옥종면 북방리 ○○○의 능선을 따라 쌓은 산성으로, 성이 언제 만들어졌는지는 알 수 없으나 1770년대까지 성이 있었다고 한다. ○○○은 능선 곳곳이 암벽이 형성되어 있는데, 이 자연 암벽들을 연결하여 성을 쌓은 흔적이 남아 있다. 특히 산 정상부근에는 지휘자들이 군사회의를 개최한 듯한 의자 및 탁자 모양의 돌이 남아 있다. 이곳은 조선 고종 31년(1894) 내정을 간섭하는 일본군에 항거하여 봉기하는 서부경남 일원의 농민군 5천여 명과 일본군이 맞서 싸운 곳으로 유명하다.","a":"하동 고성산성","c":"시도기념물","nc":"","r":"경상남도","s":"하동군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1655796.jpg"},{"q":"회덕마을의 가장 안쪽 귀퉁이에 자리잡고 있는 집으로 앞에는 논밭이 있고, 그 너머로 지리산 봉우리들이 펼쳐져 있어 경관이 좋다. 원래는 마을 전체가 샛집이었는데 현재는 2채밖에 남아 있지 않다. 다른 한채는 뼈대만 남아 있으며, 벽체와 창호는 현대식으로 고쳤다. 안채와 아래채가 안마당 주변에 ㄱ자형으로 배치되어 있고 그 앞에 헛간채가 있어 전체적으로 튼 ㄷ자형식이다. 안채와 헛간채 사이에는 창고가 경사지에 배치되어 있으며, 사랑채 뒤쪽 바깥에는 변소가 있다. 안채는 왼쪽부터 부엌 2칸·방 1칸·광·아랫방·골방으로 되어 있으며, 부엌 뒤쪽으로 뒷마당과 장독대가 있다.","a":"덕치리초가","c":"시도민속문화유산","nc":"","r":"전북특별자치도","s":"남원시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658337.jpg"},{"q":"원정 여희림(1481∼1553) 선생을 모시는 사당이다. 여희림은 중종 2년(1507)에 사마시에 합격하여 조광조, 김정 등과 교우관계를 맺었으며 중종 11년(1516)에는 고향에 내려가 여씨 향약을 실시하였다. 이 사당은 조선 명종 13년(1558)에 후손들이 세웠는데 성주댐 건설로 원래 있던 자리가 수몰되어 지금 있는 자리로 옮겼다. 앞면 3칸·옆면 2칸 규모이며, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양을 한 팔작지붕으로 꾸몄다. 중앙칸과 오른쪽 칸에 걸쳐 온돌방을 연결시켰고 방 사이에 문을 달아 필요에 따라 공간을 나눌 수 있게 하였다.","a":"구강재","c":"문화유산자료","nc":"","r":"경상북도","s":"성주군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663043.jpg"},{"q":"탱화란 액자나 족자 형태로 만들어 법당에 걸 수 있게 만든 불교그림이다. ○○○ 대웅전의 불상 뒤에 마련된 이 탱화는 앞에 모신 불상(○○○)을 보고 그린 것으로, 화면 가운데에 큼직한 ○○○을 두고, 그 좌우로 4보살과 2제자를, 주위에는 2천과 4천을 배치하였다. 석가가 영취산에서 설법하는 모습을 그린 영산회상도로, 구도가 뛰어나고 인물의 형태가 개성있게 표현되었다. 수채화에 가까운 부드러운 필치로 채색을 하였으며, 특히 엷은색 계열의 처리가 독특하면서도 뛰어나다.","a":"조계사 석가불도","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2589933.png"},{"q":"조선 후기 숙종(肅宗)의 세 번째 왕비가 된 인원 왕후(仁元王后)의 아버지 경은부원군(慶恩府院君) 김주신(金柱臣)에 의해 1709년에 건립되었다. 이 건물은 김주신이 그의 아버지 김일진의 묘에 제사를 지내기 위하여 무덤 가까이에 지은 재사(齋舍) 건물이다. ‘○○○’이라는 이름은 “영원히 잊지 않고 생각한다”라는 의미가 담겨 있으며, 현판은 재사의 중심건물에 걸었다. 건물은 ‘ㄷ’자형의 본채와 ‘ㅡ’자형의 문간행랑채가 서로 마주보고 놓여 장방형의 마당을 둘러싸도록 배치되었다. 본채의 중심에는 2칸의 대청이 있으며 좌우에 방을 두었다.","a":"고양 경주김씨의정공파 영사정","c":"문화유산자료","nc":"","r":"경기도","s":"고양시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660295.jpg"},{"q":"익재 이제현의 학문과 덕행을 추모하기 위하여 영정과 위패를 모신 서원이다. 이제현은 고려 후기의 학자이며 정치가이다. 학자로서 이제현은 뛰어난 유학자로 성리학을 수용·발전시키는데 매우 중요한 구실을 하였다. 문학 부문에서도 그는 대가를 이루었다. 많은 시문을 남겼고, 고려의 한문학을 발전시켜 한단계 높게 끌어 올렸다. 한편 사학(史學)에도 많은 업적을 남겼다. 그의 저술로 현존하는 것은 『익재난고』10권과 『역옹패설』2권이다. ○○○○은 원래 고려 공민왕(재위 1351∼1374) 때 이제현의 영당(影堂)으로 세운 것을, 숙종 12년(1686)에 서원으로 다시 세웠다.","a":"구강서원","c":"문화유산자료","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662791.jpg"},{"q":"고려의 개국공신 ○○○ 신숭겸 장군의 묘소이다. 평산 신씨의 시조로서, 918년 배현경·홍유·복지겸 등과 함께 궁예를 몰아내고 왕건을 추대하여 고려 건국에 이바지하였다. 태조 10년(927) 대구 공산에서 후백제 견훤의 군대와 싸우다가 태조가 적군에게 포위되어 위급해지자 태조의 옷을 입고 변장하여 맞서다가 전사하였다. 적군이 신숭겸을 태조로 오인하고 그의 목을 베어가자 태조는 머리없는 시신에 금으로 머리를 만들어 장례식을 치루었다고 한다. 도굴을 막기 위하여 묘는 하나인데 봉분을 3개 만들었다고 전해지고 있으며, 현재 이 묘에는 3개의 봉분이 나란히 있다.","a":"신장절공묘역","c":"시도기념물","nc":"","r":"강원특별자치도","s":"춘천시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1647789.jpg"},{"q":"한국 ○○○의 본관으로서 일제강점기와 한국전쟁을 거쳐 한국 ○○○의 중흥기인 근대화 과정까지 한국 ○○○의 혼과 정신이 뿌리깊게 배어 있는 건물이다. 1928년에 지어져서 세부적인 개조가 있었고, 건물 뒷면을 증축하였지만 대체로 원형을 유지하고 있다. 현관의 4개의 기둥과 지붕이 당당한 인상을 주는 건물로, 현관 쪽의 바닥은 물갈기 슬래브이나 복도 및 계단 난간은 목조로 되어 있다. 1층은 사무실, 2층은 집회·예배당이 있고 목조 트러스가 이색적인 아름다움이 보인다.","a":"구세군중앙회관","c":"시도기념물","nc":"","r":"서울특별시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1644839.jpg"},{"q":"모두 12기의 ○○○로 천내강을 굽어보고 있다. 마을에서는 이 ○○○들을 팔선바위라 하여 신성시하고 함부로 건드리지 않는다. 주변 입지는 용화리에서 흘러온 금강의 물줄기가 이 구릉을 S자 형태로 휘어돌아 충청북도 영동 쪽으로 빠져나가고 ○○읍에서 나오는 봉황천과 천내천이 합류하는 곳이다. ○○○○○의 형태는 개석식 또는 바둑판식이며, 개석의 형태는 사각형 또는 부정형이며 200m 안팎의 크기이다. 주민들에 의하면 예전에 ○○○이 있는 곳에서 돌칼, 돌화살촉과 붉은 토기 등이 출토되었다고 한다.","a":"금산 천내리 고인돌","c":"문화유산자료","nc":"","r":"충청남도","s":"금산군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661470.jpg"},{"q":"향교는 공자 등 성현들에게 제사를 지내고 지방민의 교육과 교화를 위해 나라에서 세운 교육기관이다. ○○○○의 언제 지었는지 정확히는 알 수 없으나, 고려 현종 1년(1010)에 세웠다고 전한다. 조선 인조 1년(1623)과 현종 15년(1674), 순조 8년(1808)에 수리하였고 1923년에 크게 보수하여 지금의 모습을 갖추었다. 건물 배치는 외삼문 없이 바로 교육 공간인 명륜당이 있고, 그 뒤에 제사 공간인 대성전이 있는 전학후묘의 형식을 따르고 있다. 대성전은 앞면 3칸·옆면 3칸 규모로, 지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕이다.","a":"결성향교","c":"시도기념물","nc":"","r":"충청남도","s":"홍성군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1652997.jpg"},{"q":"○○○○는 고려말 공양왕 2년(1390)에 왜구를 방어하기 위한 목적으로 수군만호진을 처음 설치하였고, 조선 전기 성종 때는 경상도 우수군이 머물수 있는 군영을 설치했던 곳이다. 수군은 배 위에서만 방어한다는 원칙이 성종 때에 무너지면서 경상도와 전라도 등 22곳에 수군진영을 만들었는데, 이 성은 성종 16년(1485)에 쌓기 시작하여 이듬해에 완성하였다. 성터는 산 정상에서 능선을 따라 해안에 이르도록 자연지형을 이용하여 만들었으며 자연석으로 기반을 마련하였다.","a":"창원 제포성지","c":"시도기념물","nc":"","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1656320.jpg"},{"q":"약 300년 전 경상남도 ○○군 이동면 ○○○ 경내에서 발견된 보살상이다. 현재는 하얀 분칠을 한 상태여서 본래의 모습을 자세히 알 수 없다. 사각형에 가까운 얼굴은 원만하나 눈과 입이 작고 코가 큼직하여 다소 형식화된 면이 보인다. 긴 상체에 넓은 무릎 등은 부피감이 풍부하고 탄력적이어서 보살상의 격이 높다는 것을 알 수 있다. 옷은 양 어깨에 걸쳐 흘러내리고 있는데, 띠주름 무늬가 자연스러워 불상의 특징과 조화를 이루고 있다. 왼손은 배에 대고 병을 들고 있으며 오른손은 가슴에 대었는데 연꽃가지를 잡고 있었던 것 같다.","a":"남해 용문사 석조보살좌상","c":"시도유형문화유산","nc":"","r":"경상남도","s":"남해군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641698.jpg"},{"q":"○○○○ 수은공파의 족보를 간행하기 위한 목판이다. 1711년에 발간한 『신묘보(辛卯譜)』의 목판을 비롯하여 모두 314판이 남아 있다. 남아있는 보판은 『신묘보』 79판, 『무인보(戊寅譜)』45판, 『정사보(丁巳譜)』 142판, 『수은실기(樹隱實記)』 30판, 『신묘보』 서(序) 8판, 『무인보(戊寅譜)』 서(序) 10판 등이다.","a":"경주김씨보판각","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"남원시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639640.jpg"},{"q":"『유암총서(柳菴叢書)』,『○○○○』는 이강회(李綱會; 1789~?)가 ○○○○○에 칩거하면서 자신의 글과 스승인 정약전, 정약용 형제의 글을 한데 묶어 놓은 문집의 초고본에 해당한다. 다른 곳에서는 발견할 수 없는 정약전의 저서 「표해시말(漂海始末)」(유암총서 수록)․「송정사의(松政私議)」(○○○○ 일권에 수록)가 담겨져 있으며, 정약용의 속담 한역(俗談漢譯) 저술인 「백언시(百諺詩)」는 『여유당전서(與猶堂全書)』에 수록된 「이담속찬(耳談續纂)」의 초고본으로서 높은 가치를 지닌다.","a":"신안 우이도 유암총서와 운곡잡저","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"신안군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662335.jpg"},{"q":"○○○○은 임진왜란 때 의병을 일으켰다가 순절한 권복흥의 사당으로 조선 영조 15년(1739)에 건립되었다. 조선 고종 5년(1868) 때 훼철된 후 1924년에 다시 단을 설치하고 복향하였다. ○○○○은 강당인 숭의당○르 중심으로 하여 부속건물들이 배치되어 있다. 이 중 문화유산자료로 지정된 강당은 홑처마 굴도리 3량집으로 좌우에 방을 배치하고 중간에 3칸의 대청이 만들어져 있다. 정면에는 단계사, 대청 뒷벽에는 숭의당 현판이 각각 걸려있다. 특히 강당의 좌우 협칸 전면 상부의 기둥 사이에 도리방향으로 설치된 들보 등은 전통목구조의 특징을 잘 보여준다.","a":"단계서당","c":"문화유산자료","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663508.jpg"},{"q":"○○○는 상왕산 남쪽 기슭에 있는 절로 신라 문무왕 3년(663)에 의현선사가 세웠다. 이 절은 성종 18년(1487) 이후 여러 차례 보수를 하여 오늘에 이르고 있다. ○○○은 기록으로 미루어 일제시대 초기인 1919년에 고쳐 세운 건물임을 알 수 있다. 현재 ‘명부전’이란 현판이 달려있는 ○○○은 1993년에 건물을 해체하여 원래 자리 오른편에 세웠는데, 이전 자리에는 대적광전을 새로 지었다. 규모는 앞면 3칸·옆면 2칸이며 지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕이다.","a":"일락사대웅전","c":"문화유산자료","nc":"","r":"충청남도","s":"서산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661219.jpg"},{"q":"임경당 김열의 덕을 기리고자 후손들이 지은 별당건축으로, 임경당(강원특별자치도 유형문화유산)보다는 높은 산세를 배경으로 위치하고 있다. 임경당보다 규모가 조금 작은 앞면 3칸·옆면 2칸 규모이며, 지붕 옆면이 여덟 팔(八)자 모양인 팔작지붕집이다. 1칸 규모의 대청과 1칸의 온돌방으로 되어있다. 앞면 가운데의 2기둥은 원기둥이고, 양 옆의 기둥은 4각기둥으로 이루어졌다. 건물 안에는 친하게 지내던 율곡 이이가 김열에게 선물로 지어준 ‘호송설(護松說)’을 새긴 현판과 유당 김노경이 쓴 ‘임경당(臨鏡堂)’현판이 걸려있다.","a":"상임경당","c":"시도유형문화유산","nc":"","r":"강원특별자치도","s":"강릉시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637992.jpg"},{"q":"○○○○○는 임진왜란 후 ○○○이 중건되던 1614년(광해군 6)에 처음 세워졌으며, 1856년(철종 7)에 중각(重刻)되었다. 비석에는 ‘지차개하마 잡인무득입(至此皆下馬 雜人毋得入)’이라고 새겨 계급의 높고 낮음, 신분의 귀천을 떠나 모두 말에서 내리고, 잡인들의 출입을 금한다는 내용이 담겨져 있다. ○○○○○는 여느 ○○○와는 다르게 판석위에 비를 올리고 그 판석을 두 마리의 사자(혹은 해태)가 등으로 받치고 있는 특이한 형태로, 단지 하마(下馬)의 의미로서만이 아닌 ○○○ 수호의 의미를 지니고 있는 것으로 판단된다.","a":"전주 경기전 하마비","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"전주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639818.jpg"},{"q":"○○○○○에서 발견된 횡혈묘는 한반도에서 처음으로 분명하게 확인된 예로, 잔존상태가 매우 양호하며 한반도 횡혈묘의 구조적 특징을 잘 보여주는 유적으로 묘의 구조가 일본열도 초기 횡혈묘와 형식이 비슷하여 양자간의 관계를 살펴 볼 수 있는 중요한 자료이며, 횡혈묘의 기원문제를 비롯한 고대 한․일 관계 연구에 중요한 고고학적가치가 높다.","a":"공주 단지리 고분군","c":"시도기념물","nc":"","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653261.jpg"},{"q":"영산강 상류의 충적평야를 낀 낮은 구릉지대로 장구촌 마을에 있는 무덤이다. 앞이 네모나고, 뒤가 둥근 전방후원형 무덤으로 일제시대에 도굴되어 많은 부분이 유실되었다. 1, 2호 무덤 모두 널길(연도)이 있는 굴식돌방무덤(횡혈식석실묘)이며 돌방(현실) 벽은 할석을 이용하여 벽돌처럼 쌓았다. 출토유물은 금귀고리·쇠화살촉·토기조각과 원통형토기·나팔형토기·구멍있는 아가리큰항아리(유공광구호)·쇠손칼·토기조각·유리구슬과 적갈색 원통형 토기가 수습되었다. ○○○ 무덤은 고대 무덤연구와 한일관계사를 밝히는데 많은 자료를 제공해 주는 중요한 유적이다.","a":"월계동장고분","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"광산구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645766.jpg"},{"q":"충청남도 공주시 공산성 동남쪽에 있는 해발 60m의 ○○○ 정상을 흙으로 둘러쌓은 테뫼식 토성이다. 성의 길이는 약 870m정도이지만 대부분 붕괴되어 원형을 알 수 있는 부분이 많지 않다. 현재 남아있는 북쪽벽은 높이 2m, 안쪽의 높이 0.7m, 윗면의 너비 2m정도이다. 남쪽벽은 거의 남아있지 않으며 서쪽벽은 공산성과 이어지고 있다. 전체 평면은 장방형이나 타원형에 가까운 형태로 자연지형을 최대한 이용하여 실제 높이보다 훨씬 높은 효과를 얻고 있다. 성안에서는 백제 토기조각, 기와조각들이 발견되어 건물이 있었던 것으로 짐작된다.","a":"공주옥녀봉성","c":"시도기념물","nc":"","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1652857.jpg"},{"q":"1895년 영산전을 건립하면서 제작, 봉안한 7폭 불화 가운데 4폭으로 16나한을 4폭으로 나누어 그렸다. 현재 영산전의 후불탱화 좌우로 각 2폭씩 걸려있는데, 16존자를 각각 독립적으로 한 존자씩 그린 후 4존자를 한 폭으로 하여 총4폭으로 구성하였다. 그런데 이중 제 10, 11, 13, 15존자도는 결실되어 1955년에 만봉(萬峰)과 석성(碩成)이 새로 그렸다.","a":"봉은사 십육나한도","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"강남구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636426.jpg"},{"q":"○○○○○은 우리나라에 유사한 사례가 없고 제작연대에 대한 기록이 없어 조성 시기나 용도는 정확히 알 수 없으나, 과거 ○○○에 승려 3000명이 거주할 당시 김치독으로 사용되었다고 전해지며, 지금도 내부에 염분이 검출되고 있어 채소류 등의 저장시설 용도로 사용되었을 것으로 추정된다. 크기는 깊이 240㎝, 윗부분의 바깥지름 240㎝, 안쪽지름 85㎝ 정도이다. 위와 아래는 각각 하나의 돌을 깎아 항아리 모양으로 만들고 배 부분은 30∼40㎝ 크기의 돌 4∼5장을 둥그스름하게 가공하여 원형으로 이은 것을 3단으로 쌓아올렸다.","a":"보은 법주사 석옹","c":"시도유형문화유산","nc":"","r":"충청북도","s":"보은군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638738.jpg"},{"q":"○○○○ 재사의 재실은 경북지역 상류층 재사건축의 고형을 잘 보여주고 있는 사례이다. 특히 이 재사는 퇴계 이황의 문인으로 대동운부군옥(보물 제878호)을 저술한 초간 권문해 선생의 재사로서 유교사적 가치와 건축사적 가치 그리고 역사적 가치가 높은 귀중한 자료로 여겨진다.","a":"예천권씨 용문재사","c":"문화유산자료","nc":"","r":"경상북도","s":"예천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2019051423172500.jpg"},{"q":"○○○○○군에서는 모두 12기의 ○○○이 분포하고 있는데, 2000년 실시된 발굴조사에 의하면 모두 북방식 ○○○이라 한다. ○○○의 묘실구조는 ＇ㅍ＇자 형태이고, 크기는 대·중·소형으로 구분된다. 무문토기와 대롱옥, 반달돌칼, 화살촉 등 매우 다양한 유물이 출토되었다.","a":"강화 오상리 고인돌","c":"시도기념물","nc":"","r":"인천광역시","s":"강화군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2018112015523200.jpg"},{"q":"조선 명종 1년(1546) 부장공 김언광이 묘를 관리하고 제사를 모시던 재사로 세웠으며 숙종 13년(1687) 고쳐 세워 오늘에 이르고 있다. 재실 배치는 전체적으로 ㅁ자형 모습이며, 재사 건축에서 벗어나 절 암자와 유사한 구성법을 보이고 있다. ○○○을 중심으로 오른쪽 건물은 재사 참석자들이 사용하는 공간이고, 왼쪽 건물은 대문에 붙어 있는 집채이다. 이곳은 전체적으로 절 건물에 쓰이는 재료로 사용한 듯한 암자형 재실로 오래된 건축 기법들을 잘 유지하고 있다.","a":"영주 평은리 양지암","c":"시도민속문화유산","nc":"","r":"경상북도","s":"영주시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658927.jpg"},{"q":"전북특별자치도 완주군 동상면 ○○○의 거대한 자연 암벽에 새겨진 석불좌상이다. 민머리에 상투 모양의 머리묶음이 큼직하게 솟아 있고, 풍만한 얼굴에는 눈·코·입이 큼직하게 새겨져 있다. 넓은 가슴, 큼직한 무릎 등이 당당하고 듬직해 보인다. 양 어깨를 감싸고 있는 옷은 두터운 편이며, 평행의 옷주름이 신체 전반에 새겨져 있다. 오른손은 아래로 내리고, 왼손은 배에 대고 있는 모습이다. 거구의 불상이면서도 머리와 상체의 두드러진 양감 표현은 균형감이 있으며 박진감이 느껴진다.","a":"수만리마애석불","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"완주군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639486.jpg"},{"q":"현재 월정사 성보박물관에 전시되어 있는 이 불상은 원래 강원특별자치도 원주시 판부면 금대리에 있는 ○○○에 봉안되어 있던 것이다. 불상은 소라 모양의 머리카락 위에 자그마한 정상계주와 반달형의 중심계주가 뚜렷하다. 입이 자그마하고 콧마루가 눈썹사이에서부터 돌출되고 있으며, 귀바퀴가 서있고 귓볼에 이르기까지 밖으로 휘어져 있다. 백호(白毫)는 코뿌리에 붙어 작게 돌출되어 있다. 상체는 다소 긴 듯하지만 무릎의 넓이가 넓어 안정감이 있는 모습이다. 양 어깨를 감싸고 있는 옷은 두터우며, 배 앞에서 ＇W＇자형을 그리고 있고, 가슴에는 내의가 수평으로 가로질러져 있다.","a":"영원사목불좌상및복장유물","c":"시도유형문화유산","nc":"","r":"강원특별자치도","s":"평창군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638204.jpg"},{"q":"현재 敬天廟에 모셔져 있는 이 ○○의 인물은 임금이 쓰는 어관(冕旒冠)을 쓰고 있으면서 한편으로는 신하의 예를 갖추는 笏을 양손에 쥔 형태로 묘사되어 있어 인물의 着衣에 관해서는 추후 再考가 필요할 것이다. 그러나 신라의 마지막 임금으로서 고려에 遜國했던 까닭에 신라 임금의 모습과 고려에 대한 신하의 예를 동시에 갖추고 있는 모습으로 동시에 묘사된 것으로 추정된다.","a":"하동 경천묘 경순왕 어진","c":"시도유형문화유산","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1643089.jpg"},{"q":"대구의 ○○○○는 고려 명종 22년(1192)에 창건되었으며 불상은 ○○○○ 대웅전 뒤쪽 땅속에서 발견된 것으로 완전한 형태로 남아있다. 얼굴은 온화한 인상으로 단정한 자태를 보여주고 있으며, 왼손에는 보주(寶珠)를 들고 오른손은 무릎 위에 올려 손끝을 아래로 향하고 있다. 양쪽 어깨를 감싸고 있는 옷은 주름의 조각선이 가늘고 약하게 형식화되어 시대가 뒤짐을 보여준다. 머리의 형태나 손에 든 보주 등으로 미루어 보아 지옥의 중생을 구제한다는 ○○○○을 형상화한 것으로 보이며, 단정한 자태와 온화한 인상 등으로 통일신라 후기에 만들어진 작품으로 추정된다.","a":"북지장사석조지장보살좌상","c":"시도유형문화유산","nc":"","r":"대구광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636872.jpg"},{"q":"마을에 무너져 흩어 있던 것을 1968년에 다시 쌓은 탑으로, 일명 ‘봉상사(奉常寺)탑’이라고도 한다. 탑은 1층 기단(基壇) 위에 3층의 탑신(塔身)을 올린 모습이다. 기단은 각 면의 모서리와 가운데에 기둥을 새겼는데, 이는 목조건축의 기둥을 모방한 것이다. 탑신부의 몸돌은 2 ·3층에 비해 1층이 커보이며, 각 모서리마다 기둥 모양을 가지런히 새겼다. 지붕돌은 밑면에 4단의 받침을 두었고, 처마는 직선을 이루고 있다. 꼭대기에는 머리장식을 받치던 네모난 받침돌만이 남아 있다.","a":"하동 탑리 삼층석탑","c":"시도유형문화유산","nc":"","r":"경상남도","s":"하동군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641677.jpg"},{"q":"신흥사의 옛 터에 있었던 3층 석탑으로, 탑을 품었던 절은 신라 신문왕 때 원효대사가 창건하였던 곳이나, 현재는 터만 남아 당항리 마을로 변해버렸다. 절터에 마을이 들어서면서 탑을 몇 차례 옮기다 1957년 마을 주민들이 지금의 자리로 옮겨 놓았는데, 옮길 때마다 각 부분의 돌들이 없어지거나 훼손되었다. 현재는 기단부(基壇部)가 모두 없어지고 탑신(塔身)의 1층 몸돌과 1·2·3층 지붕돌, 머리장식인 보개(寶蓋:뚜껑모양의 돌), 보륜(寶輪:수레바퀴모양의 돌) 만이 남아 있다.","a":"남해 신흥사지 삼층석탑","c":"문화유산자료","nc":"","r":"경상남도","s":"남해군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663884.jpg"},{"q":"경상북도 의성군 구천면 ○○○의 미륵당 안에 모셔져 있는 석불이다. 민머리 위에 솟아 있는 상투 모양의 머리묶음은 큼직하고, 얼굴은 눈·코·입에 훼손이 심하여 윤곽이 뚜렷하지 않다. 옷은 양쪽 어깨를 감싸고 있으며, 옷주름은 V자 모양으로 등뒤까지 연결되어 있다. 오른손은 땅을 향하여 아래로 내려져 있고 왼손은 약그릇 같은 것을 받치고 있는 것으로 보아 약사여래불을 표현한 것으로 보인다. 전체적으로 머리·손·발 등이 크게 표현되어 균형감이 없고 둔탁한 조각수법으로 보아 고려시대에 만들어진 것으로 추정된다.","a":"의성내산리석불좌상","c":"문화유산자료","nc":"","r":"경상북도","s":"의성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663109.jpg"},{"q":"이 불상은 ○○○ 대웅전의 왼쪽 대지에 봉안되어 있는 불상으로서, 불상의 왼쪽에는 거대한 돌로 만든 대좌가 따로 놓여있다. 화강암으로 이루어진 불상은 모두 4조각으로 떨어져 현재 목 부분과 몸통 중간부분을 시멘트로 붙여놓았다. 불상의 높이는 262㎝, 어깨폭은 74㎝에 달하고, 대좌(높이 53㎝)까지 합하면 불상의 총높이가 3m가 넘는다. 얼굴은 귀 옆부분이 마멸되었고 코 부분이 떨어져 나갔는데, 머리에는 높은 보관(寶冠)을 쓰고 있다.","a":"정혜사석조보살입상","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"정읍시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639722.jpg"},{"q":"이상도(1773∼1835) 선생이 지은 살림집이다. 원래는 조선 순조 33년(1833) 석보면 주남리에 세운 것을 선생의 후손인 이돈호(1869∼1942)가 지금 있는 자리로 옮긴 것이다. 이돈호는 3·1운동 때 독립운동에 가담한 바 있으며 그의 조카인 병각은 조지훈·오일도·조세림과 함께 항일애국시인으로 활약하였다. 건물 이름은 이상도 선생의 첫째 아들인 기찬의 호를 따른 것이며 제사를 지내는 곳과 사당 2채로 구성되어 있다.","a":"유우당","c":"문화유산자료","nc":"","r":"경상북도","s":"영양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663051.jpg"},{"q":"충청남도 홍성군 홍성읍 내법리 용주사에 있는 ○○○○이다. 원래는 홍성읍 대교리 ○○○에 있었던 것으로 1975년 이곳으로 옮겨 왔다. 화강암으로 만든 이 불상은 머리의 조각이 분명하지 않고, 상투 모양의 머리묶음도 작은 편이다. 둥근 얼굴에서는 사실미가 흐르며, 직선으로 뻗어나간 두 눈은 진주로 눈동자를 끼웠던 흔적이 보인다. 목에는 3개의 주름인 삼도(三道)가 있으며, 옷주름은 평행의 단을 이루고 있는데 이는 도피안사 철조비로자나○○○의 수법과 비슷하다. 불상이 앉아있는 대좌(臺座)에는 연꽃잎이 간략하게 표현되어 있다.","a":"광경사지석불좌상","c":"문화유산자료","nc":"","r":"충청남도","s":"홍성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661157.jpg"},{"q":"○○○○○는 ○○○ 정상에 자리하고 있는 ○○터로 주정산, 것대산 ○○ 등과 함께 충북에 남아 있는 23개 내지○○ 중의 하나이다. ○○○○○와 더불어 고려시대 몽고항쟁시 승전지인 기념물 제110호인 ○○○○○성이 남아 있다. ○○는 조선시대 호국군사통신 수단의 모습을 알 수 있는 귀중한 자료로 주정산-○○○-마산-음성 가섭산 방향으로 연결된다. 발굴조사 결과 5기의 연조(烟竈, 봉화를 피우기 위해 설치한 아궁이)와 주거지 등이 찾아 졌다.","a":"충주 대림산 봉수","c":"시도기념물","nc":"","r":"충청북도","s":"충주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2019020713413600.jpg"},{"q":"조선 후기의 실학자 서계 ○○○ 선생이 관직에서 물러나 후학을 양성하고 저술 활동을 하던 곳에, 후손들이 건립한 것이다. ○○○은 40세에 관직을 그만두고 이곳에서 학문연구와 후진 양성에 힘썼다. 또한 직접 농사를 지으면서 체험한 것을 토대로 그의 대표적인 농학서 『색경』을 저술했다. 이 가옥은 본래 안채와 안사랑, 바깥사랑, 행랑채를 갖춘 규모 있는 사대부 주택이었으나, 한국전쟁 때 대부분 소실되고 현재는 바깥○○○만 남아있다.","a":"서계박세당사랑채","c":"문화유산자료","nc":"","r":"경기도","s":"의정부시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660147.jpg"},{"q":"○○○는 신라 진흥왕 28년(567)에 의신이 처음 지었으며, ○○ 근교에서 가장 오래된 유서 깊은 절이다. ○○○○은 조선 초기에 지은 건물로 선조(재위 1567〜1608년)대에 수리하였고, 1683년(숙종 9)에 중건되었으며 1872년에 다시 지었다. 앞면 3칸·옆면 2칸의 규모이며, 지붕 옆면이 사람 인(人)자 모양인 소박한 맞배지붕집이다. 지붕 처마를 받치면서 장식을 겸하는 공포는 기둥 위와 기둥 사이에도 배치된 다포식 건물이다. 안에는 석조이존병립여래상과 지장보살상, 삼존불상 등이 모셔져 있다.","a":"청주 보살사 극락보전","c":"시도유형문화유산","nc":"","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638470.jpg"},{"q":"문적의 내용은, 노소재 문집 본초을중 일책으로 체제는, 세로 24cm 가로 14.2cm의 한지 장본, 심침장법 총 45정행초서로 평균 매면 8행, 1행 16자이다. 내용은, 소재선생이 을사 사화로 순천, 진도 등지로 유배되던 1548년부터 수년 간 유배지에서 쓴 시부를 수록하였는데, 무신 정월 난고 21수를 비롯하여 이월난고 40수와 옥주 2천언 등이다. 이는, 소재 문집 본초 전 7권 중 유일하게 남은 을중본이다. 소재 노수신 선생의 자는 과회요 호는 소재며 벼슬은 영의정, 시호는 문간공이다. 선생의 학문은, 탄수.","a":"노소재문적","c":"시도유형문화유산","nc":"","r":"경상북도","s":"상주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640725.jpg"},{"q":"○○○○○ 내부 좌측 벽면에 걸려 있는 ○○○○○는 역시 ○○○○○에 모셔져 있는 석가영산회상도 및 제석신중도와 함께 1882년에 제작되었다. 크게 상․하단으로 나누어 진 화면의 윗부분에는 가운데 천장보살(天藏菩薩)을 중심으로 좌우에 각각 앉아있는 모습의 지지보살(持地菩薩)과 지장보살(地藏菩薩)을 배치한 삼장보살이 중심을 이루고 있고, 그 주위로 천부중(天部衆)들이 배치되어 있다. 하단부는 새 깃털 장식 투구를 쓴 동진보살(童眞菩薩)과 악기를 연주하는 천녀(天女)들의 무리를 중심으로 좌우에 신장(神將) 무리들이 3단으로 열을 지어 질서정연하게 묘사되어 있다.","a":"범어사 대웅전 삼장보살도","c":"시도유형문화유산","nc":"","r":"부산광역시","s":"금정구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636733.jpg"},{"q":"약 4등신의 신체 비례를 보이는 고려 전기 석조(石造) ○○○○으로 현재 ○○○ 산100-35번지 내 ‘자씨각(慈氏閣)’이라는 전각(殿閣) 안에 모셔져 있다. 얼굴은 장방형으로 뺨에 살이 올라 여성적이고 온화한 인상을 준다. 이마는 좁고 이목구비가 중앙으로 몰려 있는데 이러한 얼굴 표현은 나말여초의 불․보살상에 많이 보이는 형태이다. 보계(寶髻)가 높게 솟아 있고, 보계와 머리 중간에 정면과 좌우 측면에 장식이 달린 보관(寶冠)을 착용하고 있다.","a":"진관동 석 보살입상","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"은평구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636556.jpg"},{"q":"청량산 중턱에 위치한 ○○○는 백제 의자왕 4년(644)에 자장이 지은 절이다. 당나라의 청량산에서 수행을 하고 돌아온 자장은 우연히 이곳을 지나다가 취령산이 청량산과 비슷하다 느끼고, 이곳에 절을 지은 후 ○○○라 하였다. ○○○○○은 조선 영조 40년(1764) 신화화상이 이 절을 다시 지을 때, 이곳에서 발견된 문수보살상을 모셔두기 위해 지은 법당건물이다. 석조문수보살상은 상체가 큰 불상으로 좌대와 하반신 일부가 땅에 묻혀있는 것이 특색이다.","a":"문수사문수전","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"고창군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639446.jpg"},{"q":"이 비는 조선 시대 1563년(명종18년)～1633(인조11년) 동안 조정의 문신으로 활약한 우복(愚伏)선생의 유적을 적은 비이다. 이 비석은 당초 도로 입구에 세워졌으나 지금은 주위가 개간되어 논 중간에 위치하고 있다. ○○○ 선생의 증손 정석교(鄭錫僑)가 경상감사 이명준(李命俊)으로부터 기증을 받은 남포석(藍浦石)에 비각 작업을 하고 세우지 못하던 것을 현손 정주원(鄭?源)이 음기(陰記)를 찬(撰)하고 1758년에 6대손 정종로(鄭宗魯)에 의하여 건립되었다. 비석 규모가 장대하고 글씨 보존이 전체적으로 양호하다.","a":"우복정경세신도비","c":"시도유형문화유산","nc":"","r":"경상북도","s":"상주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641055.jpg"},{"q":"조선 후기의 대표적인 실학자이며 서예가인 추사 ○○○의 옛 집이다. 안채와 ○○○ 2동짜리 건물로 조선 영조(재위 1724∼1776)의 사위이자 ○○○의 증조할아버지인 김한신에 의해 지어진 집이라고 한다. 건물 전체가 동서로 길게 배치되어 있는데, 안채는 서쪽에 있고 ○○○는 안채보다 낮은 동쪽에 따로 있다. ○○○는 남자주인이 머물면서 손님을 맞이하던 생활공간인데, ㄱ자형으로 남향하고 있다. 각방의 앞면에는 툇마루가 있어 통로로 이용하였다. 안채는 가운데의 안마당을 중심으로 사방이 막힌 ㅁ자형의 배치를 보이고 있다.","a":"김정희선생고택<안채.사랑채>","c":"시도유형문화유산","nc":"","r":"충청남도","s":"예산군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639069.jpg"},{"q":"영·정조 대의 무신 ○○○ 장군의 생가다. ○○○은 1721년에 원삼면 문촌리에서 태어났으며, 수도 방위에 큰 역할을 담당하였다. 고택 주변으로 묘소, 신도비, 정자터 등이 남아있으며, 묘역은 향토유적 제4호로 지정되었다. 이 가옥은 안채와 사랑채, 행랑채로 구성되어 있다. 그리고 안채 지붕에 있는 기와 명문에 ‘乾隆十八年癸酉日造作(건륭십팔년계유일조작)’이라고 기록되어 1753년에 건축한 것으로 추정된다.","a":"용인이주국장군고택","c":"문화유산자료","nc":"","r":"경기도","s":"용인시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660156.jpg"},{"q":"서방 극락세계를 주관하는 아미타부처를 묘사한 불회도로, 화면 가운데 주불인 아미타부처를 크게 배치하였다. 아미타불은 양어깨를 모두 덮고 있는 옷을 입고, 오른발을 왼무릎에 얹고 있는 길상좌(吉祥坐) 모습이다. 그림의 맨 위부분에는 아미타부처의 말씀을 듣기 위해 모인 여러 성중(聖衆)의 무리가 표현되어 있으며 그 아래로는 흰옷(白衣)을 걸친 관세음보살을 위시한 아미타 8대 보살과 불법을 수호하는 사천왕상이 있다. 이 그림은 ○○○ 약사불회도(경상남도 유형문화유산)와 전반적으로 비슷한 구도와 인물의 형태, 색채를 보여주고 있어 동일 작가에 의해 그려진 것으로 생각된다.","a":"고성 운흥사 아미타불회도","c":"시도유형문화유산","nc":"","r":"경상남도","s":"하동군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642319.jpg"},{"q":"이 가옥은 숙종12년(1686)에 장사랑을 지낸 산수정 정형초가 건립한 것으로 현재의 건물은 1924년에 중수한 것임. 건물구성은 안채, 사랑채, 대문채 등으로 되어 있고 안사랑채는 헐리고 일부 변경된 구조로 남아있음. 건물배치는 경사지에 기단을 높게 축조하여 대지의 안쪽 높은 곳에 안채, 바깥쪽 낮은 곳에 사랑채를 배치하였음. 안채는 우리나라 남부지역에서는 보기드문 \"ㄷ자형\"평면의 3량구조 맞배지붕의 홑처마이며 정면 4칸, 측면 2칸의 \"ㅡ자형\"평면에 양끝 협칸을 앞으로 돌출시켜 \"ㄷ자형\"평면외부에 마루를 두르고 계자난간을 설치하였음.","a":"거창무릉리정씨고가","c":"시도유형문화유산","nc":"","r":"경상남도","s":"거창군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642160.jpg"},{"q":"○○○ 사역 서쪽 언덕에 위치한 부도는 전각형에 편구형 탑신을 지닌 전형적인 조선후기 부도의 양식을 띠고 있다. 기단부의 하대석과 중대석, 상대석을 비롯하여 구형의 탑신과 팔각의 전각형 옥개석 그리고 상륜을 모두 갖춘 완형의 부도이다. 옥개석은 8각의 지붕형태로 묘사되었는데, 처마가 매우 두텁게 표현되어 둔중감을 준다. 처마의 전각부 2곳에는 원공이 남아있으며, 이는 풍경과 같은 부착물을 달았던 것으로 보인다. ○○○의 창건주인 백양대사의 탑이라고는 전해지나, 신라시대 부도와는 양식적으로 맞지는 않다.","a":"백양사 석조부도","c":"시도유형문화유산","nc":"","r":"울산광역시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637297.jpg"},{"q":"본관이 청송인 송호 심자광의 살림집이다. 심자광은 조선 선조 25년(1592)에 태어나 1625년에 무과에 합격하여 여러 관직에 있었다. 사랑채에 적힌 기록에 따르면 조선 인조 12년(1634)에 건물을 지었다고 한다. 가옥 안에는 안채, 사랑채, 행랑채, 곳간채, 방앗간(화장실)이 남아 있는데 안채는 앞면 5칸·옆면 2칸 규모이고 사랑채는 앞면 5칸·옆면 2칸 규모이다.","a":"합천 대목리 심씨고가","c":"문화유산자료","nc":"","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664291.jpg"},{"q":"나지막한 산이 병풍처럼 둘러진 마을 가운데에 남향으로 자리잡은 집이다. 전면 4칸, 측면 2칸의 ‘ㄱ’자 함경도형 온돌 중심 겹집에 마루가 수용된 형태로, ‘도광 5년(1825)’과 ‘건륭 27년(1762)’의 명문기와가 발견되었으며, 확실한 건립연대는 미상이다. 홑처마 팔작기와지붕 형태의 가옥으로 대대로 함평 이씨가 살았으나 삼십년 전 현 소유자가 매입하여 생활하고 있으며, ‘회령댁’, ‘방앗간댁’으로 불리고 있다. 평면은 부엌과 본채 지붕에서 이어져 내려와 돌출된 마구간을 두고서 전열에 우물마루 2칸과 사랑방이 있고 후열에는 안방, 아랫방, 뒷사랑이 있다.","a":"속초김근수가옥","c":"문화유산자료","nc":"","r":"강원특별자치도","s":"속초시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660449.jpg"},{"q":"불상 안에서 발견된 묵서(墨書)를 통해 조선 영조 6년(1730)이라는 조성연대를 알 수 있어 같은 시기 불상제작의 기준이 되는 작품이다. 다소 경직된 신체 측면과 고개를 아래로 숙인 자세, 치마와 같은 상의(裳衣)의 단처리 등에서 조선 후기 양식을 느낄 수 있다. 전반적으로 안정되고 균형잡힌 불상의 몸체와 유연한 옷주름의 흐름, 그리고 온화한 얼굴이 돋보이는 작품이다. 특히 한쪽 무릎을 세우고 앉은 윤왕좌(輪王座)의 자세를 취하고 있는 점이 특이하다.","a":"내원정사 목조관음보살좌상","c":"시도유형문화유산","nc":"","r":"부산광역시","s":"서구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636687.jpg"},{"q":"두방암에 자리하고 있는 탑으로, 원래 법륜사에 있던 것을 임진왜란으로 절이 없어져 이곳으로 옮겨 놓은 것이다. 푸른빛이 도는 점판암을 이용해 만든 것으로 일명 청석탑(靑石塔)이라 한다. 기단부(基壇部)의 바닥돌은 탑을 옮겨 세울 때 새로 시멘트로 만들었고, 각 기단의 맨윗돌에는 연꽃을 새겨 장식하였다. 탑신부(塔身部)는 부서지기 쉬운 돌의 특성상 상자모양의 몸돌과 얇은 지붕돌을 교대로 높게 쌓아 올렸다. 새로 만든 바닥돌이 기단의 폭보다 좁고 높아 전체적인 균형이 맞지 않고 불안정하다.","a":"진주 두방사 다층석탑","c":"시도유형문화유산","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641827.jpg"},{"q":"○○○○은 조선 선조 때 문신이며 학자인 학봉 김성일(鶴峯 金成一, 1588~1593)을 추모하기 위해 세워졌다. 김성일은 퇴계 이황의 제자로 1568년 문과급제 후 이조·병조의 좌랑, 함경도 순무어사, 대사성, 홍문관 부제학 등을 역임하였다. 임진왜란 당시에는 경상도 초유사, 경상좌·우도 관찰사 등을 지내면서 곽재우(郭再祐) 등의 의병활동을 적극 지원하고 주선하였으며, 관군과 의병 사이를 조화시켜 전투력을 강화하는 등 국난극복에 혼신의 힘을 다하다가 진주성에서 순직하였다.","a":"안동 임천서원","c":"시도기념물","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2017042810274300.jpg"},{"q":"충청남도 태안군 청계산 기슭에 위치한 죽사(竹寺)의 절터에 있으며 전체 높이는 1.03m이다. 옷은 양 어깨를 감싸 입고 있으며, 양 발을 무릎 위로 올려 발바닥이 하늘을 향한 자세로 앉아 있다. 오른손은 무릎 위에 올려 손끝이 땅을 향하고 있으며, 왼손은 왼쪽 무릎 위에 올려 손바닥이 위로 향하게 했다. 불상의 뒤에는 불꽃무늬로 장식한 배(舟)모양의 광배(光背)가 있는데, 그 안쪽에 머리광배와 몸광배를 2줄의 굵은 선으로 구분하였다. 머리광배에는 연꽃을 겹으로 새겼고, 머리광배와 몸광배가 구분되는 좌우에는 구름무늬 위에 비천상(飛天像)을 새겼다.","a":"몽산리석가여래좌상","c":"시도유형문화유산","nc":"","r":"충청남도","s":"태안군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639209.jpg"},{"q":"강원특별자치도 홍천군 홍천읍 진리의 도로변에 있는 불상으로 전해 내려오는 유래나 전설이 없다. 목 위로 머리 부분이 떨어져 나간 것을 뒤에 마을 사람들이 보완하였다. 높이 2.28m, 어깨 너비 0.8m이며 손모양은 오른손을 가슴에 대고 왼손은 배에 붙이고 있는 모습이다. 양 어깨를 감싸고 있는 옷은 좌우대칭을 이루고 있는데, 몸 전체를 가리고 발등만 노출시켰다.","a":"홍천진리석불","c":"문화유산자료","nc":"","r":"강원특별자치도","s":"홍천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660331.jpg"},{"q":"○○○ 무우전 뒷편인 북암에 오르는 길목에 자리하고 있는 비로, 정유재란으로 불에 타버린 절을 약휴대사의 노력으로 힘들게 복원한 후 그 내용을 기록해 놓은 것이다. 비는 높직한 거북받침돌 위로, 비몸을 세우고 머릿돌을 올린 모습이다. 거북받침의 머리는 용의 머리화 되었는데 여의주를 물고 있지 있으며, 목이 매우 짧아 잔뜩 웅크리고 있는 듯하다. 등은 선명하게 새긴 육각무늬로 덮혀있고, 중앙에 네모난 비좌(碑座)를 마련하여 비를 꽂아두도록 하였다. 머릿돌은 밑면에 연꽃을 새겼고, 윗면에는 서로 엉켜 꿈틀거리는 두 마리의 용을 사실적으로 표현하였다.","a":"선암사중수비","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"순천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639932.jpg"},{"q":"이 책은 ○○○ 신앙의 중심인 적멸보궁의 관리를 위해 같은 사찰 안에서도 암자와 암자 사이에 부동산을 옮긴 것을 보여주는 문건이며, 당시 사찰 승려들의 명단도 싣고 있어 조선후기 도내 사찰의 현황 등을 살필 수 있다. 조선 순조 25년(1825)에 ○○○ 서대에 소속된 논을 중대로 영원히 옮기면서 그 목록을 작성하였다. 그리고 부처의 법신이 상주하는 적멸보궁의 쇠락을 안타까이 여겨 스님들이 앞장서 시주자를 모아 기부한 내역을 적은 ○○○적멸보궁불량연기와 이와 같은 취지에 동참한 인근 사찰과 소속 승려들의 명단을 수록하였다.","a":"오대산중대불량계원수복문","c":"문화유산자료","nc":"","r":"강원특별자치도","s":"평창군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660631.jpg"},{"q":"조선 현종 때, 대동법을 주장하여 시행토록 한 김육 선생의 공을 기리기 위해 세운 비이다. 김육(1580∼1658)은 실학사상을 바탕으로 제도개혁을 추진한 조선 후기의 문신이다. 선조 38년(1605) 과거에 급제하여 관직에 나아가 충청도 관찰사, 도승지, 우의정, 좌의정, 영의정 등을 지냈다. 그는 특히 각 지방의 토산물을 바치게 하는 공물법을 폐지하고 쌀과 포로 대신하는 대동법의 실시를 주장하였는데, 이 대동법의 실시로 농민의 부담을 줄이고, 국가의 재정도 나름대로 확보하게 되었다. 비는 거북받침 위에 비몸을 세우고 머릿돌을 얹었다.","a":"김육비","c":"문화유산자료","nc":"","r":"충청남도","s":"아산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661294.jpg"},{"q":"○○○는 백제 무왕 41년(640)에 자장율사가 세웠다고 전한다. 절 경내에는 ○○○을 비롯하여 대웅전, 영산전, 대광보전, 홍성루 등 많은 건물이 남아 있다. ○○○은 절을 세운 이나, 훌륭한 스님들의 영정을 모신 곳으로, 승려들에게 국사(國師)라는 최고의 승려가 되기까지 많은 수행과 노력이 필요하다는 것을 일깨워주기 위해 세운 것이다. 조사전·조사당·국사전이라고도 한다.","a":"마곡사국사당","c":"문화유산자료","nc":"","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660975.jpg"},{"q":"이 ○○○는 1883년에 30여 명에 달하는 많은 상궁들의 시주에 의해 제작된 불화로서 대허 체훈(大虛 軆訓)과 천기(天機), 수일(守一), 태삼(台三) 등이 그린 것이다. 현재는 ○○○ 대웅전 향좌측벽에 봉안되어 있는데, 가로로 긴 화면의 상단에는 칠여래가 합장을 한 채 나란히 서 있으며, 좌측에는 아미타삼존(阿彌陀三尊) 일행이 구름을 타고 내영(來迎)하는 모습과 왕후장상(王侯將相), 선왕선후(先王先后), 북채를 든 뇌신(雷神), 우측에는 지장삼존(지장보살･도명존자･무독귀왕)과 인로왕보살(引路王菩薩)이 내영하는 모습이 묘사되어 있다.","a":"개운사 감로도","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"성북구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2593253.jpg"},{"q":"(1) 이 비석은 금헌(琴軒) ○○○의 묘소 약 50미터 정도 아래, 예전 길이 있었던 곳에 새워진 신도비 형태의 비석이다. (2) ○○○은 자가 희강(希剛), 본관이 벽진(碧珍)이며 한훤당(寒暄堂) 김굉필(金宏弼)의 문인이다. 연산군 원년(서기 1495년)에 생원시에 장원으로 입격하였고, 연산군 8년(서기 1502년)에 문과에 급제하여 홍문관 교리로 있던 중 갑자사화에 연루되어 거제도로 유배당하였다. 거기서 함흥으로 달아나 변성명을 하고 양수척(楊水尺)의 사위가 되어 지내다가 중종반정으로 조정에 돌아오게 되었다.","a":"창녕 이장곤 묘도비","c":"문화유산자료","nc":"","r":"경상남도","s":"창녕군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1665716.jpg"},{"q":"탱화란 천이나 종이에 그린 그림을 족자나 액자의 형태로 만들어 걸어두는 불화의 한 종류로, 보통 사찰의 전각 안에 모셔둔 본존상 뒤에 걸어두는 후불화를 이른다. 이 ○○○○○는 ○○○ 대적광전 내에 있는 비로자나불의 후불탱화로, 비단 바탕에 채색하였으며, 세로 278㎝, 가로 263㎝의 크기이다. 석가가 영취산에서 법화경을 설하고 있는 장면을 그린 것으로, 중앙의 석가불을 중심으로 좌우에 열보살과 사천왕 등을 배치하였다. 중앙의 석가불은 오른쪽 어깨를 드러낸 옷을 걸치고 있으며, 손은 항마촉지인을 하고 있다. 붉은색을 칠한 옷은 각종 무늬를 두어 화려하게 장식하였다.","a":"홍천수타사영산회상도","c":"시도유형문화유산","nc":"","r":"강원특별자치도","s":"홍천군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638176.jpg"},{"q":"경상북도 의성군 안사면 안사리에 있는 불상으로, 불신과 대좌(臺座), 광배(光背)를 모두 갖추고 있으나 대좌의 중대석이 없어진 상태이다. 하나의 돌에 불신과 광배를 높게 돋을새김한 이 불상은 약간 움츠린 자세이며, 하체에 비해 상체가 짧고 불균형한 편이나 형태상의 구성미가 보인다. 왼쪽 어깨를 감싸 흐르고 있는 옷자락은 평행선으로 새겨져 있다. 타원형의 광배와 대좌에는 연꽃잎이 새겨져 있다. 불상의 주위에 석탑재와 기와조각들이 쌓여 있으며, 조각수법으로 보아 고려시대에 만든 것으로 추정된다.","a":"의성안사동석조여래좌상","c":"시도유형문화유산","nc":"","r":"경상북도","s":"의성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640631.jpg"},{"q":"울릉도 내에서 가장 많은 무덤이 밀집하여 분포한 무덤들이다. 완만한 경사면에 40여기가 분포하고 있다. 무덤의 형태는 기단을 만들고 가운데 직사각형의 돌방(석실)을 만들어, 시체를 넣고 그 위에 돌을 이용하여 봉분을 만든 이른바 석총으로 삼국시대의 것으로 생각된다. ○○○ 포동무덤들은 울릉도 지역에서만 볼 수 있는 특징적인 형태를 가지고 있는 석총으로 이 지역 무덤연구에 중요한 곳이다.","a":"울릉현포동고분군","c":"시도기념물","nc":"","r":"경상북도","s":"울릉군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654520.jpg"},{"q":"소주 가씨인 가유약·가상·가침 등 삼대를 기리기 위한 사당이다. 가유약은 중국의 이름높은 장군으로, 소주 가씨의 중시조(쇠퇴한 가문을 일으킨 조상)이다. 그는 임진왜란(1592)이 일어나자 이여송과 함께 조선에 와서 왜군을 무찌르는데 큰 공을 세우고 돌아갔다. 얼마 후 선조 30년(1597) 정유재란이 일어나자 아들과 손자인 가상장군, 가침을 데리고 다시 조선에 오게 되었다. 가유약은 가침을 두고 가상과 부산에서 왜군과 싸우다 함께 전사하였다. 가침은 원수를 갚으러 전장으로 가려 했으나 주위의 만류로 시체를 거두어 장사하고 묘를 모셨다.","a":"숭의사","c":"문화유산자료","nc":"","r":"충청남도","s":"태안군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661370.jpg"},{"q":"경상북도 경주시 배동 ○○○○에 있는 높이 10m가량 되는 바위에 새겨진 앉아 있는 모습의 여래상이다. 이곳은 신라 아달라왕, 신덕왕, 경명왕의 큰 무덤이 있어서 ○○○○이라고 불리는 곳이다. 서쪽을 향하고 있는 불상은 몸은 모두 선으로 그은 듯이 새기고 얼굴만 도드라지게 표현한 독특한 조각수법을 보이고 있다. 이 불상은 고려시대에 새긴 것으로 추정되며 이런 유형의 불상을 연구하는데 중요한 위치를 차지하고 있다.","a":"삼릉계곡선각여래좌상","c":"시도유형문화유산","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640595.jpg"},{"q":"고려 원종 원년(1260) ○○○를 크게 중창한 바 있고, 한때 이곳에 머물렀던 ○○○○의 사리탑이다. ○○○○는 고려 고종 2년(1215)에 태어나 충열왕 12년(1286) 72세로 입적할 때까지 조계산 송광사에서 그 이름을 떨쳤다. 그의 사리탑은 ○○○ 극락전 오른쪽에 자리하고 있으며, 기단부(基壇部)·탑신(塔身) 등이 모두 8각을 이루고 있다. 기단부는 연꽃무늬를 새긴 아래받침돌 위로, 활짝핀 연꽃모양의 윗받침돌이 바로 놓여 있는데, 가운데받침돌을 생략한 것인지 잃어버린 것인지는 정확히 알 수 없다.","a":"대원사자진국사부도","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"보성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639861.jpg"},{"q":"호지마을에 있는 옛집으로 순조 30년(1830)에 지은 것이라 전한다. 대문을 들어서면 마당을 사이에 두고 ㅁ자형 정침이 자리잡고 있다. 중문 오른쪽에 있는 사랑채는 왼쪽부터 사랑마루와 사랑방·감실 순으로 배치하였다. 마루 앞면과 왼쪽 옆면에는 판벽을 설치하여 마루방을 마련하였고, 앞면에는 반칸 너비의 툇마루를 두었다. 사랑마루 옆면에서 오른쪽 담장까지는 앞마당 사이에 담장을 설치하고 문을 내어 별도의 공간을 이루었다. 전체 배치는 서향이지만 사랑채는 남향으로 두어 이 마을 특유의 배치 유형을 따르고 있다.","a":"영해경주댁","c":"문화유산자료","nc":"","r":"경상북도","s":"영덕군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663284.jpg"},{"q":"경상남도 ○○시 대방동 각산의 정상에는 횃불과 연기를 이용해 소식을 전하는 옛 통신수단인 봉화대가 옛 모습대로 남아있고, 서쪽 등성이에 ○○○○이 남아있다. 고려 원종(재위1259∼1274) 때에 성과 봉화대를 만들고, 줄항터에는 구라량영의 본거지를 두어 이곳을 지켰다. 고려 말에 사량도로 영을 옮기고 난 후, 이곳이 무방비상태로 되자 왜구가 침입하여 성에 불을 질르기도 했다. 그후 각산은 봉화대가 자리하는 곳이 되었으며, 봉수는 남쪽으로 대방산, 서쪽으로 곤양의 우산봉수, 북쪽으로 ○○ 안점봉수와 연결되었다.","a":"사천 각산산성","c":"문화유산자료","nc":"","r":"경상남도","s":"사천시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664038.jpg"},{"q":"○○○○ 제4대 교장이었던 ○○○이 블레어 선교사가 미국에서 염출한 자금으로 1931년 건립한 건물이다. 건물의 설계는 ○○○이, 건축공사는 ○○○ 교장의 감독하에 학생들이 기초공사를 하고, 상부공사는 중국인 조적공과 일본인 목수들이 담당하였다 한다. 이 건물은 건축 당시 붉은 벽돌조 2층이었으나 1964년 3층으로 증축하면서 건물 내부에 철근콘크리트 기둥을 세우고 바닥을 슬라브로 개조하였다.","a":"계성학교핸더슨관","c":"시도유형문화유산","nc":"","r":"대구광역시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636929.jpg"},{"q":"칠산 남단의 해발 90m ~100m 정도의 정상부 주변에 두 곳으로 나누어져 형성되어 있는데 북쪽에는 10여기의 큰 수혈식 석곽묘군이, 남쪽에는 수십기의 작은 수혈식 석곽묘와 목곽묘가 혼재해 있음이 1987년 경성대학교 박물관의 발굴조사에 의해 밝혀졌다. 토기류, 철기류, 장신구류 등 많은 유물들이 출토되었으며 3세기 후반부터 6세기까지의 가야묘제나 유물의 변천을 잘 보여주는 유적이다.","a":"김해칠산동고분군","c":"시도기념물","nc":"","r":"경상남도","s":"김해시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1655365.jpg"},{"q":"조선 전기의 문신인 송간(1405∼1480)을 중심으로 송대립·송심·송순례 등의 여산 송씨와 매월당 김시습 등 11분의 위패를 모시고 있는 사당이다. 송간은 세종, 문종, 단종의 세 임금을 섬겨 벼슬이 가선대부까지 이르렀다. 1455년 왕의 명령으로 남방을 순시하고 돌아오는 길에 단종이 영월로 쫓겨갔다는 소식을 듣고 영월에 가서 단종에게 그의 임무가 끝났음을 알렸다. 그 뒤 바로 고향인 여산에 가 있다가 단종이 죽었다는 소식을 듣고 깊은 산 속에서 3년 상을 마치고 통곡하며 산천을 돌아다니다 생을 마쳤다.","a":"고흥서동사","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"고흥군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662128.jpg"},{"q":"○○○란 임금이나 고관 등의 평생업적을 기록하여 그의 무덤 남동쪽에 세워두는 것이며, ○○○은 묘의 바로 옆에 두어 묘의 주인공을 밝혀두는 것이다. 이 비는 조선시대 중기 유성룡과 더불어 퇴계학파를 대표하였던 학봉 김성일 선생의 묘에서 약 50m 아래에 자리하고 있다. 김성일은 퇴계 이황의 제자로 그의 아래에서 배움을 익혔으며, 선조 1년(1568) 증광문과에 병과 급제한 후 여러 벼슬을 두루 거치었다. 임진왜란 때에는 경상우도초유사로 임명되어 의병활동을 도와 많은 공적을 남겼다.","a":"학봉신도비및묘방석","c":"시도유형문화유산","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641004.jpg"},{"q":"충장공 ○○○의 묘역과 정문(旌門)이다. ○○○은 임진왜란 때 옥포해전과 합포해전 등에서 활약하였으나 미조항전투에서 전사하였다. 그 후 영조 21년(1751)에 그에 대한 정려가 내려졌다. ○○○의 묘는 조선시대의 일반적인 묘의 형태로, 묘 앞에는 최근에 세운 비석과 상석 망주석 등이 있고 묘의 왼쪽에는 묘갈이 세워져 있다. 효종 8년(1657)에 세운 이 묘갈은 두동강난 것을 다시 붙여 세운 것이다. 묘로 진입하는 입구 쪽에 신도비가 위치하고 있으며, 정문은 묘역에서 서쪽으로 약 1.5㎞ 되는 곳에 사당과 함께 있다.","a":"춘천한백록묘역및정문","c":"문화유산자료","nc":"","r":"강원특별자치도","s":"춘천시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660606.jpg"},{"q":"○○○○○은 백운산에서 동남쪽으로 뻗어 있는 구릉의 끝부분에 위치하고 있다. 이 일대는 언양에서 경주로 연결되는 곳으로 유적 주변의 구릉일대에서 무문토기가 많이 발견되었다고 한다. ○○○는 현재 2기만 남아 있으나 원래는 더 많았을 것으로 짐작된다. 1호와 2호는 2m정도 떨어져 있으며 땅 위에 덮개돌이 반듯하게 놓여 있다. 덮개돌은 화강암으로 1호는 길이 350㎝, 너비 190㎝, 두께 140㎝정도이고, 2호는 길이 270㎝, 너비 160㎝, 두께 150㎝ 정도인데, 받침돌은 확인되지 않는 것으로 보아 개석식 ○○○일 것으로 추정된다.","a":"인보리지석묘군","c":"시도기념물","nc":"","r":"울산광역시","s":"울주군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645898.jpg"},{"q":"경상북도 예천군 보문면 승본리의 산 속에 서 있는 높이 160cm의 석불이다. 머리 위에는 상투 모양의 머리묶음이 뚜렷하고, 코와 귀에 약간의 손상이 있지만 온화한 인상이다. 양 어깨에 걸친 옷은 배 앞에서 가지런한 옷주름을 나타낸다. 두 손은 가슴에 모아 약그릇을 들고 있어서 이 불상이 중생의 질병을 구제한다는 약사여래를 형상화한 것임을 알 수 있다. 불상이 서 있는 대좌(臺座)는 아랫부분이 땅에 묻혀 있고 윗부분만 남아 있는데, 둥근 형태의 돌에 연꽃무늬가 새겨져 있다. 불상의 양식상 신라말 또는 고려초의 작품으로 추정된다.","a":"예천승본동석불입상","c":"문화유산자료","nc":"","r":"경상북도","s":"예천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663191.jpg"},{"q":"윤찬·윤여임·백선남·윤지선·윤자민의 학문과 덕을 추모하기 위해 세운 서원이다. 윤찬은 조선 중기 무신이다. 임진왜란 당시 야인으로서 선조의 수레를 호위하여 피난길을 도왔다. 후에 선전관에 제수되고, 오위도총부부총관에 이른다. 윤여임은 조선 중기 무신이다. 무과에 급제하고 광해군 14년(1622) 조총·대포 등을 만들어 포상받아 선전관이 되었다. 병자호란 때 쌍령전투에서 싸우다 전사하였다. 후일 병조판서에 추증된다. 윤지선은 조선 후기 문신이다. 광해군 14년(1662) 문과에 급제하여 좌의정까지 오른다.","a":"백산서원","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"김제시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661818.jpg"},{"q":"○○○는 전라남도 장흥군 가지산에 있는 절로, 860년 신라의 승려 체징에 의해 창건되었다. 이 책은 ○○○○○의 배안에 넣어서 보관하던 유물 가운데 하나이다. 『○○○○』는 조선 전기에 널리 유행하던 ‘금강반야바라밀경’, ‘대방광불화엄경입부사의해탈경계보현행원품’, ‘대불정수능엄신주’, ‘불설아미타경’, ‘관세음보살예문’, ‘묘법연화경관세음보살보문품’등 여섯가지 경전을 모아 한 책으로 엮은 것이다. 우리나라에서 간행된 가장 오래된 것은 세종 6년(1424)에 전라도 고산 안심사에서 만든 판본이며, 이 밖에도 현재까지 알려진 판본은 20여종 이상이 되고 있다.","a":"보림사사천왕상복장육경합부","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"장흥군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2020022814022800.jpg"},{"q":"○○○은 고령 박씨인 무민당 박인(1583∼1640) 선생이 학문을 닦고 연구하던 곳으로, 성리학을 연구하는 유학자들을 위해 지은 정자이다. 박인 선생은 관직에 뜻을 두지 않고 시골에서 은거행활을 하던 선비로, 덕망과 학식과 충절이 뛰어났다. 인조 17년(1639)에 세운 정자의 규모는 앞면 3칸·옆면 2칸이며, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕으로 꾸몄다. 왼쪽과 앞쪽 전체에 마루를 깔았으며, 건물 둘레는 조각한 난간으로 꾸몄다.","a":"합천 벽한정","c":"문화유산자료","nc":"","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664412.jpg"},{"q":"전라남도 ○○군 삼계면 신기리 ○○○에 있는 이 석불은 대좌(臺座)와 불신을 각기 다른 돌로 만들었다. 일부에서 심한 파손을 보여주고 있으나 현 ○○○의 변천 과정을 말해주는 유일한 자료이다. 만든 시기는 고려 중기로 여겨지며 인근에 있는 영광신천리3층석탑(보물 제504호)과 함께 당시의 조각사 연구에 참고자료가 된다.","a":"장성 봉정사 석조여래입상","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"장성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662239.jpg"},{"q":"충효마을 동쪽 북촌마을에 위치해 있으며, 환벽당과는 200m쯤 떨어져 있다. 이 정자는 정면 3칸, 측면 2칸의 골기와 팔작지붕으로 중앙의 거실 한 칸을 제외한 좌․우양 칸은 모두 마루로 꾸며져 있다. ○○○. 권필의 취시가 원문.","a":"취가정","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"북구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2018101118232600.JPG"},{"q":"○○○는 임진왜란 최초의 승리를 이룩한 ○○○○○로서 1592년 4월 13일 대군을 이끌고 침입한 왜군에 의해 부산 동래성, 울산성, 경주성이 함락되고 영천성 마저 함락되자 4월 27일 이곳에서 도탄에 빠진 백성과 나라를 구하고자 창의기병(창의기병)하여 5월 6일 이곳 한천일대를 중심으로 전개된 전투에서 최조의 승리를 거둠으로서 후일 영천 복성전으 발판을 마련한 역사적 장소이다. 당시 이곳 ○○○투에 목숨 바쳐 참가한 의병들의 넋을 위고하고 애국애족심과 호국정신을 고취하는 역사적 장소로 보존코자 경상북도 기념물로 지정하였다.","a":"임란의병 한천전 승첩지","c":"시도기념물","nc":"","r":"경상북도","s":"영천시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2019051910395400.JPG"},{"q":"조선 중기의 문신인 류상운(柳尙運, 1636~1707)의 초상화이다. 류상운의 본관은 문화(文化)이고, 호는 약재(約齋)이다. 현재 류상운의 초상화는 2점이 전하고 있다. 한 점은 평양의 생사당(生祠堂), 즉 관찰사 류상운의 업적을 기리기 위해 세운 사당에 걸렸던 것이고, 다른 한 점은 그것을 베껴 그린 이모본이다. 류상운이 평안도관찰사로 있을 때 백성들을 위한 선정(善政)을 베풀었기에 백성들이 생사당을 만들고 초상화를 그려서 봉안했다고 한다.","a":"류상운초상","c":"시도유형문화유산","nc":"","r":"경기도","s":"양평군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2023052611135102.png"},{"q":"‘탑골동’또는 ‘절골동’이라 불리우는 ○○○ 산골짜기에는 이름이 알려지지 않은 자그만 절터가 하나 있다. 절터에서 조금 떨어진 산 기슭에 이르면 아담한 모습의 이 탑이 보이는데, 2층의 기단(基壇) 위에 3층의 탑신(塔身)을 올려놓은 모습이다. 아래층 기단은 네 면의 가운데와 모서리에 기둥모양을 본떠 새겼고, 위층기단은 모서리에만 조각을 해 두었다. 탑신부의 각층 몸돌을 덮고있는 지붕돌은 곡선을 이루는 낙수면과 수평을 유지하는 처마의 조화가 아름답다. 네 귀퉁이에서의 들어올림도 가벼우며, 밑면의 받침은 1층에서부터 5단·4단·3단으로 점차 줄어들고 있다.","a":"정산남천리석탑","c":"시도유형문화유산","nc":"","r":"충청남도","s":"청양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639097.jpg"},{"q":"조선 세조 2년(1456) 조선의 6대 임금인 단종의 복위를 도모하다 목숨을 바친 박팽년·성삼문·이개·하위지·유성원·유응부 6명의 신하 즉 사육신(死六臣)을 모신 곳이다. 이들은 단종 3년(1455)에 단종의 숙부인 수양대군(뒤의 세조)이 왕위를 빼앗고 단종을 몰아내자 이에 분개하여 단종의 복위를 꾀하다 발각되어 참혹한 최후를 맞았다. 사육신의 충성심과 장렬한 의기를 추모하기 위해 숙종 7년(1681)에 이곳에 서원을 세우고, 정조 6년(1782)에는 신도비(神道碑:왕이나 고관 등의 평생 업적을 기리기 위해 무덤 근처 길가에 세우는 비)를 세워 두었다.","a":"사육신묘","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"동작구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636052.jpg"},{"q":"용모산 밑에 있는 ○○○은 9세기말 통일신라 진감국사가 신흥사를 세운 후에 수행과 더불어 불교를 전파하기 위해 지었다. 당시 암자 주위에 대나무가 있어 명칭이 ‘○○○’이 되었다고 전한다. 그 뒤 조선 연산군 10년(1504)에 지엄선사가 고쳐 지었으나 임진왜란 때 소실되었으며, 현종 5년(1664)에 전남의 어느 민가를 해체하여 복원한 것이 오늘에 이르고 있다.","a":"죽림암","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"임실군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661640.jpg"},{"q":"배를 타고 들어오는 외적의 침입을 막기 위해 제주도에서는 해안선을 따라가며 성을 쌓았는데 이를 ○○○○이라 한다. 현재 성벽이 남아있는 곳으로는 온평리, 행원리, 한동리. 동복리, 북촌리, 애월리, 고내리 등 14곳이 있다. 김상헌이 지은 『남사록』에는 ○○○○을 일러 ‘탐라의 만리장성’이라 부르고 있다. 현재 남아 있는 온평 ○○○○ 성벽의 길이는 약 2,120m로 다른 ○○○○들과 비교해 매우 길다. 온평리 하동 해안가에서 신산리 마을 경계에 이르기까지 펼쳐진 이 ○○○○은 1, 2, 3, 4지점으로 나눌 수 있다.","a":"온평환해장성","c":"시도기념물","nc":"","r":"제주특별자치도","s":"서귀포시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657925.jpg"},{"q":"조선 중기 문신인 김종걸(1628∼1708)선생을 추모하기 위해 사림들이 세운 건물이다. 선생은 학문과 덕행에서 뿐 아니라 효성이 지극하여, 부모님이 병들자 소태산에 올라가 7일 동안 금식 기도를 드렸다. 그 후 약을 구하러 가는 길에 호랑이가 나타나 인도하여 명약을 구해 부모님의 병을 낳게 했다는 일화가 전하고 있다. 그는 죽은 뒤에 이조 참판으로 추대되었다. 정조17년(1793)에 세운 이 사당은 흥선대원군의 서원철폐령으로 고종 5년(1868) 폐쇄되었다가 1925년 복원하여 오늘에 이르고 있다.","a":"봉산리사","c":"문화유산자료","nc":"","r":"경상북도","s":"봉화군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662689.jpg"},{"q":"1844년 제작된 봉은사 ○○○의 도상을 축소화한 작품으로 19세기 서울, 경기지역에서 유행하였던 ○○○의 전형적인 작품이다. 특히 향로와 옷 무늬 등에 금박을 사용 하였으며 세부묘사가 정교한 편으로 당시 불화의 경향을 잘 반영하였다.","a":"사자암 신중도","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"동작구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2595102.jpg"},{"q":"○○○○○는 건립연대가 정조 14년(1790)으로 확인되는 바 시기상으로 보아 200년 이상이 되었고, 형태면에서도 18세기 후기에 많이 보이는 비석형태를 보여주고 있다. 특히 옥개석 양측면에 조각되어 있는 쌍조(雙鳥)의 모습과 옥개석 앞뒤 밑부분에 2단씩 조각되어 있는 연목(椽木, 서까래) 형식은 목조가옥이 지붕을 연상케 해 주어 독특한 감이 있다. 이 비석의 비문 내용으로 보아서 ○○○○의 유래와 배향인물 19명의 내력을 기록하고 있다.","a":"창녕 물계서원 원정비","c":"문화유산자료","nc":"","r":"경상남도","s":"창녕군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1665286.jpg"},{"q":"이 가옥은 안채와 사랑채 2동으로 구성되어 있는 전통 살림집으로 사랑채 묵서명(墨書銘)의 상량문을 통해 보면 1852년(철종 3)에 건립되었다. 가옥의 이름을 ○○○○이라고 명명한 것은, 집을 건립한 이주희(李澍熙, 1866~1946)의 아호인 ‘극와(極窩)에서 따온 것이다. 가옥을 건립한 이주희는 어머니가 돌아가시자 3년 동안 흰옷과 흰 갓을 쓰고 어머니를 생각하는 생활을 실천한 효자였다. 또한 그는 국권상실에 직면해서 이를 한탄하며 방에 거적을 깔고 생활하면서 두문불출한 애국지사이기도 하였다.","a":"성주 극와고택","c":"시도민속문화유산","nc":"","r":"경상북도","s":"성주군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658990.jpg"},{"q":"○○○는 임진왜란 때 기허 영규대사와 중봉 조헌 선생이 이곳에서 승군과 의병을 일으켜 훈련하였다 하여 호국도장으로 잘 알려져 있다. 영규대사와 조헌 선생은 힘을 합하여 청주성을 탈환하고 금산전투에서 왜군을 맞아 싸우다 순절하였다. 이에 ○○○에서는 ○○○을 짓고 영규대사와 조헌 선생의 영정을 봉안하였는데 지금은 위패만 모셔져 있다. ○○○ 지붕에 있는 망와의 명문으로 보아 조선 숙종 20년에 건축된 것으로 추정되며, 건축의 형태는 정면 1칸, 측면 1칸 겹처마 맞배지붕 목조기와집으로 매우 작은 규모지만 원형이 잘 보존되어 있다.","a":"옥천 가산사 영정각 및 산신각","c":"시도기념물","nc":"","r":"충청북도","s":"옥천군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1650719.jpg"},{"q":"○○○○○는 ○○군 남면의 남단 해안가에 위치한 ○○○의 정상에 축조되어 있다. 자연 암반을 기반으로 하여 석축한 것으로, 평면 형태는 원형이나 일부분은 각이 져 있다. 동쪽 부분은 비교적 완전하게 남아 있으나 서벽은 붕괴가 심한 편이다. 무너진 부분은 후대에 일부 개축되어 전체적인 구조는 정확하게 파악하기 어렵다. 그러나 동벽의 상태가 양호하므로 조선시대 봉수의 구조를 비교적 자세하게 파악할 수 있다고 판단된다. 이 ○○○는 동쪽에 위치한 ○○ 금산 봉수를 받아 내륙의 망운산, 혹은 순천 돌산도 봉수와 연결되는 것으로 보인다.","a":"남해 설흘산 봉수대","c":"시도기념물","nc":"","r":"경상남도","s":"남해군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657157.jpg"},{"q":"이 영정은 ○○○○○선사의 좌안7분면 바닥가부좌상으로, 돗자리위에 방석을 깔고 왼손엔 목리문이 그려진 주장자를 오른손엔 염주를 쥐고 측면을 향해 앉아 있다. 그 옆으로는 서책들이 올려진 서안이 보인다. 화면은 녹색바탕에 운보문의 충진구도인 상단벽면과 돗자리의 이단구도로 이루어져 있다. 화면 향우측엔 양종대법사○○○○○지진(兩宗大法師凝庵堂僖愈之眞) 화제가, 향좌측 외곽에는 묵서로 쓴 영찬이 있다. 화면 크기는 가로 75.0cm, 세로 113.1cm이다.","a":"응암당 희유 진영","c":"시도유형문화유산","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/0000000001643019.JPG"},{"q":"○○○란 임금이나 고관 등의 평생업적을 기록하여 그의 무덤 남동쪽에 세워두는 것으로, 이 비는 조선 중기의 문신인 ○○ 선생의 행적을 기록하고 있다. ○○ 선생은 학문에 뛰어난 이로, 중종 14년(1519) 대과에 장원급제하여 관직에 나아가 홍문관의 부수찬, 사간원의 사간 등을 지냈고, 생을 마친 후에는 영의정으로 추증되었다. 선조 23년(1590) 당대의 명필인 한석봉의 글씨를 새겨 비를 세웠다.","a":"합천 박소 신도비","c":"시도유형문화유산","nc":"","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642200.jpg"},{"q":"이 화첩은 조선 선조(宣祖)때 한성부우윤(漢城府右尹)을 제수 받은 이거(李遽, 1532～1608)가 1605년(宣祖 38년) 자신이 참여하는 계회(契會)에서 102세 된 자신의 모친 채씨부인(蔡氏夫人), 강신(姜紳, 1543～ 1615)의 83세 된 모친 윤씨부인(尹氏夫人)등 장수(長壽)를 누린 10여 명의 사대부가(士大夫家)대부인(大夫人)들을 위하여 잔치를 연 장면을 그린 것이다.","a":"경수연도","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2590375.jpg"},{"q":"○○○○○은 1897년 고종 황제가 하늘에 제사를 지내고 대한제국의 성립을 대내외에 널리 알리기 위해 조성한 ○○○의 ○○으로 이 문은 비록 오랜 기간 제 위치를 벗어나 다른 용도로 사용되면서 창건 당시의 원형이 부분적으로 훼손․변형되었지만, 대한제국 시기대외적으로 조선이 자주국임을 선언하고 대한제국의 선포를 알리기 위해 창건한 ○○○의 첫 관문에 해당하는 건축물로서, 역사적으로 매우 상징적인 의미를 지니고 있으며 이전 복원 시 최대한 원부재를 활용하여 복원함.","a":"원구단 정문","c":"문화유산자료","nc":"","r":"서울특별시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2025061318324090.jpg"},{"q":"경남 합천의 상천리 마을 옛 절터에 있던 것을, 1960년 부산의 동아대학교에서 현재의 자리로 옮겨 세웠다. 기단의 아래받침돌은 옮겨 세울 때 새로 만든 것으로, 그 위에 1층 기단(基壇)과 3층의 탑신(塔身)을 올렸다. 기단과 탑신의 각 몸돌에는 모서리마다 기둥모양을 조각하였다. 두툼한 지붕돌은 밑면의 받침이 3단씩이며, 네 귀퉁이가 살짝 들려 있다. 전체적으로 각 층의 비례가 안정되어 소박하고 간결한 느낌을 준다. 고려 후기∼조선 전기 사이에 세웠을 것으로 추정된다.","a":"삼층석탑","c":"시도유형문화유산","nc":"","r":"부산광역시","s":"서구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636635.jpg"},{"q":"○○○는 조선 광해군 8년(1616) 성화선사가 세운 절로 광해군 14년(1622) 폭풍우로 허물어진 것을 다시 세워 천택사라 불렀다고 한다. 그 뒤 인조 6년(1628) 다시 화재로 타버린 것을 행선선사가 자리를 옮겨 짓고 ○○○로 이름을 바꾸어 오늘에 이르고 있다. 아미타삼존불을 모신 ○○○은 앞면 3칸·옆면 2칸 규모이며 지붕은 옆에서 볼 때 지붕선이 사람 인(人)자 모양인 맞배지붕이다. 지붕 처마를 받치기 위해 만든 공포는 기둥 위와 기둥 사이에도 있는 다포양식이다. 안쪽은 복잡하고 장식이 많은 천장구조를 이루고 있으며, 공간이 넓게 트여있다.","a":"통영 용화사 보광전","c":"시도유형문화유산","nc":"","r":"경상남도","s":"통영시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642046.jpg"},{"q":"○○○ 칠성각 ○○○은 2미터에 가까운 중형 크기의 면 바탕 화면에 채색된 작품이다. 도상들이 비교적 정연하게 묘사되어 있지만 채색상태가 다소 거친편이다. 조선후기∼말기에 이르는 ○○○ 도상연구에 자료적 가치가 있다.","a":"의령 수도사 칠성탱","c":"문화유산자료","nc":"","r":"경상남도","s":"의령군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1665237.jpg"},{"q":"고려 후기의 문신인 목은 이색(1328∼1396) 선생의 초상화이다. 이색은 공민왕 1년(1352) 세금제도의 개혁, 국방계획, 교육장려, 불교억제 등 여러 정책에 대해 건의문을 올렸다. 공양왕 1년(1389) 이성계 일파가 위화도 회군으로 세력을 잡자 장단지역으로 유배되기도 하였다. 이후 이성계가 그를 조정으로 불러 들였으나 이를 거절하고 이듬해 여강지역으로 가던 도중 생을 마치었다. 그림의 작가는 알 수 없으나 조선 전기의 대학자였던 권근의 찬하는 글이 있고, ‘영락갑신9월’이라는 기록이 함께 있어, 조선 태종 4년(1404) 이전의 작품으로 추정된다.","a":"목은영정","c":"시도유형문화유산","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640619.jpg"},{"q":"○○○ 한켠에 자리하고 있는 사리탑으로, 사리의 주인공에 대해서는 알려지지 않고 있다. 탑은 네모난 기단(基壇)위로 공 모양을 한 탑신(塔身)을 올린 모습이다. 특히 탑신의 맨 윗부분에 연꽃무늬를 둔 구슬띠를 새겨 놓아 시선을 모은다. 이 절내에서 연대가 가장 오래된 것으로, 양식적으로도 특이한 기법을 보이고 있는 고려시대의 작품이다.","a":"강진백련사원구형부도","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"강진군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640144.jpg"},{"q":"평택시 안중읍 ○○○에 있다. 해발 30∼40m의 낮은 구릉지에 축조된 평지토성이다. 평면 형태는 북벽이 약간 짧은 사다리꼴 모양이다. 동벽 부분이 농수로 조성과정에서 파괴된 상태임을 고려하면 원래의 형태는 장방형이었던 것으로 보인다. 성의 둘레는 449m다. 성벽에는 3개의 문지와 5개의 치, 수구지 등이 있다. 성내에는 5개의 건물지가 확인되며, 성벽 바깥쪽에는 해자가 있었다. 성벽은 자연 능선의 경사면을 이용하여 낮은 곳을 성토하는 방식으로 쌓았다. 성벽은 바닥을 다듬고 점토와 마사토를 교대로 쌓고 다짐했다.","a":"평택용성리성지","c":"시도기념물","nc":"","r":"경기도","s":"평택시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1647346.jpg"},{"q":"○○○ 아랫마을에 자리잡고 있는 옛 집으로 18세기에 지은 것으로 보인다. 원래 반남 박씨가 지은 것을 현 소유자의 6대조가 사들여 지금에 이르고 있다고 전한다. ㅁ자형의 정침과 방앗간채로 이루어져 있다. 중문을 중심으로 오른쪽에 마구간이 있고, 왼쪽에는 一자형의 사랑채가 있다. 사랑채는 1칸의 사랑마루와 2칸의 사랑방으로 구성되었으며, 앞쪽에 반칸너비의 툇마루가 있다. 툇마루 주위에는 난간을 둘러 사랑채의 격식을 갖추려 하였다. 사랑마루 뒤쪽에는 중방을 두었는데 마루쪽과 안마당쪽으로 여닫이문을 달아 출입할 수 있도록 하였다.","a":"영주수도리김덕진가옥","c":"시도민속문화유산","nc":"","r":"경상북도","s":"영주시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658848.jpg"},{"q":"○○○○○은 쌍청당 송유(1389~1446)가 1432년(세종 14)에 건립한 별당 건물이다. 건물 이름은 선생의 호인 ‘쌍청(雙淸)’을 따다 붙였는데 청풍과 명월의 맑은 기상을 마음에 담고자 한 것이라고 한다. 이후 여러 차례에 걸쳐 고쳐 지었지만 비교적 원형을 잘 보존하고 있어 조선 초기의 건축 양식을 볼 수 있는 대표적 건물로 알려져 있다. 정면 3칸 중 우측 2칸은 우물마루의 대청으로 사용하고 좌측 1칸은 온돌방으로 사용하였다.","a":"회덕쌍청당","c":"시도유형문화유산","nc":"","r":"대전광역시","s":"대덕구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637177.jpg"},{"q":"향교는 훌륭한 유학자를 제사하고 지방민의 유학교육과 교화를 위하여 나라에서 지은 교육기관이다. 이 향교를 처음 지은 시기는 알 수 없다. 조선 명종 6년(1515) 현감 황준량이 수리하였다고 하며 임진왜란 때 불에 타버린 것을 광해군 7년(1615) 다시 지어 숙종 12년(1686) 지금 있는 자리로 옮겼다. ○○○은 교육공간의 중심 건물로 강의를 하던 곳인데 철종 3년(1852) 5월에 다른 건물들을 수리하면서 고쳐지었다고 한다. 지붕은 단순한 맞배지붕의 양끝 칸쪽에 날개를 펼친 듯 지붕을 덧단 가적지붕이다.","a":"신녕향교명륜당","c":"시도유형문화유산","nc":"","r":"경상북도","s":"영천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640612.jpg"},{"q":"고려 후기 성균관 진사 이오(李午) 선생이 고려가 망하고 조선왕조가 들어서자 고려에 대한 충절을 지키기로 결심하고 이곳에 거처를 정한 이후 대대로 그 후손들이 살아온 장소이다. 이오는 이곳에 담장을 쌓고 고려 유민의 거주지임을 뜻하는 ‘○○○학’이라는 비석을 세워 논과 밭을 일구어 자급자족을 하였다. 그는 아들에게도 조선왕조에 벼슬하지 말 것과 자기가 죽은 뒤라도 자신의 신주를 이곳을 떠나 다른 곳으로 옮기지 말도록 유언하였다. 그의 유언을 받든 후손들은 19대 600여 년에 이르는 동안 이곳을 떠나지 않았고, 이에 ○○○이라는 이름으로 오늘까지 이어 오고 있다.","a":"함안 고려동 유적지","c":"시도기념물","nc":"","r":"경상남도","s":"함안군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1655016.jpg"},{"q":"충청남도 예산군 덕산면 ○○○ 절터에서 나온 이 보살입상은 함께 발견된 3층석탑과 같이 마을 회관에 보존되어 있다. 불상은 탑의 맞은 편에 세워져 있으며 아랫부분이 땅에 묻혀 있다. 정수리 부분이 평평하고 귀는 긴 편이나 어깨에 닿지는 않는다. 목에는 3줄로 새겨진 삼도(三道)가 있는데 뚜렷하지 않다. 왼손은 가슴 앞까지 들어 손가락을 펴고 있는 모습이고, 양 어깨를 감싼 채 길게 입은 옷은 발까지 내려져 있다. 전하는 이야기에 의하면 약 300년 전에 지금의 마을회관 동쪽 150m되는 지점에 절이 있었는데 난리 중에 불에 타 버렸다고 한다.","a":"석곡리미륵불","c":"문화유산자료","nc":"","r":"충청남도","s":"예산군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661204.jpg"},{"q":"조선 중기 선조 때 선비인 교하노씨交河盧氏의 4형제 노계원盧系元·노준원盧俊元·노종원盧從元·노일원盧一元의 위폐를 모신 사당과 ○○○이다. 『증보문헌비고增補文獻備考』의 기록에 따르면 서애 류성룡西厓 柳成龍이 영남에 갔다가 상경하는 길에 4형제를 찾아가 만나보고 그들의 남다른 우애와 효성이 지극한 것에 감탄하여 선조에게 말씀드리니 선조가 친히 ‘체화당棣華堂’이란 글씨를 써서 그 집에 걸도록 하였다고 전한다.","a":"청주 체화당사 및 사적비","c":"시도기념물","nc":"","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1649989.jpg"},{"q":"원주목사와 남원목사를 지낸 김탄행(1714∼1774)의 묘를 관리하기 위하여 지은 집이다. 약 240여 년 전에 처음 지었다고 하지만 정확한 근거는 없으며, 1936년에 크게 보수하였다고 한다. ㄱ자형의 안채와 사랑채가 연결되어 ㄷ자형을 이루고, 사랑채 끝에 대문과 헛간 등이 연결되어 전체적으로 ㅁ자형의 배치를 이루고 있다. 안채는 안방과 웃방이 부엌에 접하여 있고 그 옆으로 대청과 건넌방이 있으며, 지붕 옆면은 여덟 팔(八)자 모양의 화려한 팔작지붕집이다.","a":"김두한가옥","c":"시도유형문화유산","nc":"","r":"강원특별자치도","s":"원주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638077.jpg"},{"q":"태인 현감을 지낸 영천자 신잠 선생의 어진 정치와 행적을 기리기 위해 세운 비이다. 신잠(1491∼1554)은 조선 중종 14년(1519) 현량과에 급제했으나, 기묘사화로 인해 벼슬길에서 물러난 후 20여년간 은거하며 글과 그림에만 전념하였다. 그 후 복직되어 태인과 간성의 목사를 지내었고, 상주목사로 있던 중 목숨을 다하였다. 문장과 서화에 특히 뛰어난 재주를 보였다고 한다. 비는 높은 받침돌 위에 비몸돌을 세웠는데, 비몸돌의 윗변 양 모서리를 깍아 둥글게 처리하였다.","a":"신잠비","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"정읍시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661719.jpg"},{"q":"○○○는 고대부터 중요한 통신수단의 하나로 높은 봉우리에서 횃불이나 연기 등으로 변방의 긴급한 상황을 중아이나 해당 진영에 알려 적의 침략을 분쇄하는 등 군사목적으로 설치한 것이다","a":"고성천왕점봉수대","c":"시도기념물","nc":"","r":"경상남도","s":"고성군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1656788.jpg"},{"q":"○○○는 ○○○ 장군의 보검으로 용천검과 ○○○가 있었는데 용천검은 전쟁 시 직접 쓰던 검이었으나 6.25때 분실되었고 한다. ○○○가 남아 있는 단검이 유일한 유물로 평상시 보호용으로 애용한 보검으로 알려져 있으나 관련된 문헌은 남아있지 않다. 현재 충렬사 유물전시관에 전시하고 있으며 칼과 칼집 모두 양호한 상태이다. 도신은 철, 손잡이와 칼집은 목재, 목재를 고정시키는 장식은 황동과 동으로 되어 있다. 또한 칼 코 등을 얇은 철판으로 제작도어 있으며, 그 위에 주석·납으로 합금하여 도금하였다. 도신 좌우측면에 명문이 남아 있다. 보관함은 후대에 제작한 것이다.","a":"임경업 추련도","c":"시도유형문화유산","nc":"","r":"충청북도","s":"충주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638937.jpg"},{"q":"○○○○○ 자료는 1899년에 창립한 ○○○○○의 설립과정을 보여주는 청원서와 인가서, 정관, 인천·부산 등의 지점 설치관련 ○○ 등을 포함하는 창립 및 초기 운영 관련 ○○와 회계 관련 ○○로서, 기본적으로는 낱개 ○○와 ○○철 및 장부의 형태로 구성된 총 19건75점이다. 낱장의 ○○들도 남아 있는 천공(穿孔)의 흔적으로 보아 초기에는 ○○철에 포함되어 전래하다가 어느 시기에 해체하여 별도 관리한 것으로 보인다.","a":"대한천일은행 창립관련 문서 및 회계문서 일괄","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636470.jpg"},{"q":"전북특별자치도 김제시 황산동 ○○○에 모셔져 있는 나무로 만든 ○○○○○으로, 고개는 앞으로 숙여져 있고 신체는 단정하면서도 정돈되어 있다. 최근 불상 속에서 발견된 기록을 통해 1610년에 만들었음을 알게 되었다. 손모양이 모든 중생을 제도한다는 아미타여래의 손모양에 가까운데 기록에는 ○○○○상이라고 적혀 있다. 조선 후기 ○○○○의 형상이 다양하였음을 보여주는 귀중한 자료이다.","a":"문수사목조석가여래좌상","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"김제시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639658.jpg"},{"q":"원래 ○○시 우암산 목암사에서 전하던 석불입상으로, 근래에 현위치로 이전되었다. 석불상의 머리 부분은 원래 결실되어서 후에 보수된 불두가 있었는데, 현위치로 이전하면서 새로이 조성하여 붙였다. 대좌와 광배는 전하지 않고, 불신의 일부도 약간 파손된 부분이 있으나 나머지 부분은 보존이 양호하다. 조각수법이 뛰어나며 불신의 뒷면까지 세밀히 조각한 완전한 원각상이어서, 전체적으로 통일신라시대 여래입상의 특징이 두드러지게 반영되고 있는 상이다.","a":"청주 목우사지 석조여래입상","c":"시도유형문화유산","nc":"","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638905.jpg"},{"q":"○○○은 남자의 성기모양을 한 자연암석이나, 암석을 조각하여 세운 것을 말하는데, 사람들이 섬기는 민간신앙 중 성기숭배의 대상이 되는 것이다. 흰바위 마을 입구 서쪽에 자리하고 있는 이 ○○○은 이 마을에 있는 12당산 중의 하나로, 일명 ‘자지바우’라고도 불리운다. 높이는 1.35m로, 네모난 단 위로 길고도 곧게 뻗어 있다. 꼭대기부분은 약간 뾰족하게 깎은 후 둥글게 처리하였다. 300년 전에 어려운 사람을 많이 도와주던 ‘박잉걸’이라는 사람이 이 ○○○을 세웠다고 전한다.","a":"남근석","c":"시도민속문화유산","nc":"","r":"전북특별자치도","s":"정읍시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658300.jpg"},{"q":"이 초상화는 복건(幅巾)에 학창의(鶴氅衣, 백색 천으로 만들고 옷 가장자리에 검정비단으로 선을 두른 선비들의 웃옷)를 착용하고 공수(拱手) 자세를 취한 송시열의 좌안칠분면(左顔七分面) 반신상이다. 우암 송시열(尤庵 宋時烈, 1607년～1689년)은 조선 중기의 대표적 문인으로서 정치적으로 기복이 심한 삶을 영위하였지만 한편으로는 일생을 주자학 연구에 몰두했던 거유(巨儒)로서 기호학파(畿湖學派)의 주류를 이루면서 뛰어난 학식으로 많은 학자들을 길러낸 인물이다.","a":"송시열상","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2590339.jpg"},{"q":"이 영정은 좌안7분면의 바닥가부좌상으로, 회색장삼에 주색 가사를 수하고 측면을 향해 앉은 채 왼손엔 주장자를, 오른손엔 염주를 쥐고 있다. 그리고 뒤편으로는 문양 없는 상단벽면과 하단돗자리의 이단구도를 바탕으로 하여 패턴화된 등받이 장식을 배치하였다. 화면 향우측에 주지묵서의 화제가, 향좌측에 역시 주시묵서의 영찬이 있어 1860년에 조성되었음을 알 수 있다. 화면크기는 가로 84.0cm, 세로123.2cm이다.","a":"춘암당 인천 진영","c":"시도유형문화유산","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/0000000001643004.JPG"},{"q":"조선 중기의 문신인 한음 이덕형(1561∼1613) 선생의 초상화로, 현재 ‘한음영당’에 보존되어 있다. 선생은 선조 13년(1580) 문과에 급제한 뒤 승무원에 보직되고, 이어 선조 25년(1592) 예조참판에 올라 대제학을 겸임하였다. 그 후 병조판서, 우의정, 좌의정까지 올랐으며 1608년 광해군이 즉위하자 영의정으로 추천되었으나 영창대군의 처형을 반대하다 직위를 박탈당하여 양근에서 은거하다 생을 마쳤다. 글씨에도 뛰어나 저서로 『한음문고』를 남겼으며, 현재 포천의 용연서원, 상주의 근암서원 등에서 그의 위패를 모시고 제사를 지내고 있다.","a":"한음선생영정","c":"문화유산자료","nc":"","r":"충청남도","s":"당진시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661368.jpg"},{"q":"조선 세조 때 적개공신 장말손의 후손 장언상(1529∼1609)이 이곳에 터를 잡아 집을 짓고 살아오면서 후손이 번창하여 장씨의 집성촌을 이루고 있다. 사랑채와 안채가 ㅁ자형을 이루고 있으나 각각 독립된 건물로 평면구성이 특이하다. 뒤쪽에는 장말손 선생의 위패를 모시는 사당과 유물보호각이 있다. 유물각에는 보물로 지정된 영정과 교서 및 고문서 등이 보존되어 있다. 비교적 지을 당시의 모습을 잘 보존하고 있는 건물이다.","a":"화기리인동장씨종택","c":"시도민속문화유산","nc":"","r":"경상북도","s":"영주시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658807.jpg"},{"q":"이 영정은 영담당 ○○선사의 좌안7분면 바닥가부좌상으로, 방석을 깔고 화면중앙에 청색장삼에 주색가사를 수하고 양손에 각각 주장자와 염주를 쥐고 측면을 향해 앉아 있다. 선사 뒤편으로는 문양 없는 상단벽면과 하단돗자리의 이단구도를 배경으로 하여 도식화된 등받이 장식을 배치하였다. 화면 향우측에는 주지묵서의 ‘영담당○○대사지진(嶺潭堂有洪大師之眞)’ 화제가 있고 향좌측에는 주지묵서의 영찬이 있다. 화면크기는 가로 81.9cm, 세로 124.0cm이다.","a":"영암당 유홍 진영","c":"시도유형문화유산","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/0000000001643016.JPG"},{"q":"조선 숙종 때의 문신이자 학자인 미수 허목(許穆,1595∼1682)의 시문집 93권 25책을 새긴 목판이다. 숙종 15년(1689)에 판을 새겼으며, 총 861매에 이른다. 허목은 23세 때 정구의 문하에서 수학하였으며, 퇴계의 학문을 존중하였다. 이로 인해 스승 정구로부터 퇴계의 학문을 이어 받아 다시 그 학문이 이익에 의해 계승, 발전되는 구실을 하였다. 예학에 밝았던 허목의 행적을 알 수 있으며, 오래된 연대의 것으로 보존상태가 매우 좋고 누락된 목판이 없어 그 가치가 높다. 현재 전남 나주 소재의 ○○○○에 소장되어 있다.","a":"나주미천서원기언목판","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"나주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2019051619452200.jpg"},{"q":"세조의 비 정희왕후의 부친인 ○○○ 윤번(尹璠, 1384~1448)을 비롯하여 그의 후손들의 묘 600여기가 조성된 가족 묘역이다. 윤번과 중종 비 장경왕후 윤씨의 부친 윤여필(尹汝弼), 중종 비 문정왕후 윤씨의 부친 윤지임(尹之任) 묘 등이 있다. 윤번 묘역은 사각형의 둘레석을 세운 단분(單墳; 하나의 봉분)의 형태이다. 봉분은 조선 초기의 묘제 영향을 그대로 반영하고 있으며, 석물은 옛 것과 새 것이 섞여 있다. 그 중 주요한 석물은 묘표인데, 1448년(세종30)에 건립된 것으로 원수방부형(圓首方趺形; 둥근 머릿돌과 사각 받침돌의 비석 형태)이다.","a":"파평윤씨정정공파묘역","c":"시도기념물","nc":"","r":"경기도","s":"파주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2018010219115500.jpg"},{"q":"ㅡ자형의 사랑채와 ㄱ자형의 안채가 나란히 배치되어 있으며, 두 공간은 행랑채와 담장으로 명확히 구별되어 있다. 출입문도 구별되어 각각 안대문과 사랑대문으로 출입할수 있으며, ㄴ자형의 행랑채 익랑에 있는 중문으로 사랑마당과 안마당으로 통하게 되어있다. 대지전체가 담장으로 구획되어 있으며, 후면은 급한 경사지로 되어있다. 대지전면 담장과 사잇담은 막돌담장으로 되어있고, 후면담장은 토담위에 서까래를 걸러 한식기와를 얹어놓았다. ○○○○○은 서산지역에 남아있는 전통적인 양반가옥이다","a":"서산유상묵가옥","c":"시도민속문화유산","nc":"","r":"충청남도","s":"서산시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658276.jpg"},{"q":"나주 ○○○○○좌상(羅州 竹林寺 乾漆 阿彌陀如來坐像)은 고려시대 후기의 불상 양식의 전통을 이어주는 조선 초기 불상으로서 우리나라 조선시대 전기불상의 양식을 연구하는데 매우 귀중한 예가 되고 있다. 전국적으로 15개 내외뿐인 희귀한 건칠불에 속하고 있어 역사적, 학술적 예술적 가치가 있다.","a":"나주죽림사건칠아미타여래좌상","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"나주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2019051719174600.jpg"},{"q":"권택의 처인 ○○○○의 절의를 숭상하기 위해 건립한 것이다. 1601년(선조 34) 정려가 내려져 배양촌 앞에 ○○○을 세웠다가 1688년(숙종 14)에 ○○○을 입석 묘소 아래로 이전했다. 이 건물은 ○○○의 일반적인 구성형식을 따라 단칸에 3량가로 건축했으나 건축양식과 구조수법에서 몇 가지 특징이 있다. 익공계와 다포계 형식이 절충된 외1출목 삼익공의 건축양식으로 살미와 첨차에 연봉과 봉두를 잘 다듬어 화려하게 치장하였다. 초석은 주좌를 새긴 고졸한 형태이며, 각부의 결구상태는 견실한 편이다. 조선시대 ○○○의 건축형식과 특징을 잘 보여준다.","a":"산청 진양강씨 정려각","c":"문화유산자료","nc":"","r":"경상남도","s":"산청군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666404.jpg"},{"q":"○○가 ○○○의 죽음을 애도하며 친히 지어 보낸 뇌문을 새긴 비이다. “뇌문”이란 죽은 이의 명복을 천지신명께 비는 글이다. ○○○의 본관은 평강(平康)이고 호는 번암(樊巖)이다. ○○○은 ○○의 총애를 받고 여러 요직을 지낸 남인(南人) 출신의 명재상이다. ○○○는 묘역 바로 아래의 비각 안에 있다. 사각형 받침돌에 비신(碑身 ; 글씨를 새기는 부분)을 세우고 지붕돌을 얹은 방부개석(方趺蓋石) 양식을 취하고 있다. 오석(烏石)으로 만든 비신 상단에 가로로 쓰여진 “○○ 뇌문(誄文)”이란 전액(篆額; 전서체로 비석의 이름을 새긴 부분)이 있다.","a":"정조 어제 채제공 뇌문비","c":"시도유형문화유산","nc":"","r":"경기도","s":"용인시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637459.jpg"},{"q":"이 묘역은 조선 제 4대 왕인 세종(成宗)의 아들로 단종(端宗)복위운동에 가담하여 세조로부터 정치적 탄압을 받았던 ○○○ 이영(和義君 李瓔：1425년∼ 1489년 이후)의 분묘가 자리한 곳이다. ○○○ 이영은 1425년(세종 7) 조선 제 4대왕 세종(世宗)의 여섯 번째 아들(庶 1男)로 태어났다. 어머니는 영빈 강씨(令嬪 姜氏)이다. 후에 박중손(朴仲孫)의 사위가 되었다. 사육신인 박팽년(朴彭年)의 매부이기도 하다. 1433년(세종 15) ○○○에 봉해졌다.","a":"화의군이영묘역","c":"시도기념물","nc":"","r":"서울특별시","s":"은평구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2018102309564600.jpg"},{"q":"조선 선조 35년(1602)에 충주목사 정구(鄭逑)가 이미 있던 백운서당에 주자를 모시고 백운서원이라 하였는데，현종 2년(1661)에 정구를 배향하고 ○○○○이라 하였다. 숙종 2년(1676) 나라에서 현판을 받아 사액서원이 되었고 고종 8년(1871) 흥선대원군의 서원철폐령 때 철거되었다. 고종 31년(1894)에 서원을 다시 지었는데，다음해 구 영정을 가져와서 봉안하였다. 교육 공간과 제사 공간으로 크게 나뉘는데，앞쪽 교육 공간에는 현재 주춧돌만 남아 있다. 그 뒤편의 제사 공간에는 ‘○○○○’이라는 현판이 걸린 사당이 있다.","a":"음성 운곡서원","c":"문화유산자료","nc":"","r":"충청북도","s":"음성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660729.jpg"},{"q":"○○○○○ 종 목: 경기도 유형문화유산 시 대 : 1500년(조선 연산군 5년) ○○○○○는 불경에 나오는 숫자가 들어 있는 용어를 가려 뽑아서 숫자의 차례대로 배열하여 쉽게 찾아볼 숭 있도록 엮어놓은 일종의 불교용어사전이다. 본래 이 책은 당나라 승려 현수(賢首)가 부조의 설법을 숫자로서 표시하여 일목요연하게 이해할 수 있도록 편찬했는데, 후대 오면서 점차 희귀해지자 명나라 행심(行深)이 불교입문의 지침이 될 만한 체재로 재편하였다.","a":"현수제승법수","c":"시도유형문화유산","nc":"","r":"경기도","s":"남양주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2019052009570400.jpg"},{"q":"산성 안에 계곡을 품고 산 정상부를 둘러쌓은 삼국시대의 산성으로, 산봉우리가 동쪽에서 뻗어내리고 있어 수구를 골짜기인 서남쪽을 향해 뚫어 놓았으며, 돌로 쌓았다. 성의 둘레는 567m이고, 동·서 길이 182m, 남·북 길이 120m, 성 안의 면적은 15,523㎤에 이른다. 수구(水口)에서 서북쪽 성벽의 끝자락까지는 성벽을 2중으로 쌓았고, 그 사이에는 적의 침입을 어렵게 하기 위해 물길을 돌린 환호를 파두었다.","a":"척문리산성","c":"시도기념물","nc":"","r":"전북특별자치도","s":"남원시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653499.jpg"},{"q":"1층 기단(基壇) 위에 3층의 탑신(塔身)을 올려 놓은 석탑이다. 밑돌 ·가운데돌 ·맨윗돌을 쌓아 3단으로 마련한 기단은 아무런 조각을 하지 않았다. 탑신부는 몸돌과 지붕돌을 각각 하나씩의 돌로 쌓아 올렸으며, 역시 별다른 장식은 없다. 두터워 보이는 지붕돌은 밑면이 두꺼운 원형을 이루어 받침을 대신하고 있고, 네 귀퉁이는 위로 들려있다. 3층 지붕돌 위로는 노반(露盤:머리장식 받침)으로 보이는 네모난 돌이 놓여있다. 꾸밈이 없어 전체적으로 간결해 보이며, 지붕돌이 두텁고, 네 귀퉁이가 날카롭게 들려있어 고려시대에 세운 것으로 보인다.","a":"구례사도리삼층석탑","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"구례군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639839.jpg"},{"q":"○○은 옛부터 고령가야국(古寧伽倻國)의 수도였다고 전해지거니와 상주에 속해 있으면서도 나름대로의 문화적 배경을 지닌 고도이다. 신흥리 ○○○은, ○○이 사벌국 세력과는 달리 고동람군(古冬攬郡)으로 편제되면서 조영된 것으로 보여진다. 이 ○○○, 속칭 달랑골, 안생 원골을 사이에 두고 조성되어 있다. 첫째 군은, ○○○에서 신흥리 쪽으로 뻗어 내린 3개 지맥의 능선과 자락에 조영된 것으로 주로 소형 석곽과 중형급의 고분이 주류다.","a":"함창 오봉산 고분군","c":"시도기념물","nc":"","r":"경상북도","s":"상주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654615.jpg"},{"q":"향교는 행정구역인 부 · 목 ·군 · 현에 설립된 지방 교육기관으로 조선왕조가 들어서면서 적극적으로 개선과 보급에 노력함. ○○○○는 조선 태종 15년(1415)에 현유의 위패를 봉안, 배향하고 지방민의 교육과 교화를 위해 창건되었음. 1415년에 대성전을 설립하고 1572년에 현감 서의가 중건하였으며, 1574년에는 현감 장문한이 명륜당을 건립함. 그 뒤 임진왜란 때 소실되었다가 1623년에 대성전을 중건하고 1715년에 춘풍루를 건립하였음. 1748년에 도유사 김천분이 현재의 위치로 이건하여 몇 차례의 중수 · 보수를 거쳐 오늘에 이르고 있음.","a":"거창향교","c":"시도유형문화유산","nc":"","r":"경상남도","s":"거창군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641993.jpg"},{"q":"○○○의 창건에 대해 명확히 알려진 바는 없으나, 1960년대에 편찬된『한국사찰전서』에 따르면, 932년 백양(白楊) 조사가 창건한 후 임진왜란 때 소실되었으며, 1678년 연정(衍淨) 선사가 중창하였고, 1753년 설인(雪人) 선가가 다시 중창하였다고 전한다. 이후 조선후기까지 이어지다가 구한말과 일제강점기에 접어들며 사세(寺勢)가 약화되어 퇴락하였으나,「차사중창주비구니보현대공덕비(此寺重刱主比丘尼普賢大功德碑)」의 기록에 따르면, 1922년 비구니 승려 보현에 의해 ○○○가 중건되었으며, 1927년에 ○○○이, 1932년에 명부전과 백양선원 등이 건립되었다고 한다.","a":"백양사 칠성각","c":"문화유산자료","nc":"","r":"울산광역시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2017110214593602.JPG"},{"q":"○○○는 부소산 서쪽 봉우리 정상, 곧 달을 보내서 ‘송월대(送月臺)’라 불리는 봉우리에 있다. 이곳은 해발 106m로 부소산에서는 가장 높아서 동으로는 계룡산, 서로는 구룡평야, 남으로는 성흥산성, 북으로 울성산성과 증산성 등이 보여 전망이 아주 좋다. 아마 백제 시대에는 망루가 있어서 부소산성의 서쪽 장대 구실도 했을 것으로 추정된다. ○○○는 1919년 당시 부여군수인 김창수가 주도하여 임천 문루인 배산루(背山樓)를 옮겨 지었고, 1990년 중수하여 현재에 이르고 있다.","a":"사자루","c":"문화유산자료","nc":"","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661045.jpg"},{"q":"오리 이원익의 문집은 함경도관찰사 이서우(李瑞雨, 1633~1709년)의 도움으로 1691년(숙종 17)에 간행한 것이 초판본 『○○○○○』이다. 그 후 이원익의 현손인 이존도(李存道, 1659~1745)가 원집과 그 후 수집한 자료를 엮은 속집, 별집과 연보, 행장 등을 모은 부록을 경상도관찰사 김연(金演, 1655년 ~ )의 협조를 얻어 1705년(숙종 31)에 판각하여 안동의 병산서원에 장판(장판)한 것이『○○○○○』이다.","a":"광명 오리선생집·오리선생속집","c":"문화유산자료","nc":"","r":"경기도","s":"광명시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660293.jpg"},{"q":"전체 높이 15.5㎝의 작은 크기로 가지고 다닐 수 있게 만든 호신불(護身佛)이다. 아래로 향한 연꽃이 새겨진 대좌(臺座) 위에 서 있는 불상으로 아랫부분에는 금색이 많이 남아 있다. 정수리 부근에 있는 상투 모양의 머리묶음이 매우 크게 표현되어 있는 것이 특징이다. 얼굴은 갸름하고 여성스러울 정도로 인자하게 느껴지며, 입가에는 엷은 미소를 띠고 있다. 옷은 양 어깨에 걸치고 있으며, 가슴 아래에는 늘어진 U자형의 주름이 표현되어 있다. 옷자락은 양 팔에 걸쳐 길게 늘어뜨리고 있으며, 양 다리에는 타원형의 옷주름을 표현하였다.","a":"양산 통도사 청동여래입상","c":"시도유형문화유산","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641581.jpg"},{"q":"○○○는 여인의 입상으로 원래는 족자였을 것으로 생각 되나, 현재는 액자로 표구되어 있으며 전체적인 상태는 양호한 편이다. 본 작품은 19세기 신윤복 ○○○의 전통과 연결되어 있는 전형적인 선묘 위주의 초상화로, 조선중기 이후 제작된 ○○○의 계통으로 볼 때 조선말 기 ○○○로는 가장 수작에 해당되며 조선말기 복식사 연구 및 초상화 연구 에 좋은 자료이다. 또한 당대 초상화 계통을 풍미한 석지 채용신의 작품과 견줄 수 있는 작품 으로 자료적 가치가 높은 문화유산이다.","a":"미인도","c":"문화유산자료","nc":"","r":"부산광역시","s":"서구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659380.jpg"},{"q":"향교는 공자와 여러 성현께 제사를 지내고 지방민의 교육과 교화를 위해 나라에서 세운 교육기관이다. ○○○○는 고려 공민왕 2년(1390) 옥곡동에 처음 세웠으나, 임진왜란 때 불타 없어져 여러 차례 다시 세웠는데 조선 숙종 7년(1681) 신교동을 거쳐, 현재의 위치로 이건되었다. 임진왜란 당시 향교에 모시던 위패가 위험해지자 향교의 종이었던 강개명이 성암산 동굴로 옮겨 놓아 무사했다고 한다. 제사 공간인 ○○○을 앞에 두고 교육 공간인 명륜당을 뒤쪽에 둔 전묘후학의 배치 형태를 따르고 있다.","a":"경산향교<대성전, 삼문>","c":"시도유형문화유산","nc":"","r":"경상북도","s":"경산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641292.jpg"},{"q":"명부전은 염라대왕을 비롯하여 모두 열 명의 심판관이 죽은 이를 심판하는 곳이기 때문에 시왕전(十王殿)이라고도 한다. 지장보살과 시왕을 한곳에 모신 전각은 우리나라에서만 볼 수 있는 특징적인 절집이다. ‘○○○ 지장전’은 나무로 조각한 지장보살상을 중심으로, 그 좌우에 각각 5분씩, 모두 열 명의 ○○○을 함께 모신 곳이다. 민머리의 스님 모습을 하고 앉아 있는 지장보살상의 좌우에는 젊은 스님 모습의 도명존자(道明尊者)와 귀신의 왕이라는 무독귀왕(無毒鬼王)이 보좌한다.","a":"안성 칠장사 목조지장삼존상과 시왕상 일괄","c":"시도유형문화유산","nc":"","r":"경기도","s":"안성시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2018102316273800.JPG"},{"q":"임진왜란 당시 의병장으로 활약했던 조경남이 13세인 선조 15년(1585)부터 인조 15년(1637)까지 57년간의 국내의 중요한 사실을 기록한 것으로, ‘산서야사(山西野史)’라고 부르기도 한다. 특히 임진왜란과 정유재란에 대한 부분은 이순신 장군의『난중일기』보다 훨씬 광범위하게 다루어졌으며, 이 밖에도 이괄의 난, 병자호란, 정묘호란 등 중요 전란과 당시의 풍속 및 조정에서 일어난 사실들이 자세하게 기록되어 있다. 이것은 총 10권으로 구성되었는데 편의상 후반 5권을『속잡록』이라 부르고 있다.","a":"난중잡록","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"남원시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639533.jpg"},{"q":"충청남도 천안시 성거읍 해발 579m의 성거산 정상에 쌓은 산성이다. 『직산현지』를 보면 고려 태조가 직산 수헐원에 들렸다가, 동쪽에 있는 산을 바라보니 오색이 맑고 아름다워 영험이 있는 산이라 믿고 제사를 지내도록 하였으며, 성거산이라 이름을 지었다고 한다. 백제는 산성이나 읍성을 만들 때 반드시 익성(翼城)을 지었는데, 익성은 양 날개가 달린 듯 좌우로 성을 만든 것을 말한다. 따라서 ○○○○은 위례산성의 익성으로 보는 것이 타당하며, 이렇게 볼 때 성을 쌓은 시기는 삼국시대로 추정된다.","a":"성거산성","c":"문화유산자료","nc":"","r":"충청남도","s":"천안시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661317.jpg"},{"q":"향교는 성현의 위패를 모시고 제사 지내며, 지방 백성의 교육을 담당하기 위해 국가에서 세운 교육기관이다. ○○○○는 현재의 경인교육대학교에서 북쪽으로 약 200m 지점에 위치하고 있으며, 고려인종 5년(1127)왕명에 따라 수주(樹州)향교가 계양구 오류동 산4번지에 세워졌는데 당시 전국 56주가 모두 이에 따라 세워진 것으로 보이며 수주의 후칭인 안남도호부가 의종 19년(1165) 계산동(온수골)으로 이전됨에 따라 당시 안남향교도 안남산 남쪽(현재 계산2동 한우리 아파트 부근)에 이전했던 것으로 추측된다.","a":"부평향교","c":"시도유형문화유산","nc":"","r":"인천광역시","s":"계양구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637008.jpg"},{"q":"조선 후기 안동김씨 세도기 후반의 중심인물이었던 하옥 김좌근의 아들인 김병기(金炳冀, 1818~1875)가 부친의 묘지관리를 위한 집이자 별장으로 지은 건물이다. 고택의 뒤를 감싸는 산자락에 김좌근의 묘역과 김병기의 묘역이 있다. 고택 앞쪽으로 연지까지 고택의 일부분이었다고 하니 그 면적이 대단하였다. 당대에는 99칸 규모였다고 전하지만, 지금은 안채와 별당만 남아있으며, 2006년에 묘역도 사라졌다. 안채 회랑과 이어졌던 별당 둘레의 쪽마루는 온전한 모습으로 남아있다.","a":"김좌근고택","c":"시도민속문화유산","nc":"","r":"경기도","s":"이천시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/2019051613480200.jpg"},{"q":"여말선초(麗末鮮初) 제주고씨 중시조(中始祖)가 낙향 건립한 목조(木造) 건축물로 ○○읍내 현존하는 가옥 중 가장 오래된 것으로 우물 정(井)자 형의 평면을 지녔으며 안채와 사랑채로 구분 건립되어 있다. 가옥구조는 전반적으로 양반가옥에서 흔히 볼 수 있는 건축양식이며 사랑채의 마루는 정자(亭子)형으로 건축되어 있고 1921년경 가옥 일부를 중·보수(重·補修)한 적이 있다고 하며 대문(大門) 우측에는 수령 약600여년 된 뽕나무 2주가 도기념물로 지정 관리되고 있다. 근대에는 1934년 을해년 수해시 사랑채 보수가 있었으며.","a":"정선 상유재 고택","c":"시도유형문화유산","nc":"","r":"강원특별자치도","s":"정선군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638087.jpg"},{"q":"○○○○ 내에 서 있는 비로, 조선 단종·세조 때의 선비인 엄흥도의 충절을 기리고 있다. 엄흥도는 어린 단종이 세조에 의해 영월에 유배되었을 때에 그 지역의 호장을 지내었던 자로, 단종이 죽임을 당하자 그 시신을 수습하여 지금의 장릉자리에 몰래 장사지낸 후 세조의 보복이 두려워 종적을 감추어 버렸다. 이 후 숙종은 그 충의를 거룩히 여겨 ○○○의를 증직하였고, 영조는 그를 위한 정려문을 내려주었으며 훗날 공조판서에 다시 증직하였다.","a":"증공조참판엄공원강서원비","c":"문화유산자료","nc":"","r":"울산광역시","s":"울주군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659791.jpg"},{"q":"동백섬 내에 자리한 작은 바위 윗면에 ‘해운대(海雲臺)’라는 글씨를 새긴 것으로, 통일신라 후기의 학자였던 최치원 선생의 글씨로 전한다. 선생이 가야산으로 향하던 도중 이 주변의 자연경관이 너무도 아름다워 돌을 쌓아 대를 만든 후, 바다와 구름, 달과 산을 음미하면서 이 바위에 ‘해운대(海雲臺)’라는 글씨를 새기었는데, 이때 부터 ‘해운대’라는 지명이 생겨났다고 한다.","a":"해운대석각","c":"시도기념물","nc":"","r":"부산광역시","s":"해운대구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645193.jpg"},{"q":"○○○ 소재 부도군은 사찰의 동쪽 약 1㎞ 전방 진입로 우측 임야 내 5기의 부도가 조성되어 있는 호젓한 곳에 있다. 사찰의 묘역으로 보이는 부도군은 약간의 경사면과 앞쪽에 석축으로 마감한 약 100여 평 정도의 면적 한가운데에 5기의 부도들이 조성되어 있다. 대부분 조선후기에 건립된 것으로 추정되는 5기의 부도들은 현존상태가 양호한 편이며 각각 탑호를 가지고 있기도 하다. 5기의 부도들은 모두 주변에서 산출되는 화강암으로 조성된 것으로 추정되며, 서로 일정한 거리를 둔 채 횡렬로 건립되어 있다.","a":"함양 영원사 승탑군","c":"시도유형문화유산","nc":"","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642686.jpg"},{"q":"○○○는 청동기시대의 대표적인 무덤으로 고인돌이라도 부르며, 주로 경제력이 있거나 정치권력을 가진 지배층의 무덤으로 알려져 있다. 우리나라 고인돌은 4개의 받침돌을 세워 돌방을 만들고 그 위에 거대하고 평평한 덮개돌을 올려 놓은 탁자식과, 땅속에 돌방을 만들고 작은 받침돌을 세운 뒤 그 위에 덮개돌을 올린 바둑판식으로 구분된다. 전라남도 고흥군 과역면 도척리 월악산 줄기자락의 나즈막한 구릉에 길을 사이에 두고 남북으로 고인돌이 밀집해 있다. 북쪽에는 13기 중 현재 8기가 남아 있는데, 이중 큰 것은 길이 2.8m, 너비 2.35m이다.","a":"고흥도천리지석묘군","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"고흥군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662222.jpg"},{"q":"○○○은 건물을 짓거나 부분적으로 수리할 때 그 연유 또는 역사적 사실, 건물주의 번영과 안녕을 기원하는 내용, 찬문(撰文), 공역자(工役者)의 이름과 상량 시기 등을 기록한 문서이다. 그 종류로는 최초 건축 시 작성하는 창건 ○○○, 건물이 낡거나 수리할 때 작성하는 중수 ○○○, 기존 건물을 다시 지을 때 ○○○○○ 등이 있다. 『○○○○○』은 조선후기 서예가이자 학자인 추사 김정희(金正喜)가 33세였던 1818년(순조 18)에 쓴 ○○○이다.","a":"합천 해인사 대적광전 중건 상량문","c":"시도유형문화유산","nc":"","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2025042211360190.jpg"},{"q":"○○○는 고려 태조 18년(935)에 지었다고 전해지며, 수리하거나 다시 지은 기록은 전하지 않고 있다. ○○○○○은 원래 ○○객사의 문이었다고 하나 확실하지 않으며, 웅천향교에 있던 문을 1943년에 우담화상이 이곳으로 옮겼다고 한다. 앞면 3칸에 지붕 옆면이 사람 인(人)자 모양인 맞배지붕집이다. 지붕 처마를 받치기 위해서 장식하여 만든 공포는 기둥 위와 기둥 사이에도 있는 다포계 양식의 건물로 ○○○으로서는 규모가 대단히 큰 편이다. 공포는 복잡하게 짜여져 있고, 조각도 매우 화려하다.","a":"창원 불곡사 일주문","c":"시도유형문화유산","nc":"","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641693.jpg"},{"q":"○○은 조선시대 수령의 집무공간으로 일명 아헌(衙軒)이라고도 하며, 객사 다음으로 중요한 관아시설로 이청(吏廳), 무청(武廳), 향청(鄕廳) 등 각종 관아 건물의 중심이 되는 중요한 곳이다. 동래는 일본과 최접경지로서 한반도 제일의 관방이자 전략요충지로 중시된 만큼 일찍부터 읍성과 관아가 설치되었다. 조선시대에는 군사적 요충지로서 더욱 중시되어 태조 때부터 진을 두고 병마사가 판현사를 겸하도록 하였고, 명종 12년(1547)에 도호부로 승격되어 정3품 당상관으로 부사를 임명했다.","a":"동래부 동헌","c":"시도기념물","nc":"","r":"부산광역시","s":"동래구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645282.jpg"},{"q":"한개마을 북쪽 영취산 기슭에 자리잡고 있는 한옥으로 대문에서 내려다 보이는 가옥 경치가 눈길을 끄는 곳이다. 1911년 이전희씨가 지은 집으로 가묘와 별당은 1930년에 늘려 지은 것이다. 집 이름은 이전희씨의 부인이 초전면 월곡동에 시집왔다하여 붙였다고 한다. 건물들은 대문채, 안채, 사랑채, 중문채, 고방채, 사당 등으로 구성되어 있다. 정침이 一자형을 갖추고 있고 아래채, 고방채, 중문채 등은 튼 ㅁ자형으로 배치되어 있다. 대문채는 남쪽에 있으며 안채의 공간 구조는 규칙적이고 정교하다.","a":"대산동월곡댁","c":"시도민속문화유산","nc":"","r":"경상북도","s":"성주군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658645.jpg"},{"q":"경렬공 정지(1347∼1391)를 배향하는 사우이다. 후에 정지(鄭地) 외에 유사, 고중영, 전상의, 고경조, 정충신, 유평, 유성익 등 7인을 더 모셔 팔현사라고도 부른다. 정지는 나주 사람으로 고려 말의 왜구 창궐기에 수군의 기강을 바로 잡고 여러 곳에서 왜구를 대파하는 등 공헌을 하여 지방 사람들의 추앙을 받았다. 경렬사는 외삼문과 사당으로 소박하게 구성되었고 기와 이은 막돌담장으로 둘렀다. 솟을삼문에 들어서면 사당이 나오는데 사당은 앞면 3칸, 옆면 반칸 규모로 기둥 위에서 지붕을 떠받치는 구조가 익공양식이며 겹처마 맞배지붕 건물이다.","a":"나주경렬사","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"나주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2019051719533000.jpg"},{"q":"이 건물은 청송심씨 석촌공파 17세인 심덕활沈德活 공公이 요절한 아우 덕종德宗의 양자로 입적한 친아들 헌문憲文의 네 번째 돌을 기념하여 순조 6년1806에 건축하였다고 전하며, 21세인 의해宜海가 1900년에 보수하여 세거世居해 오면서 현재에 이르고 있다. ‘□’자형의 안채와 ‘―’자형의 사랑채로 구성되어 전체적으로 ‘□’자형의 배치형태를 취하고 있다.","a":"청송초전댁","c":"문화유산자료","nc":"","r":"경상북도","s":"청송군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663380.jpg"},{"q":"전북특별자치도 정읍시 고부면 ○○○ 두승산에 있는 높이 1.81m의 석불로, 현재는 무릎 이하가 땅속에 묻혀 있다. 몸에 비해 큰 머리에는 작은 소라 모양의 머리칼을 붙여 놓았으며, 그 위에는 상투 모양의 머리묶음이 큼직하다. 얼굴은 풍만한 인상이고 이목구비는 섬세하게 표현되지 않았다. 어깨는 얼굴에 비해 좁아 위축된 인상을 준다. 옷은 양 어깨에 걸치고 있으며, 가슴에 속옷이 보이고, 배에는 띠매듭이 표현되어 있다. 두 손은 큼직하게 표현하였는데 오른손은 위를 향하고 왼손은 엄지 손가락과 새끼 손가락을 맞대어 아래로 내리고 있다.","a":"남복리미륵암석불","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"정읍시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639512.jpg"},{"q":"무등산 서쪽 기슭에 있는 ○○○는 9세기 중엽에 철감선사가 지었다. 고려 선종 10년(1094)에 혜조국사가 수리하였으며, 조선 세종 25년(1443)에 김방이 다시 지었다. 그 뒤 임진왜란(1592) 때 불타 없어진 것을 광해군 1년(1609)에 짓고, 여러 차례의 수리를 거쳐 오늘에 이르고 있다. ○○○은 대웅전의 뒤편에 세워진 법당으로, 현재 무등산에 남아 있는 절 건물 중 가장 오래된 것이다. 오백나한과 10대 제자상을 모시고 있으며 이 고장 사람들의 평안을 기원하기 위해 지은 것이다.","a":"증심사오백전","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637149.jpg"},{"q":"김시습(1435∼1493)과 김효종(1414∼1493)의 뜻을 기리기 위해 조선 광해군 13년(1621)에 세운 사당이다. 김시습은 조선 전기 학자이며 우리나라 최초의 한문소설인 『금오신화』를 지은 인물이다. 지금 있는 ○○○는 흥선대원군의 서원 철폐령으로 잠시 폐쇠되었다가 1970년에 다시 세운 것이다.","a":"청일사","c":"문화유산자료","nc":"","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661038.jpg"},{"q":"○○○○는 사찰 입구에 설치하는 것으로, 절에 행사나 의식이 있을 때면 이곳에 당이라는 깃발을 걸어두는데, 이 깃발을 거는 길쭉한 장대를 당간이라 하고, 당간의 양쪽에 서서 이를 지탱시켜주는 두 돌기둥을 ○○○○라 한다. 이 ○○○○가 속해 있던 절의 이름은 알 수 없으나 동쪽에 있는 동부동5층전탑과 같은 절의 유적으로 보인다. 한국전쟁 때 일부가 파손된 이 ○○○○는 양 기둥에 아무런 조각을 새기지 않아 간결하며, 기둥 사이에는 당간을 꽂는 둥근 받침돌이 놓여 있다. 기둥 안쪽면에는 당간을 고정시키기 위한 홈을 파 놓았다.","a":"안동운흥동당간지주","c":"시도유형문화유산","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640430.jpg"},{"q":"풍호정은 합강동 평산 신씨 시조인 풍호공 신지(1424∼?)선생이 세운 정자이다. 신지는 고려 개국공신인 신숭겸의 18대손으로 강원도 원주에서 태어났다. 관직은 의영고 부상에 올랐고 청백리로 여러 선비들과 이 정자에서 강론하였다고 한다. 앞쪽에 흐르는 반변천을 바라보며 풍호정을 중심으로 오른쪽에는 비각이 있고 왼쪽으로는 ㅁ자형 민가인 주사가 일직선상에 배치되어 있다. 풍호정은 중앙마루를 중심으로 좌우에 온돌방을 두고 있으며, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양을 한 팔작지붕이다.","a":"풍호정주사","c":"문화유산자료","nc":"","r":"경상북도","s":"청송군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663063.jpg"},{"q":"동구 평광동 마을 앞 도로변에 있는 ‘효자 ○○○○○’은 조선 후기 인물인 ○○○의 효행을 기리기 위해 세운 정려 현판과 ○○○이다. ○○○은 어릴 때부터 효성이 지극하여 매우 가난한 가정 형편에도 50여년간 부모에게 지극한 효행을 행하여 마을 사람들에게 칭찬을 들었다. ○○○은 조선 순조 30년(1830)에 그의 아들이 세웠다고 한다. 순조 16년(1816)에 경상도 관찰사 이존수의 건의로 통정대부에 임명되는 동시에 효자로서 포상을 받아 정려 현판을 내렸다.","a":"효자강순항정려각","c":"문화유산자료","nc":"","r":"대구광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659496.gif"},{"q":"○○○란 임금이나 고관의 평생업적을 기록하여 그의 무덤 남동쪽에 세워두는 것으로, 이 비는 조선시대 전기의 문신 ○○○ 선생의 행적을 적고 있다. ○○○은 연산군 10년(1504)에 진사가 되고, 중종 4년(1509)에 문과에 급제하여 벼슬길에 올랐다. 직제학·승정원·동부승지 등을 지냈으며, 인종 때 윤임 일파의 탄핵으로 사직하였다가 명종이 즉위한 후 다시 임용되어 좌찬성에까지 올랐다. 비는 낮은 사각받침돌 위로 비몸을 세우고, 지붕돌을 올린 모습으로, 받침돌은 윗면에 연꽃무늬를 두어 장식하였다.","a":"소세양신도비","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"익산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639638.jpg"},{"q":"대구 달성군 화원읍의 ○○○와 성산리(城山里) 일대에는 과거 많은 ○○○가 분포했다고 한다. 그러나 지금은 이 곳에 있는 8기만이 유일하게 남북으로 열을 지어 있다. 3기는 화장사(華藏寺) 경내에 1기는 화장사 담에 걸쳐서, 4기는 화장사 바깥의 화원교도소 외곽에 위치하고 있다. 마을 사람들은 칠성바위라 부르고 있다. 이 곳의 ○○○는 부정형의 거대한 암석을 상석으로 하고, 일열로 배치되어 한 집단을 이루고 있다. 상석의 장축방향은 북동-남서간 선상에 있다. 지석의 유무는 외형상 확인되지는 않으나 원래 없었던 것으로 추측된다.","a":"천내리지석묘군","c":"시도기념물","nc":"","r":"대구광역시","s":"달성군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645393.jpg"},{"q":"『○○○○○』은 필사본으로서 이러한 모습의 것으로는 유일본으로 보인다. 이 책의 내용 가운데 노극홍의 시문은 약간의 글자 출입이 있다 하더라도 『광주노씨세고(光州盧氏世稿)』의 「옥촌고(沃村稿)」에 실려 있지만, 한강이 생질인 노극홍 및 그 생질의 아들과 손자에게 보낸 편지는 한강의 문집에도 실려 있지 않는 것이다. 한강문인록 또한 비교적 초기의 것으로 후대의 기록과 대조해 보면 한강 정구(寒崗 鄭逑)와 그 문인들의 학문 성향을 이해하는데 매우 중요한 자료이다.","a":"창녕 동산서당 한강연원록","c":"문화유산자료","nc":"","r":"경상남도","s":"창녕군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1665365.jpg"},{"q":"경주시 서악동에 있는 문무대왕의 친동생 김인문(629∼694)의 묘이다. 어려서부터 학문을 좋아하여 책을 많이 읽었고 특히 글씨를 잘써 태종 무열왕의 비문을 썼고 활쏘기와 말타기에도 능하였다. 또한 넓은 식견과 훌륭한 재주와 솜씨로 많은 사람들로부터 존경을 받았다. 20대에 당나라에 들어가 좌령군위장군이 되었고 신라에 들어와서는 군주가 되어 장산성을 쌓는데 감독을 맡았다. 외교술에 능하여 백제와 고구려를 멸망시킬 때 당나라에게 신라측 협조사항을 받아내는데 큰 공을 세워 신라의 삼국통일에 큰 역할을 하였다. 당나라에서 관직을 지내다가 효소왕 3년(694)에 죽었다.","a":"김인문묘","c":"시도기념물","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654438.jpg"},{"q":"충청남도 아산시 영인면 아산리에 위치한 석불입상으로, 화강암에 높이 265㎝, 너비 87㎝로 조각하였다. 목에 시멘트로 보수한 흔적이 있는데, 전하는 말에 의하면 청일전쟁 때 목이 절단된 채 방치되다가 1945년에 보수한 것이라 한다. 머리에는 관(冠)을 쓰고 있으며, 계란형의 얼굴은 양 볼이 통통하게 표현되었다. 당당한 체구에 옷은 왼쪽 어깨만을 감싸고 있는데 옷주름은 마멸로 인해 자세히 보이지 않지만, 배 아래에는 옷주름을 표현한 흔적이 보인다. 왼손의 손바닥에는 동그란 구슬이 올려져 있으며, 오른손은 엄지와 중지를 맞대고 오른쪽 가슴 앞에 올려 놓고 있다.","a":"영인석불","c":"문화유산자료","nc":"","r":"충청남도","s":"아산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661298.jpg"},{"q":"금강산의 한 사찰에서 모시다가 해방 이후 ○○○ 대웅전에 모시게 된 이 불상은 통견의 결가부좌로 손모양으로 보아 석가모니불로 생각된다. 조선후기에 만들어진 목조 ○○○ 가운데 그다지 크지 않지만 단정한 형태와 상호(相好)가 원만하게 표현된 수작이다. 보존 상태도 비교적 좋은 편으로서 양감 넘친 조각이 돋보이며 의습은 전형적인 조선 17세기 경에 제작된 불상과 양식상 유사한 점을 볼 수 있다. 다른 불상과 비교해 봤을 때, 이 불상은 17세기 중반 경에 만들어진 불상인 것으로 추정되며 조각적으로도 매우 뛰어난 기량을 지닌 작품으로, 보존상태도 양호하다.","a":"태백장명사목불좌상","c":"시도유형문화유산","nc":"","r":"강원특별자치도","s":"태백시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638286.jpg"},{"q":"천태산 서쪽 구릉지대에 있는 3기의 무덤들이다. 현재 봉분은 유실이 심하여 높이 2m, 길이 14m 정도의 원형무덤으로 처음에는 4m 정도의 높이였을 것으로 생각된다. 무덤은 구덩식돌방무덤(수혈식석실묘)으로 높은 봉분을 가지고 있는데 이러한 형태는 이 지방 특유의 양식으로 백제 전기에 속한다. 도굴에 의해 파괴된 무덤을 정리 조사한 결과 일부 유물이 일본 천황릉의 배총에서 출토된 것들과 같은 유형의 유물이었다. ○○○무덤들은 백제 문화의 일본전파와 두나라의 관계를 이해하고 연구하는데 중요한 자료이다.","a":"운학리고분군","c":"시도기념물","nc":"","r":"전북특별자치도","s":"정읍시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653520.jpg"},{"q":"○○○은 중종 28년(1533)에 ○○○ 송순(1493∼1582)선생이 관직을 떠나 선비들을 가르치며 여생을 보내던 정자로, 퇴계 이황을 비롯한 유명인사들과 학문에 대해 토론하던 곳이다. 조선 중기 문신인 송순 선생은 과거에 급제한 후 여러 벼슬을 거쳤으며, 말년에는 학문에 전념하면서 많은 책을 저술하였다. 처음 있던 정자는 선조 30년(1597) 임진왜란으로 파괴되어, 효종 5년(1654)에 후손들이 다시 지었다. 정자는 앞면 3칸·옆면 2칸 규모이며, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕이다.","a":"면앙정","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"담양군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653944.jpg"},{"q":"영사재는 반남박씨 집성촌인 논산시 상월면 대우리에 위치하고 있으며 예빈시 참봉으로 임명되고 후에 호조참판으로 추증된 박동민과 사헌부 집의를 지낸 아들 휘, 손자 박세기를 배향하는 재실로서 신도비, 묘표석, 처인 정경부인 전주이씨의 정려각 등 연계유적이 근처에 소재하고 있다. 인조 10년(1632) 창건된 후, 조선 숙종 20년(1694)과 그 후 몇 차례의 중수를 거치며, 원형을 보존하고 있으며 건물 전면에 영사재의 현판이 있고 내부에 중수기 등이 현액되어 있다.","a":"논산영사재","c":"문화유산자료","nc":"","r":"충청남도","s":"논산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661560.jpg"},{"q":"1920년에 왕궁 저수지의 둑이 완성된 후 이를 기념하기 위해서 송병우가 세운 누각이다. 지붕의 옆면이 여덟 팔(八)자 모양인 팔작지붕집으로 정자로서는 규모가 큰 것에 속한다. 정자 주변의 연못에는 중국에서 처음으로 흰색 연꽃을 갖다 심었다고 전한다.","a":"함벽정","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"익산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639559.jpg"},{"q":"신라 삼국통일의 중심인물인 김유신 장군과 신라 학자인 최치원, 설총을 추모하기 위해 세운 서원이다. 조선 명종 때 문신인 이정(1512∼1571)이 경주부윤이라는 벼슬을 지낼 때 지방 유림과 뜻을 같이하여 명종 18년(1563)에 세운 것이다. 선도산 아래에 ‘서악정사’로 세운 것은 임진왜란으로 소실되었고 1602년 묘우, 1610년 강당과 동·서재를 새로 지었다. 인조 원년(1623)에 국가가 인정한 사액서원으로 ‘서악’이라는 이름을 받았다. 흥선대원군의 서원철폐령 때에도 폐쇄되지 않고 살아 남은 47개 서원 중 하나이다.","a":"서악서원","c":"시도기념물","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654421.jpg"},{"q":"전국 유림들에게 항일의식을 드높인 자하 장기석 선생의 절개를 기리기 위해 세운 비이다. 장기석(1860∼1911)은 일찍 부모를 여의고 몹시 가난하여 공부를 하지 못하다 39세의 늦은 나이에 공부를 시작하여 43세에 학문을 두루 통달하였다. 그 뒤 후진양성을 위한 교육에 힘썼으며, 일제 때 경찰서장으로 부터 경축식에 참석할 것을 강요받았으나 이를 거절하여 대구형무소에 수감되었다. 그곳에서 단식을 시작하였고 의식을 잃어 일본경찰들이 음식을 먹이려 하자 그릇으로 서장을 때려 옥중에서 생을 마치었다. 비는 평평한 바닥돌 위에 비몸을 세운 간단한 형태이다.","a":"해동청풍비","c":"시도기념물","nc":"","r":"경상북도","s":"성주군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654534.jpg"},{"q":"하나의 화강암을 끝이 뾰족하게 다듬어 부처의 몸에서 나오는 빛을 형상화한 광배(光背)를 만들고, 그 위에 ○○○○을 돋을새김한 것이다. 둥근 얼굴에 살짝 감은 눈, 잔잔한 미소를 띤 입, 길게 늘어진 귀에서 원만한 인상을 풍기고 있다. 옷은 양 어깨에 걸쳐서 입고 있는데, U자형의 옷주름이 무릎까지 이어지고 있다. 오른손은 가슴까지 들어 손바닥이 밖을 향하고 손가락이 위로 향하고 있으며, 왼손은 손가락이 아래로 향하고 있다. 둥근 어깨와 양감있는 가슴, 잘록한 허리의 굴곡 등에서 통일신라시대 불상의 사실적인 모습이 나타난다.","a":"나주만봉리석조여래입상","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"나주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639906.jpg"},{"q":"남한산성 망월봉에서 남쪽과 북서쪽으로 뻗어 내린 두 능선의 계곡부에 있다. 조선은 임진왜란을 치르면서 도성수비의 필요성을 느껴 벽암 각성을 팔도 도총섭으로 임명하고, 전국의 승군을 동원하여 1624년부터 1626년까지 남한산성을 축성했다. 산성 축성 후에는 산성 방어를 위하여 산성 내에 9개의 사찰을 건립하고 승군이 머물게 했다. 9개의 사찰에는 모두 350여 명의 승군이 주둔했다. 망월사의 수비 담당 구간은 남한산성 동장대 구간이었다.","a":"망월사지","c":"시도기념물","nc":"","r":"경기도","s":"광주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1646450.jpg"},{"q":"화강암으로 된 높이 1.5m의 좌상으로 간송미술관에 전시되어 있다. 머리에는 작은 소라 모양의 머리칼을 붙여 놓았으며, 그 위로 상투 모양의 머리묶음이 큼직하게 솟아있다. 옷은 양 어깨를 감싸고 있으며 옷주름선의 표현에서는 형식화된 모습이 보인다. 손은 양 손을 가슴에 올리고 오른손으로 왼손 검지손가락을 감싼 형태로 ○○○○○이 취하는 일반적인 손모양이다. 불상이 앉아있는 4각의 대좌(臺座)에는 겹으로 연꽃무늬를 새겨 넣었다. 이 불상은 형식화된 옷주름 등을 고려할 때 고려 중기에 만들어진 작품으로 추정된다.","a":"석 비로자나불좌상","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"성북구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636113.jpg"},{"q":"고려시대의 명장 은열 ○○○ 장군이 태어난 곳이다. ○○○은 고려 목종(재위 997∼1009) 때 문과에 급제하였으며, 현종 3년(1012)에 동여진족이 쳐들어 오자, 도부서의 문연 등과 함께 격퇴하였다. 또한 1018년에 거란의 소배압이 10만의 군사를 이끌고 침입하자, 강감찬 장군의 부장으로 함께 출전하여 흥화진에서 적을 대파하였다. 그 공으로 응양상장군주국이 되고 이어 우산기상시에 올라 추성치리익대공신이 되었으며, 이듬해 지중추사병부상서가 되었다.","a":"진주 강민첨탄생지","c":"시도기념물","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654771.jpg"},{"q":"○○○ 선생의 숭고한 죽음을 기리고 있는 비로, 비가 자리한 이곳은 그가 왜적과 장렬히 싸우다 전사한 곳이기도 하다. ○○○ 선생은 조선시대 중기의 문신으로, 선조 25년(1592) 임진왜란이 일어나 서울이 함락되고 왕이 의주로 피신하였다는 소식을 전해 듣고는 고향인 장흥에서 6천여 명의 의병을 일으켜 의병장에 추대되었다. 황간, 영동 등지에 있던 왜적이 금산을 점령하고 장차 전주를 지나 호남지역을 칠 계획이라는 정보를 입수하여 충청의병장으로 있던 조헌에게 서신을 보내어 같이 형강을 건너 금산의 왜적을 칠 것을 제의하였다.","a":"고경명선생비","c":"문화유산자료","nc":"","r":"충청남도","s":"금산군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660921.jpg"},{"q":"조계종 화엄사에 딸린 말사로, 1196년(고려 명종 26) 보조국사 지눌이 창건하였다. 지눌이 수행할 곳을 찾다가 여기에 절을 지으면 '나라가 흥한다'는 신령한 노승의 말에 따라 지금의 자리에 절을 세우고 '○○○'라고 이름 지었다 한다. 몽골군의 침입으로 불타 없어졌다가 조선 시대에 다시 세웠으나 임진왜란과 정유재란을 겪으면서 법당과 요사가 완전히 불타버린 것을, 1624년(인조 2) 계특대사가 다시 지었다.","a":"흥국사","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"여수시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661962.jpg"},{"q":"충청북도 ○○군 청천면의 채운사는 고려 충렬왕 3년(1277) 도일 스님이 창건하여 수도암이라 하던 것을 혜식 스님이 이름을 고쳐 부른 것이라고 한다. 불상이 모셔져 있는 대웅전은 한국전쟁 때 인민군이 3번이나 불태우려 했지만 타지 않자 겁을 먹고 물러갔다는 일화가 전해진다. 불상은 오른손을 들어 손바닥을 밖으로 하고, 왼손은 무릎 위에 올려 설법하는 모양을 하고 있다. 전체적으로 정제된 조각기법을 보여주고 있으며, 만들어진 연대를 밝혀주는 유물이 불상 속에서 나왔다는 점에서 중요하다.","a":"괴산 채운암 목조여래좌상","c":"시도유형문화유산","nc":"","r":"충청북도","s":"괴산군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638693.jpg"},{"q":"순조의 셋째 딸 덕온공주의 남편 윤의선이 지은 집이다. 고종 2년(1865)에 지었으며, ㄷ자형 안채와 ㄱ자형 사랑채, ㄷ자형 중문간 행랑채, ㄷ자형 별채, 一자형 별당채로 구성되어 있다. 중대문에 들어서면 안마당의 전면에 안채가 자리하고 있다. 중앙 대청을 중심으로 오른쪽에는 건넌방이 있고 ㄱ자로 꺾여서 아궁이부엌·마루·사랑채의 침방으로 연결되는 방이 배치되어 있다. 대청 왼쪽에는 윗방과 안방이 있고 꺾여서 부엌과 찬마루가 놓였다. 안채 왼쪽 터에는 별당채가 자리잡고 있다.","a":"장위동김진흥가옥","c":"시도민속문화유산","nc":"","r":"서울특별시","s":"성북구","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658068.jpg"},{"q":"고려 말~조선 초의 명장인 ○○○ 장군의 묘이다. 1419년(세종 1)에 왜구의 침입이 더욱 심해지자 조정에서는 왜구의 소굴인 쓰시마섬(대마도)을 공격하기로 결정하였다. 이에 장군은 전함과 군사를 거느리고 쓰시마섬을 공략해 일본 규슈 본토까지 추격하여 항복을 받고 돌아왔다. 묘역은 부인 평양 조씨(平壤趙氏)와 합장한 단분(單墳; 하나의 봉분)의 형태이다. 1975년에 크게 정비하였고, 석물은 옛 것과 새 것이 섞여 있다.","a":"이종무장군묘","c":"시도기념물","nc":"","r":"경기도","s":"용인시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645977.jpg"},{"q":"문장가로 이름이 높았던 조선 후기의 문신 영재 ○○○ 선생이 살았던 ○○이다. 고종 3년(1866) 15세의 어린 나이로 문과에 급제하였으며 고종 11년(1874) 서장관으로 발탁되었고 충청우도 암행어사 등을 지냈다. 강직한 성격 탓에 세 번씩이나 유배되고 또 풀려났다. 그의 저서 『당의통략』은 파당을 초월하고 친족을 초월하여 공정한 입장에서 당쟁의 원인과 전개과정을 기술한 명저로 평가 받고 있다. 저서로는 『당의통략』외에 『명미당집』이 있다.","a":"강화 이건창 생가","c":"시도기념물","nc":"","r":"인천광역시","s":"강화군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2018112110380600.jpg"},{"q":"○○○ 책판 가) 개관 : 이 책판은 ○○○의 원집 17장과 습유 7장 등 도합 24장 12매로 구성되어 있다. 대체적인 크기는 가로 52.5cm, 세로 27cm, 두께 2cm이며, 광곽의 크기는 가로 32.5cm, 세로 20cm이다. 나) ○○○의 제작 경위와 그 주요 내용 및 특징 : ○○○은 무민당(无悶堂) ○○이 그 아버지 조계(釣溪) 박수종(朴壽宗, 1565∼1619)의 유고와 부록 문자를 정리하여 1627년에 제작한 것이다.","a":"영모록 및 박인 무민당집 목판","c":"시도유형문화유산","nc":"","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1643081.jpg"},{"q":"○○○는 청동기 시대 사람들이 만든 무덤으로 고인돌이라고도 한다. 무덤으로 보지 않고 제사를 지내는 제단으로 보는 견해도 있다. ○○○는 생김새에 따라 땅 위에 책상처럼 세우는 탁자식과 큰 돌을 조그만 받침돌로 고이거나 받침돌 없이 평평한 돌을 얹는 바둑판식으로 나뉜다. 우리나라는 세계에서 ○○○가 가장 많이 남아 있어 2000년에 인천광역시 강화군의 ○○○, 전북특별자치도 고창의 ○○○, 전라남도 화순의 ○○○ 등 3개 지역의 ○○○군이 함께 유네스코 세계 문화유산으로 등재되었다. 연천 ○○○○○는 고포리마을 동쪽 끝자락의 낮은 구릉사면에 위치한다.","a":"연천통현리지석묘","c":"문화유산자료","nc":"","r":"경기도","s":"연천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660013.jpg"},{"q":"향교는 훌륭한 유학자를 제사하고 지방민의 유학교육과 교화를 위하여 나라에서 지은 교육기관이다 처음 세워진 시기는 알 수 없으나 조선 순조 7년(1807)에 곤양군수 신오가 지금의 위치로 옮겼다. 향교내 건물들은 여러 차례 보수해서 현재의 모습에 이르고 있다. 공부하는 곳인 명륜당과 동·서재가 앞에 있고 사당인 대성전과 사당 출입문인 내삼문이 뒤에 있는 전학후묘의 형태이다. 그러나 특이하게도 대성전 좌우에 동·서 양무가 없고, 대성전의 위치 또한 명륜당 뒤의 오른쪽에 비스듬하게 세워져 있어 두 영역이 완전히 분리된 배치를 보이고 있다.","a":"곤양향교","c":"시도유형문화유산","nc":"","r":"경상남도","s":"사천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641921.jpg"},{"q":"○○○의 대변소 건물로 일주문과 범종루를 지나 대각암 가는 길에 있는 해천당 옆에 위치해 있다. ○○○는 백제 성왕 7년(529)에 아도화상이 비로암이라 하였던 것을 통일신라 헌강왕 5년(875) 도선국사가 ○○○라 고쳐 불렀다. 이후 고려시대 대각국사 의천이 더욱 크게 하여 대가람을 이루었다고 한다. 이 건물은 앞면 6칸·옆면 4칸 규모로, 지붕 옆면이 사람 인(人)자 모양인 맞배지붕이며 바람을 막을 수 있는 풍판으로 처리되었다. 정(丁)자 모양의 평면을 구성하고 있는 이 건물은 북쪽에서 출입할 수 있도록 되어 있다.","a":"순천선암사측간","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"순천시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662247.jpg"},{"q":"동춘당 송준길(1606∼1672)의 후학들이 그의 학문과 덕을 기리기 위해 세운 ○○○○의 ○○○와 강학공간으로 이용했던 정자인 ○○○이다. 송준길은 조선 효종∼현종 때의 문신으로 예학에 매우 밝았다. ○○○은 원래 현종 10년(1669) 동춘당 송준길이 학문을 연구하며 여생을 마치려고 이곳 검담에 세운 정자이다. 숙종 20년(1694)에 송준길을 기리기 위해 ○○○○을 세웠는데, 이 때부터 ○○○은 ○○○○의 강학공간으로 이용되었다. 고종 8년(1871) 서원이 훼철될 때 함께 없어졌다가 1920년대 초 다시 세워졌다.","a":"부강 보만정 및 검담서원 묘정비","c":"문화유산자료","nc":"","r":"세종특별자치시","s":null,"i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2022062113505900.JPG"},{"q":"조선 중종 때의 선비이자 김종직의 문인이었던 민구령 선생과 그 형제들의 시와 문집, 행적 등을 새긴 ○○이다. 민구령 선생과 그의 동생 구조, 구연, 구주, 구서는 평생 학문을 닦고 실천하며 우애가 돈독하여 향리에 그 평판이 자자하였다.","a":"오우실기 목판","c":"시도유형문화유산","nc":"","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642209.jpg"},{"q":"신성리 본당은 1903년 최초로 설립되었으며 현재의 공소 건물은 1909년 신축된 본당과 함께 사제관으로 건립되었다. 1936년 본당이 정읍 시내로 이전하고 본당 건물은 철거되었으나 사제관은 보존되어 공소로 활용되었다.","a":"천주교신성공소","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"정읍시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661863.jpg"},{"q":"동계 이운룡 장군과 향산 백신을 기리기 위해 세운 서원이다. 이운룡(1562∼1610)은 선조 18년(1585) 무과에 급제하였으며, 임진왜란 때 많은 공을 세워 경상우수사 겸 3도수군통제사에 이르렀다. 이 서원은 원래 이운룡의 출생지인 매전면 온막리에 상충사를 세우면서 유래되었다. 순조 14년(1814)에 이서면 금촌리로 옮겼으나 고종 5년(1848)에 흥선대원군의 서원철폐령으로 철거되고 남은 강당을 지금 있는 자리에 이전하면서 효충사라 이름을 바꾸었다. 그 뒤 1947년에는 서원을 고쳐 세워 오늘에 이르고 있다.","a":"금호서원","c":"문화유산자료","nc":"","r":"경상북도","s":"청도군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663113.jpg"},{"q":"19세기 말 20세기 초의 보살상으로 토제의 소형 보살상임에도 불구하고 부드러움과 자연스러움이 잘 표현되어 있고 전통적인 소조 기법으로 제작되어 희소성과 예배대상물로서의 빼어난 조형미를 지니고 있는 등 자료로서 가치가 크다.","a":"김해 관음정사 소조보살좌상","c":"문화유산자료","nc":"","r":"경상남도","s":"김해시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666686.jpg"},{"q":"조선 중기 고승 사명당(1544∼1610)이 태어난 곳이다. 경상남도 ○○ 출신으로 속명은 응규이며 호가 사명당이다. 중종 30년 풍천 임씨 집안에서 태어나 13세에 출가하여 직지사 신묵의 제자가 되었다. 금강산에 들어가 수도하던 중 선조 25년(1592)에 임진왜란이 일어나자, 의승병을 모아 의병장으로서 활약하였다. 1593년 명나라 구원군이 주축이 되었던 평양성 탈환 전투에 참가하여 공을 세웠다. 선조는 그의 공을 크게 인정하여 가선대부동지중추부사의 벼슬을 내렸으며 일본과 강화를 위한 사신으로 임명하기도 했다.","a":"밀양 사명대사 생가지","c":"시도기념물","nc":"","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1655589.jpg"},{"q":"향교는 공자와 여러 성현께 제사를 지내고 지방민의 교육과 교화를 위해 나라에서 세운 교육기관이다. ○○○○는 조선 선조 8년(1575) 가산리 성산에 처음 지었다가 인조 18년(1640)에 지금 있는 자리로 옮겼다. 지금 남아 있는 건물로는 ○○○을 비롯하여 동무와 서무, 명륜당, 동재와 서재, 고직사, 진강루, 신문(내삼문), 외삼문 등이다. ○○○에는 공자를 비롯한 4성과 중국 성현의 위패를 모시고 있으며, 동무와 서무에는 우리나라 성현의 위패를 모시고 있다.","a":"운봉향교대성전","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"남원시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661664.jpg"},{"q":"임진왜란 때 큰 공을 세운 충무공 이순신과 김완을 기리기 위하여 세운 건물로 원래는 자양면 노항동에 세웠으나, 정조 9년(1785)에 불타서 정조 11년(1787)에 다시 지었다. 그 후 세월이 흐르면서 퇴락한 것을 1960년 성곡동으로 옮겨 지으면서 수리하였다. 1976년 영천댐 건설로 인해 지금의 위치로 옮겨지었다. 가운데 2칸을 대청으로 꾸미고, 뒤쪽 1칸에 신주를 두어 위패를 모시도록 하였다. 기둥은 네모·여덟모·원형 등 세 종류를 사용하여 격조있게 하였다.","a":"동린각","c":"시도유형문화유산","nc":"","r":"경상북도","s":"영천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640374.jpg"},{"q":"신도비란 임금이나 고관의 평생업적을 기록하여 그의 묘앞에 세워두는 것으로, 이 비는 조선 중기의 문신인 ○○○ 선생의 공적을 기리고 있다. ○○○ 선생은 선조 18년(1585) 문과에 급제하여 벼슬길에 올랐다. 인조 때에는 공조판서를 지내기도 하였으며, 인조 14년(1636) 병자호란이 일어나자 조정의 명을 받아 영위사가 되어 80세의 노령에도 불구하고 강화도에 들어갔다. 이듬해 청나라 군대가 강화도로 몰려오자 아들에게 뒷일을 부탁한 뒤 스스로 목을 매어 생을 마쳤다. 이러한 그의 충절을 기려 ‘○○○’이라는 시호가 내려졌고 좌의정에 추증되었다.","a":"충숙공 이상길 묘역","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"노원구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636225.jpg"},{"q":"보문산공원 진입로 우측에 있는 정려각에 보관된 송두원과 그의 할머니 윤씨부인의 정려현판이다. 1745년 영조가 명정(銘旌)하였으며 유림에서 주관하여 건립하였다. 송두원은 우암 송시열의 조카인 송기학의 손자이다. 부모에 대한 효성이 지극하였으며, 음식을 철에 맞추어 손수 맛을 본 후에 올렸으며, 부모가 좋아하는 것은 무엇이든 구하여 드렸다. 부모상을 당하여서는 예법에 따라 정성을 다하여 장례를 치르고, 시묘 중 잠시도 상복을 벗은 적이 없었다. 산소에 흰제비가 날아와 둥지를 틀고 살았는데 사람들이 그의 정성이 하늘에까지 닿은 것이라 하였다.","a":"송씨양세정려","c":"문화유산자료","nc":"","r":"대전광역시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659754.jpg"},{"q":"○○○은 영일정씨 포은공파 28대 태용(1827~1895)이 만년에 서암을 건립하여 강학, 자수하였는데 그 후 암자가 무너지자 현손들이 서암 구지에 정자를 세워 ○○○이라 편액한 것이다. 정자는 정면 3칸 측면 2칸 규모의 팔작기와집이다. 정자의 주위에는 기와를 얹은 토석담장을 둘렀는데, 전면에 있던 사주문을 현재 허물어진 상태이다. 평면은 대청을 중심으로 좌우에 온돌방 1칸씩을 연접시킨 후 전면에는 반 칸 규모의 퇴칸을 둔 중당협실형(中堂挾室形)인데, 대청의 전면에는 4분합 들어열개문을 설치하여 마루방을 이루게 하였으며 퇴칸의 주위에는 평난간을 설치하였다.","a":"영주 내림리 모은정","c":"문화유산자료","nc":"","r":"경상북도","s":"영주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2020030409225501.jpg"},{"q":"○○○는 청동기시대의 대표적인 무덤으로 고인돌이라고도 부르며, 주로 경제력이 있거나 정치권력을 가진 지배층의 무덤으로 알려져 있다. 우리나라의 고인돌은 4개의 받침돌을 세워 지상에 무덤방을 만들고 그 위에 거대하고 평평한 덮개돌을 올려놓은 탁자식과, 땅속에 무덤방을 만들고 작은 받침돌을 세운 뒤 그 위에 덮개돌을 올린 바둑판식으로 구분된다. 경상남도 ○○시 장마면에 있는 이 고인돌은 바둑판식으로 원래 7기의 고인돌이 북두칠성 모양으로 무리지어 있었는데, 지금은 파괴되어 2기만 남아 있다.","a":"창녕 지석묘","c":"시도기념물","nc":"","r":"경상남도","s":"창녕군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654733.jpg"},{"q":"고종 2년(1865)에 ○○○에게 100세가 넘은 것을 축하하기 위해 관직을 수여한 병풍첩이다. 상·하 2책으로 되어 있는데 연대는 오래되지 않았다. 100세가 넘은 ○○○에게 지중추부사를 내림과 함께 원로대신과 조정대신 108명이 직접 손으로 쓴 시문이 적혀 있다. 상권은 60매이며, 크기는 가로 50㎝, 세로 35.5㎝이다. 하권은 62매이며, 크기는 가로 50.2㎝, 세로 34.8㎝이다. 이 병풍첩은 100세가 넘은 사람에게 수여한 관직첩으로는 매우 희귀할 뿐 아니라 축하하는 시문이 대개 유명한 사람들이 쓴 것으로 명작과 명필로 평가되고 있다.","a":"이용화백세영수첩","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"남원시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639615.jpg"},{"q":"계초심학입문(誡初心學入文), ○○○○○ 등 10책 모두 370년이 넘은 고전적(古典籍)이며, 불교사의 희귀 자료이다. 2004년 성주사 안심료(安心寮)에 임시 봉안된 불상을 지장전 건립과 함께 이전하여 개금(改金) 및 개채(改彩)하면서 지장보살불의 복장유물을 확인한 결과 지장보살과 시왕을 비롯한 권속일체가 1681년 신조된 사실과 조성한 화원 및 시주자 명단이 열거되어 있으며, 당시 성주사의 명칭이 웅신사(熊神寺, 곰절) 임을 알 수 있다.","a":"묘법연화경 권제1","c":"시도유형문화유산","nc":"","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2018102913382200.JPG"},{"q":"경상남도 ○○군 야로면에 있는 해발 757m의 ○○○ 정상부를 둘러 쌓은 산성이다. 삼국시대에 쌓은 산성으로 조선시대까지 계속하여 사용된 것으로 추정되는데, 지금은 다 무너져 옛모습이 남아있지 않다. 『동국여지승람』에 성의 둘레는 1,643척이고 성 안에 6개의 우물과 1개의 연못이 있다고 기록되어 있다. 이곳에서 멀지 않은 곳에 무덤들이 모여있어 가야 때에는 이 고장이 중심지였다고 여겨지며, 신라 때 야로현이라 하기 이전에 적화(赤火)라 불리던 시기의 유적으로 추정된다.","a":"합천 미숭산성","c":"시도기념물","nc":"","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1655113.jpg"},{"q":"언양 ○○○○은 울주군 상북면 명촌리 해발 297m의 산성산(山城山)의 8부 능선을 따라 돌로 쌓은 테뫼식 산성이다. 성내에서 삼국시대의 토기편이 출토되는 것으로 보아 삼국시대에서 조선시대까지 주로 왜구 방비를 목적으로 축조한 산성으로 추정하고 있다. 『언양읍지(彦陽邑誌)』에는 ‘둘레가 2천 척(尺)이고, 성 안에 우물이 있다.’고 했으며, ‘임진왜란 때에 의병(義兵)들이 주둔했던 곳’이라고 기록되어 있다. 따라서 이 성은 임진왜란 때 언양지역의 의병 활동과 관련하여 매우 중요한 의미가 있는 곳임을 알 수 있다.","a":"언양천전리성","c":"시도기념물","nc":"","r":"울산광역시","s":"울주군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645890.jpg"},{"q":"이 책은 포은 정몽주(1337∼1392) 선생의 시집으로, 포은 선생의 아들 정종성이 숙부인 정도가 초록한 『사일본영시(使日本詠詩』, 함전림이 집록한 『봉사명조행록(奉使明朝行錄)』과 그 외 여러 곳에서 모은 부친의 시를 더 추가하여 세종 21년(1439)에 개판한 초간본의 후쇄본이다. 부산광역시립시민도서관에 소장 중인 『○○○○』는 조선시대에 간행된 후쇄본이기는 하지만 임진왜란 이전의 판본이 확실하며, 현재까지 이와 동일 판본으로 보이는 것은 국립중앙도서관과 서울대학교 규장각에서 소장하고 있는 것에 불과할 정도의 귀중본으로 국가유산적 가치가 높은 책이다.","a":"포은시고","c":"시도유형문화유산","nc":"","r":"부산광역시","s":"부산진구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636688.jpg"},{"q":"○○○ 마을에 있는 ○○○○이다. ○○○○는 물의 떨어지는 힘을 이용하는 동채방아와 흘러가는 힘을 이용하는 밀채방아의 두 종류가 있는데, 이 방아는 동채방아이다. 물이 잠시 고였다 떨어지는 구유가 56개로 구성되어 있고, 물레는 지름 250㎝, 폭 67㎝의 크기이다. 50m 쯤 떨어져 있는 보(둑을 쌓아 흐르는 냇물을 가두어 두는 곳)에서 물을 끌어 사용하고 있는데, 보의 위쪽으로 용소(龍沼:지하수가 솟아나오는 곳)가 마련되어 있어 풍부한 물을 공급받을 수 있는 좋은 조건을 갖추고 있다.","a":"정선백전리물레방아","c":"시도민속문화유산","nc":"","r":"강원특별자치도","s":"정선군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658189.jpg"},{"q":"안성 ○○○ 비로전에 봉안되어 있는 높이 109㎝의 석불상이다. 현재 드러난 부분으로 평면 팔각의 연화대좌임을 알 수 있다. 대좌위에 비교적 넓게 자리 잡아 안정감 있게 앉은 가부좌의 모습과 둥글고 당당한 어깨에 둥글고 유연한 신체 윤곽선, 신체에 전체적으로 볼륨감이 살아있으며 약간의 층단을 이루는 띠 모양의 옷주름 표현 등에서 통일 신라 말기의 불상 양식을 엿볼 수 있다. 나발(螺髮 ; 소라처럼 말린 머리카락)의 머리에는 육계(肉髻 ; 상투 모양의 머리묶음)가 표현되었다.","a":"안성운수암석조비로자나불좌상","c":"시도유형문화유산","nc":"","r":"경기도","s":"안성시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2018102211453800.JPG"},{"q":"영광 ○○○○은 1616(광해군 8)년에 조선조 개국공신인 이천우의 영정을 봉안하였는데, 이천우는 전라도의 왜구토벌에 공을 세웠고 그 후손이 담양에서 영광으로 이거하면서 향내 유림들과 함께 영당을 건립한 것이다. 조선후기 훼철 이후 강당은 서당으로 기능했으며, 1928년에 발의하여 1934년에 신실을 중건하였다. 건물 배치에 있어 중심축을 설정해 짜임새 있는 건축 모습을 보여주고 있으며, 각 건물의 구조도 무리없이 안정된 형태를 취하고 있다. 중건 이후의 보존관리 및 상태도 양호하며, 관련 자료도 잘 보존되어 오고 있다.","a":"영광묘장영당","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"영광군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662285.jpg"},{"q":"조선 전기 문신이자 5현 중의 한 사람인 일두 ○○○의 문집을 새긴 책판이다. ○○○은 김굉필과 김종직의 문인으로 무오사화 때 종성으로 유배되었다. 그리고 갑자사화 때에는 부관참시(部灌斬屍:죽은 시체에 형을 가함)를 당하였다. ○○○은 당시 성리학의 대가로 경사(經史)에 통달했으며 역행실천을 통해 많은 독서를 했으나 사화 때문에 저술이 거의 전하지 못하고 있다. 다만 얼마되지 않은 유집만 전할 뿐이다. 이 문집은 정구(鄭逑)와 ○○○의 증손자 정수민이 함께 수집·검수한 것을 인조 13년(1635)에 처음 발행하였다.","a":"정여창 일두문집 목판","c":"시도유형문화유산","nc":"","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641767.jpg"},{"q":"조선 세종 때부터 연산군에 이르기까지 7명의 왕을 섬기면서 도덕정치를 실천한 광릉부원군 이극배(1422∼1495)와 그 후손들의 묘이다. 이극배는 세종 29년(1447) 사마시에 합격하여 진사가 되고, 그해 식년문과에 정과로 급제하였다. 세조가 왕위에 오르는 데에 큰 공을 세워 좌익공신 3등에 기록되고, 이어 광릉군에 봉해졌다. 1459년 북방의 야인정벌 때 신숙주의 종사로 출전하였으며, 1462년 부터 이조·예조·병조·형조의 판서를 두루 역임하였다. 성종 10년(1479) 영중추부사가 되었고, 1481년부터 2년 동안의 흉년이 발생하였을 때에는 진휼사로 활약하였다.","a":"광주이씨 광릉부원군파 묘역","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"강동구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636270.jpg"},{"q":"○○○ 노랑굴은 노란 색깔의 표면을 가진 그릇을 생산했던 기와이다. 규모는 길이 810cm, 높이 117cm, 너비 300cm이며, 시멘트포장길 옆 완만한 자연 경사면에 자리잡고 있다. 이곳에서 동쪽으로 200m 정도 떨어진 거리에는 구억이 검으굴이 있다.","a":"구억리검은굴","c":"시도기념물","nc":"","r":"제주특별자치도","s":"서귀포시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657961.jpg"},{"q":"이 정자는 1911(辛亥)년에 윤우벽(1585∼1657)선생의 공적과 학덕을 기리고 강학하기 위하여 문중에서 건립하였다. 대문채와 서당을 일직선상에 배치하고 서당의 좌측으로 관리사를 배치하여 전체 형태는 ㄷ자형이며 정면과 측면으로 담장을 둘렀다 서당은 정면 4칸, 측면 2칸의 전, 후퇴집으로 실(室)은 좌로부터 방, 대청, 방, 방의 순으로 배열하였다. 막돌로 쌓은 기단위에 다듬은 초석을 놓고 그 위에 기둥을 세웠는데 기둥은 모두 각기둥을 사용하였다. 3량구조로 대들보위에 긴 사다리꼴의 판대공을 세워 종도리를 받게 하였고 퇴칸에서는 퇴보를 올렸다.","a":"합천 춘우정","c":"문화유산자료","nc":"","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1665222.jpg"},{"q":"조선 태종 때의 문신인 심은 이수(1374∼1430)를 모시고 있는 ○○○에 소장된 것으로, 이수와 관련된 서첩류와 편지, 부조묘와 ○○○ 창건에 관련된 자료 그리고 논밭을 매매한 문서 등 ○○○류를 포함하여 17건 91점이다. 이수는 41세때 문과에 급제하여 예문관 대제학, 이조판서를 지냈다. 시호는 ‘문정’이다. ○○○는 선조 23년(1590)에 호남의 유림들이 진원현 죽림동에 창건하였으나 정유재란 때 불타 없어져 순조 14년(1814)에 다시 중건하였다. 그후 고종 5년(1868)에 훼손되었던 것을 1947년 복원하였다.","a":"장성 죽림사 고문서 일괄","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"장성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640076.jpg"},{"q":"전남 장흥군 유치면 봉덕리에 위치한 ○○○의 ○○○○ 속에 들어있던 유물 중 하나이다. 『○○○○○』은 ○○○○바라밀경을 풀어 쓴 경전이다. ○○○○바라밀경은 줄여서 ‘금강경’이라고 부르기도 하며 우리나라에서는 반야심경 다음으로 많이 읽힌 책이다. 이 책은 본래 고려대장경에 속해 있었는데, 이 판본만 별도로 조선 전기에 간행한 것으로 보인다. 조선시대에 간행한 것에 대한 기록은 따로 남아 있지 않지만, 원판은 1236년 해인사대장경을 만들기 위해 설치한 기구인 대장도감에서 만들었다는 기록이 남아 있다.","a":"보림사사천왕상복장금강반야론","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"장흥군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2020022813485400.jpg"},{"q":"신안○○○○ 소장 ○○○ 3종(種) 7점(點)이다. 지정목록은 가정(嘉靖) 18년(1539) 주소종자녀분재기(朱紹宗子女分財記), 만력(萬曆) 5年(1577) 주춘영자녀분재기(朱春齡子女分財記), 천계(天啓) 3年(1623) 주량자녀분재기(朱樑子女分財記), 무자(戊子) (1708) 주찬문자녀분재기(朱纘文子女分財記), 을미(乙未)(1715) 주중휘자녀분재기(朱重徽子女分財記), 만력(萬曆) 22年(1594) 주량무과급제교지(朱樑武科及第敎旨), 옹정(雍正) 9年(1731) 예조입안(禮曹立案) (朱氏宗孫 고주중휘(故朱重徽)의 양자건)(5件 연접(連接)) 등으로 분재 문서들은 1…","a":"영해인량리주씨종택고문서","c":"시도유형문화유산","nc":"","r":"경상북도","s":"영덕군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641102.jpg"},{"q":"선운사 참당암 대웅전 안에 있는 입 지름 50㎝의 조선시대 범종이다. 종을 매다는 용뉴는 용이 네발을 종에 대고 웅크리고 있는 형상이다. 어깨부위에는 둥근 원으로 띠를 두르고, 원안에 범자를 양각하였다. 몸통 위쪽으로는 직사각형으로 외곽을 두른 보살입상을 4면에 주조하였고, 그 사이에는 사각형 모양의 유곽을 배치하였다. 유곽의 테두리는 빗살무늬로 장식하였고, 내부에는 꽃모양을 한 4개의 유두가 있다. 보살상 아래쪽으로는 간격을 두고 굵게 두 줄의 테가 돌려져 있고, 그 사이에 명문판이 불규칙하게 주조되어 있다. 입구 부분에는 빗살무늬를 새겼다.","a":"참당암동종","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"고창군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639596.jpg"},{"q":"이 책은 조선 후기의 문신인 단계 ○○○의 일기이다. ○○○은 17세에 진사에 합격하고, 20세에 문과에 급제하여 사간원 정언이 되었다. 32세에 벼슬을 버리고 고향으로 돌아왔다. 36세 때인 1862년에 부친이 민중봉기에 연루되어 임자도로 귀향가게 되자 같이 따라갔다. 41세 때에는 백성을 괴롭힌다는 어사의 거짓 상소로 인해 강원도 간성으로 1년간 귀향살이를 했다. 현재 이 책은 ○○○의 나이 23세(1849)부터 사망할 때까지 53년 동안 쓴 일기로, 모두 29책으로 되어있다.","a":"김인섭 단계일기","c":"시도유형문화유산","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641846.jpg"},{"q":"조선 숙종 때 청백리로 명성이 높았던 강파 권상임(1622∼1700) 공이 세운 살림집이다. 원래는 ㅁ자형 집이었으나 사랑채가 화재로 소실된 후 안채 앞면 왼쪽에 다시 지어 지금은 ㄷ자형 평면 구조를 보인다. 안채는 ㄱ자형 평면으로 오른쪽부터 안방·마루·방을 배열하였고 오른쪽 안방 앞면으로 2칸 규모의 부엌을 시설하였다. 안방은 곡식 등의 수납을 위한 공간인 도장방을 가지고 있다. 대청에는 쌍여닫이문을 2개씩 설치하여 여름은 물론 겨울의 실내온도조절 기능까지 고려하였다. 사랑채는 가운데 마루를 중심으로 양 옆에 온돌방을 각각 놓았다.","a":"강파헌정침","c":"문화유산자료","nc":"","r":"경상북도","s":"영덕군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663208.jpg"},{"q":"지석묘는 청동기시대의 대표적인 무덤으로 고인돌이라고도 부르며, 주로 경제력이 있거나 정치권력을 가진 지배층의 무덤으로 알려져 있다. 우리나라의 고인돌은 4개의 받침을 세워 돌방을 만들고 그 위에 거대하고 평평한 덮개돌을 올려놓은 탁자식과, 땅 속에 돌방을 만들고 작은 받침돌을 세운 뒤 그 위에 덮개돌을 올린 바둑판식으로 구분된다. 홍성군 구항면·은하면에 분포하고 있는 이 고인돌은 탁자식으로 모두 4기이다. 구항면 태봉리에 있는 고인돌은 4개의 받침돌 중 1개가 빠져 나간 상태이고, 나머지 3개는 약간 무너졌으나 비교적 양호한 편이다.","a":"홍성지석묘","c":"시도기념물","nc":"","r":"충청남도","s":"홍성군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1652003.jpg"},{"q":"이 ○○은 전체 평면이 팔각형인 팔각원당형(八角圓堂形) 부도로 탑의 옥신부(屋身部)와 상륜부(相輪部)가 없어지고 기단부(基壇部)와 옥개석(屋蓋石)만 남아 있다. 지대석은 방향이며 기단의 하대석은 각 면에 안상(眼象)을 조각하고 그 안에 사자문양을 부조(浮彫)하였으며. 위에는 운룡문(雲龍文)으로 정식하였다. 상대석은 두 겹으로 된 앙련(仰蓮)을 조각하여 옥신부를 받치도록 하였다. 기단 중대석에는 각 면에 문양을 양각하였으나 마멸되어 형태를 파악하기 어렵다. 옥개석은 추녀부부 끝을 살짝 들어 올려 경쾌한 느낌을 준다.","a":"합천 적연선사 승탑","c":"시도유형문화유산","nc":"","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642328.jpg"},{"q":"척화비란 쇄국정책을 실시하던 흥선대원군이 병인양요, 신미양요를 승리로 이끌면서, 서양세력을 배척하고 그들의 침략을 경계하여야 한다는 의지를 국민에게 더욱 강력히 심어주고자 서울 및 전국 중요 도로변에 세우도록 한 비로, 비의 규모나 크기에 대한 규정은 없으나 그 내용만은 똑같이 쓰도록 하였다. 함평공원 내에 자리하고 있는 이 비는 낮은 사각받침돌 위로 비몸을 세운 모습에 비몸의 윗변을 둥글게 다듬어 놓았다. 비문에는 “서양 오랑캐들이 침략함에 싸우지 않으면 화친을 해야하는데, 화친을 주장하면 나라를 파는 것과 같다.","a":"함평척화비","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"함평군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662168.jpg"},{"q":"조선 중기의 문신 허백당 김양진(1467∼1535) 선생께 제사드리기 위해 지은 건물이다. 김양진 선생은 여러 벼슬을 두루 거친 분으로 학행이 높고 청렴결백한 삶을 사셨다고 한다. 앞면 5칸·옆면 2칸 규모로 지붕은 옆면에서 볼 때 지붕선이 여덟 팔자 모양과 비슷한 팔작지붕이며 주변 건물들의 배치형태는 ㄷ자형으로 구성되어 있다. 건물 안쪽 재료를 짜 맞춘 수법과 문짝을 다는 부분의 구조수법들이 조선 중기 건축양식을 잘 간직하고 있어 귀한 자료가 되는 건물이다.","a":"대지재사","c":"시도유형문화유산","nc":"","r":"경상북도","s":"예천군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640621.jpg"},{"q":"○○○은 사적기에 의하면 성덕왕 19년(720)에 창건되었으며 고려 태조 1년(918) 證通國師가, 선종 1년(1084) 導生僧痛, 예종 2년(1107)에 慈淨國尊이 중수하고, 조선 세종 31년(1449)에 信眉禪師가 중수하였다. 수차례에 걸쳐 중건되다 소실된 것을 영조 11년(1735)에 卓融禪師가 소실된 것을 재창하였으며 순조 3년(1803) 就俊師가 중수하였다. ○○○극락전은 1976년 해체 복원하였으며 내부에는 아미타불상과 후불탱화, 신미대사의 탱화가 보존되어 있으며 현판 무량수(無量壽)는 공민왕 친필로 전한다.","a":"보은 법주사 복천암 극락보전","c":"시도유형문화유산","nc":"","r":"충청북도","s":"보은군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638932.jpg"},{"q":"조선 초기의 무신인 충무공 남이(南怡, 1441∼1468) 장군의 묘이다. 장군은 1467년(세조 13)에는 이시애의 난을 토벌하여 적개공신 1등에 봉해진 후, 다시 여진을 토벌한 공으로 이등군공에 올랐다. 그러나 1468년에 예종이 즉위하자 유자광(柳子光)의 모함으로 역모를 꾀한다하여 처형당하는 ‘남이의 옥(獄)’ 사건이 발생하였다. 묘역은 부인과 함께 매장된 쌍분(雙墳 ; 두개의 봉분)의 형태로 후대에 다시 정비한 것이다. 묘제(墓制)는 원형이 다소 변형되었으며, 석물은 옛 것과 새 것이 섞여있다.","a":"남이장군묘","c":"시도기념물","nc":"","r":"경기도","s":"화성시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645944.jpg"},{"q":"변종환 고가는 안채, 사랑채, 대문채, 곳간채 등 4동의 건물과 기타 대문, 헛간으로 구성되어있다. 안채와 사랑채는 일자형 병렬로 배치되어 남부지방 부농주택의 공통적인 배치 특성을 보인다. 안채는 팔작 홑처마지붕의 정면 4칸 측면 1칸에 전후퇴 갖춘 주두없는 납도리 5량가이며 장여수장집으로 평범한 동자주 대공으로 종도리를 받쳤다. 평면구성은 좌로부터 부엌, 방, 대청, 방이 각각 1칸씩으로 배설되어 있다. 부엌방 앞에는 쪽마루가 있으며 평난간이 둘러져 있다.","a":"거창 사병리 변씨고가 2","c":"문화유산자료","nc":"","r":"경상남도","s":"거창군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2018101516334300.JPG"},{"q":"강원특별자치도 강릉시 성산면 보광리 ○○○ 봉우리에 있는 산성으로, 둘레는 약 4㎞이다. 기록에 의하면 이 산은 보현산이라 하고 산성은 보현산성으로 불리며, 둘레가 1707척이라고 하였다. 대관령과 연결된 산맥에 자연적인 산세를 이용하여 쌓은 산성으로, 소금강에 있는 금강산성과도 연결되어 있다. 북쪽의 성벽은 험준한 절벽을 이용해 쌓았는데 거의 붕괴되었고, 지금은 남쪽 방면으로 높이 2m 정도의 성벽이 남아 있다. 남쪽의 성벽은 다듬지 않은 돌을 이용하여 쌓았으며, 동·서·북쪽에는 성문터가 남아 있다.","a":"강릉대공산성","c":"시도기념물","nc":"","r":"강원특별자치도","s":"강릉시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1647864.jpg"},{"q":"○○○란 조선 고종 때 병인양요와 신미양요를 승리로 이끈 흥선대원군이 서양세력의 침략을 온 국민에게 경고하고자 서울 및 전국 각지의 도로변에 세우도록 한 비로, 이 비도 그 중의 하나이다. 전국에서 유일하게 바위에 비문을 새겨 놓았으며, 비문에는 “서양 오랑캐가 침략하는데 싸우지 않으면 화해할 수 밖에 없으나 화해를 주장하는 것은 나라를 파는 것이니 자손만대에 경고하노라”라는 강한 경고 문구가 적혀있다.","a":"구미 척화비","c":"문화유산자료","nc":"","r":"경상북도","s":"구미시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662382.jpg"},{"q":"탱화란 액자나 족자형태로 만들어 법당에 걸 수 있게 만든 불교그림을 만한다. ○○○ 능인보전의 불상뒤에 걸려 있는 이 탱화는 비단 바탕에 채색하여 그렸으며, 크기는 가로 174.5㎝, 세로 111.5㎝이다. 소략한 존상의 형태와 음영법의 구사, 적색과 녹색의 탁한 색감이나 어두운 군청색을 남용한 점, 불화의 횡적인 구도와 그림에 나타난 상을 간략하게 나타낸 점 등 조선 후기 불화의 특징을 충실히 보여주고 있는 작품이다.","a":"지장사 약사불도","c":"문화유산자료","nc":"","r":"서울특별시","s":"동작구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2018102513294700.jpg"},{"q":"향교는 공자와 여러 성현께 제사를 지내고 지방민의 교육과 교화를 위해 나라에서 세운 교육기관이다. ○○○○를 처음 지은 정확한 시기는 알 수 없지만, 조선 전기에 세운 것으로 보인다. 임진왜란 때 불탄 것을 인조 1년(1623)에 다시 세웠고 이후 여러 차례 보수를 거쳐 오늘에 이르고 있다. 건물은 공부하는 공간인 명륜당을 앞쪽에, 제사 공간인 대성전을 뒤쪽에 둔 전학후묘의 배치 형태를 보이고 있다. 안쪽에는 공자와 제자들, 우리나라 성현의 위패를 모시고 있다. 이외의 건물로 학생들의 기숙사로 쓰인 동재를 비롯하여 내삼문, 외삼문, 수직사 등이 있다.","a":"석성향교","c":"시도기념물","nc":"","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1652964.jpg"},{"q":"밀양시 ○○○읍 삼랑리 하부마을 산기슭에는 여러 개의 비석들이 몰려 세워져 있는데, 이 비석들은 모두 조선 후기 이곳에 조성되어 기능하던 後漕倉(三浪倉) 및 이 지역 주민과 관련된 업적을 남긴 역대 수령과 관찰사를 기리기 위해 세워졌다. 이들을 소개해 보면 다음과 같다. (1) 府使金侯仁大遺愛碑 ○○○○○ 창건 당시 밀양부사로 있으면서 ○○○ 조성을 위해 애쓴 김인대를 기리기 위해 1766년(영조 42) 주민들이 건립한 비이다. 화강석재로 관석과 대석을 갖추고 있다. 비신 크기는 49×23×131cm.","a":"밀양삼랑진후조창유지비석군","c":"문화유산자료","nc":"","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1665821.jpg"},{"q":"목천면사무소에서 병천으로 가는 길 왼쪽 산기슭에 있는 불상으로 원통형의 돌을 다듬어 만들었다. 갸름하면서도 복스러운 얼굴에 감은 듯한 눈, 오똑한 콧날, 작고 단정한 입 등이 단아하고 자비로운 인상을 준다. 양 어깨를 감싼 옷은 두꺼워서 신체의 굴곡이 거의 드러나지 않지만, 드러낸 가슴에서부터 무릎 아래까지 U자형의 옷주름을 표현하고 있다. 오른손은 손바닥을 정면으로 하여 손가락이 위로 향하고, 왼손은 손바닥을 정면으로 하여 손가락이 아래로 향한 손모양을 하고 있다. 전체적으로 통일신라시대의 불상양식의 전통을 잘 계승하고 있는 고려시대의 작품이다.","a":"용화사 석조여래입상","c":"시도유형문화유산","nc":"","r":"충청남도","s":"천안시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639100.jpg"},{"q":"경상남도 ○○에 있는 작품으로 화강암으로 된 자연암벽을 다듬어 불상을 도드라지게 새기고 있다. 마멸이 심하여 세부표현은 잘 알 수 없지만, 탄력있는 둥근 얼굴과 어깨까지 닿은 귀, 목에 있는 3줄의 삼도(三道) 등에서 뛰어난 조각수법을 엿볼 수 있다. 옷은 왼쪽 어깨를 감싸고 있으며 가슴에서 무릎까지 U자형의 옷주름이 표현되어 있다. 부처의 몸에서 나오는 빛을 형상화한 광배(光背)는 배(舟)모양이며, 머리광배는 2줄의 선으로 둥글게 표현하였다. 탄력있는 얼굴, 굴곡이 표현된 신체, 부드러운 옷주름 등으로 볼 때 통일신라시대에 만들어진 불상으로 보인다.","a":"창녕 감리 마애여래입상","c":"시도유형문화유산","nc":"","r":"경상남도","s":"창녕군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641446.jpg"},{"q":"고려 후기의 유학자인 이재(彛齋) ○○○ 선생의 묘소이다. 고려 충렬왕 1년(1275)에 문과에 급제하여 충선왕 때 첨의평리(僉議評理)로 상의회의도감사를 겸하였고 뒤에 상당군에 봉해졌다. 충렬왕 24년(1298)에 충선왕을 따라 원나라 연경에 가서 학자들과 교류하면서 10년 동안 성리학을 연구하고 돌아와 제자들을 가르켰다. 그의 문인으로는 이제현, 박충좌, 이곡, 이인복, 백문보 등이 있다. 우리나라에 처음으로 성리학을 들여온 사람은 안향이지만, 성리학을 본격적으로 연구하고 그 체계를 파악하여 확립한 사람은 ○○○이라 할 수 있다.","a":"남해 전 백이정 묘","c":"시도기념물","nc":"","r":"경상남도","s":"남해군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1655920.jpg"},{"q":"보(洑)라는 것은 논에 물을 대기 위하여 둑을 쌓고 냇물을 가두어 두는 곳을 말한다. 원래 정읍천과 태인천 상류에 농민들이 설치한 보가 있었으나, 고종 30년(1893) 고부군수 조병갑이 농민들을 강제로 동원하여 두 하천이 합류하는 하류지점에 새로 만석보를 축조하였다. 만석보가 완공된 후 가을에 새 보에 대한 수세라는 명목으로 많은 양의 쌀을 착취하자 농민들이 분개하여 1894년 전봉준을 중심으로 민란을 일으켜 동학농민운동의 발단이 되었다. 만석보는 농민들에 의하여 파괴되어 지금은 둑을 쌓았던 흔적만이 남아있다.","a":"만석보지","c":"시도기념물","nc":"","r":"전북특별자치도","s":"정읍시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653411.jpg"},{"q":"통일신라 후기의 학자이자 문장가였던 고운 ○○○ 선생의 ○○화로, ○○○○에 보존되어 있다. ○○○은 통일신라 6두품 출신의 지식인 가운데 가장 대표적인 인물로, 경문왕 9년(869) 당나라에 유학을 가서 그곳에서 과거에 급제하여 활약하기도 하였다. 그림은 검은사모에 관리의 집무복인 관복을 입고 두 손을 맞잡은 채, 주인공이 높이가 긴 의자에 앉아있는 전신좌상으로, 주인공을 풍만하게 나타내었으며, 크기는 가로 77.5㎝, 세로 108㎝ 이다. 가슴에 있는 흉배는 화려하게 표현한 반면 허리띠의 문양은 단순하다.","a":"하동 운암영당 최치원 초상","c":"시도유형문화유산","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641803.jpg"},{"q":"양산 ○○○○○은 고개를 약간 숙인 채 양손을 무릎 위에 각각 가지런히 두고 정면을 향해 가부좌한 보살상이다. 머리에는 두건(頭巾)을 쓰고 있으며, 어깨 뒤와 등 부분을 1/3 정도 덮고 있다. 결가부좌를 한 보살상으로 소장처에서는 법기보살이라 부르고 있으며 법기보살은 화엄경 보살주처품에 나오는 보살이다. 특히 우리나라에는 금강산 일대에서 법기보살들이 다수 제작된 것으로 알려져 있다. 이 불상은 상호·조각수법 및 착의법 등 전체적인 수법으로 보아 조선 후기에 조성된 것으로 문화유산으로 가치가 있다.","a":"양산내원사석조보살좌상","c":"문화유산자료","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1665089.jpg"},{"q":"○○○○○는 1923년 세운 사당으로 단종복위운동 때 사육신의 한 사람이었던 박팽년(1417∼1456)과, 사육신에 포함되지는 않지만 함께 복위운동을 도모했던 박심문(1408∼1456)을 모신 곳이다. 박팽년은 조선 전기 문신으로 1434년(세종 16) 문과에 급제한 후 1453년(단종 1) 우승지를 거쳐 형조참판이 되었으며 1455(세조 1)에는 집현전의 관원이 되었다. 단종이 왕위를 빼앗기자 성삼문 등과 함께 단종복위운동을 펼치는 중 발각되어 심한 고문으로 옥중에서 숨을 거두었다. 박심문 역시 조선 전기 문신으로 1436년(세종 18) 문과에 급제하였다.","a":"창계숭절사","c":"문화유산자료","nc":"","r":"대전광역시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659690.jpg"},{"q":"신도비란 왕이나 고관 등의 평생업적을 기록하여 그의 묘 남동쪽에 세워두는 것으로, 이 비는 조선 전기의 문신인 화산 권주(1457∼1505) 선생을 기리고 있다. 화산은 세조 3년(1457)에 태어나, 24세에 과거에 급제하여 벼슬길에 올랐다. 성종 20년(1489)에는 공조정랑으로 있으면서 질정관이 되어 요동지역을 다녀오기도 하였으며, 성종 24년(1493) 12월에서 이듬해 8월까지는 경차관이 되어 대마도를 다녀오기도 하였다. 연산군 3년(1497)에는 도승지에까지 이르렀으며, 1499년에는『성종실록』의 편찬에도 참여하였다.","a":"화산신도비","c":"문화유산자료","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662476.jpg"},{"q":"이 정자는 구휼(救恤)사업 및 육영(育英)사업과 독립운동가(獨立運動家)의 지원(支援)을 펼친 현장(現場事業處)로서 수봉 이규인(秀峯 李圭寅)(1859～1936) 선생이 1924년 서당(書堂)인 비해당(匪懈堂)과 약국(藥局)인 보인재(輔仁齋)를 갖춘 2층으로 건립하였으나 1953년 현재와 같이 단층으로 개수되었다. 선생은 사립(私立)의 경주고등보통학교(慶州高等普通學校)를 설립하여 구국(救國)의 인재(人材)를 양성하려 하였으나 끝내 조선총독부(朝鮮總督府)에 수탈(收奪)되어 경주공립중학교(慶州公立中學校)로 개교되고 말았다.","a":"수봉정","c":"시도기념물","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654567.jpg"},{"q":"현재 대웅전의 향우측에 모셔져 있는 이 그림은 화기(畵記)가 없어 정확한 제작연대와 화사는 알 수 없지만 작품의 경향으로 볼 때 19세기 말~20세기 초반에 제작된 작품으로 추정된다. 2폭의 그림이 상․하로 나뉘어 조성 되었는데 위쪽의 그림은 극락연지를 배경으로 아미타삼존이 청련화(靑蓮花) 위에 결가부좌하고 있고 연꽃이 만발한 연지 속에는 활짝 핀 연꽃 속에서 연화화생(蓮花化生)하는 장면을 그렸으며 아래쪽의 그림은 반야용선도(般若龍船圖)를 그렸다.","a":"안양암 극락왕생도","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2590616.jpg"},{"q":"동헌은 조선시대의 지방 관아건물로 고을의 수령이 일반 행정업무와 재판 등 공적일 일을 하던 곳이다. 백성을 잘 다스리고 사랑한다는 뜻의 ‘○○○’은 조선조 ○○현의 동헌으로 광무 8년(1904)에 오병선 군수가 서문을 썼다. 잘 다듬은 긴 돌로 쌓은 2단의 받침대 위에 네모난 주춧돌을 놓고 네모난 기둥을 세운 앞면 6칸·옆면 3칸의 건물이다. 오랫동안 ○○군청의 민원실로 사용되면서 뒤편으로 건물을 새로 지었고, 내부도 많이 변경되었던 것을 옛 모습대로 복원하였다.","a":"태안 목애당","c":"시도유형문화유산","nc":"","r":"충청남도","s":"태안군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639235.jpg"},{"q":"○○○○○의 재질은 조선후기 영남 지역에서 다수 사용되었던 불석(제오라이트)으로, 조선시대에 성행한 목조, 소조 불상과는 다른 이 지역 불상 재료의 특징으로 판단된다. 절대연대는 알 수 없지만 이 삼존불상의 양식을 통해서 17세기 불상 양식을 계승한 가운데 18세기의 도식적이고 평판적인 특징들을 확인할 수 있는데, 이렇게 판단된 조성 년대는 ○○○에 현존하는 <중수목판기(重修木板記)>의 내용과도 다소 부합되는 사실이어서 더욱 신빙성을 더하고 있다.","a":"운수사 대웅전 석조여래삼존좌상","c":"시도유형문화유산","nc":"","r":"부산광역시","s":"사상구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636776.jpg"},{"q":"‘○○○’은 조선 시대의 황희(黃喜, 1363년-1452년)가 관직에서 물러나 남은 인생을 보내던 곳으로, 임진강 주변 언덕에 세운 정자(亭子)를 말한다. 주변에 낙하진(洛河津)과 가깝게 있어 ‘낙하정(落河亭)’이라 하였으나, 임진강 주변을 가득 채운 갈매기들과 함께 놀겠다고 의미로 ‘○○○’으로 불렀다고 한다. ○○○은 조선 중기 의 학자였던 허목(許穆)이 지은 <○○○기(伴鷗亭記)>에 “정자는 파주 서쪽 15리 임진강 아래에 있고 조수(潮水; 밀물과 썰물) 때마다 백구(白鷗; 흰 갈매기)가 강 위로 모여들어 들판 모래사장에 가득하다.”라고 아름답게 묘사되어 있다.","a":"반구정","c":"문화유산자료","nc":"","r":"경기도","s":"파주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659864.jpg"},{"q":"충청북도 ○○군에 예부터 ‘말무덤’이라 불려 내려오던 신라계 무덤이다. 태종 무열왕의 사위 김흠운과의 관련설과 임진왜란 때 의병장으로 진주성에서 순절한 이의정 선생의 애마가 묻혔다는 이야기가 전해 내려왔다. 그러나 1933년 발굴조사 결과 7세기 중엽의 신라계 돌방무덤(석실분)으로 밝혀졌다. 25점의 출토된 유물들은 현재 충북대학교 박물관에 소장되어 있다. ○○○무덤은 이 지역의 역사성을 밝혀주는 중요한 유적 중 하나이다.","a":"영동 가곡리 고분","c":"시도기념물","nc":"","r":"충청북도","s":"영동군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1650345.jpg"},{"q":"1. ○○○○ 1책 이 ○○○○은 1588년 사마시 입격자 명부의 초본으로 책의 크기는 23.5×18.5cm이다 2. 경자○○○○ 이 방목은 하달한(1624∼1660, 자 통원)이 1660년(현종 1, 경술) 식년시에 진사 3등 제21인에 입격한 방목으로서, 목활자본이다. 책의 크기는 18.5×22.5cm이다 3. 숭정삼경술증광○○○○ 이 방목은 1790년(정조 14)에 실시된 증광시 진사 3등 제 35인에 입격한 하진백에게 반질된 것이다. 금속활자본으로서 크기는 22.0×33.5cm이다.","a":"진주 단지종택 사마방목","c":"시도유형문화유산","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642968.jpg"},{"q":"○○○터에 자리하고 있는 비로, 조선 중기 승려인 회은의 행적을 기리고 있다. 회은의 성은 기씨이며, 자는 응준으로, 회은은 그의 호이다. 어려서 출가하여 승려생활을 시작하였으며, 인조 때 병자호란이 일어나자 벽암대사가 모은 승병의 참모로 활약하였다. 조정에서는 그의 공을 높이사 절충과 양호도총섭에 임명하였고, 인조 25년(1647)에는 가선대부와 팔도도총섭에 이르렀다. 현종 원년(1660)에는 품계를 올리어 자헌에 이르고 승병대장이 되었으며, 현종 4년(1663)에 특별히 품계를 올리어서 정헌으로서 군무를 맡아 보았다.","a":"광양송천사지회은장노비","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"광양시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640118.jpg"},{"q":"하나의 커다란 광배에 얕게 조각된 불상으로, 불상의 왼쪽 몸광배 부분에 약간 금이 간 것을 제외하고는 전체적으로 보존상태는 좋은 편이다. 불상을 조각한 석판은 두께 약 20㎝ 정도 되는 편평한 돌로서, 앞에는 얕은 부조로 불상을 새기고 뒤에는 선각으로 또 한 구의 불상을 조각하였다. 앞면은 거신광(擧身光)의 가장자리를 따라 안쪽에 얕게 2중의 머리광배와 몸광배를 조각하고 그 안에 ○○○ 1구를 조각하였다.","a":"무송리석불좌상","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"고창군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639735.jpg"},{"q":"향교는 공자와 여러 성현께 제사를 지내고 지방민의 교육과 교화를 위해 나라에서 세운 교육기관이다. ○○○○를 세운 시기는 확실하게 알 수 없으나 기록에 따르면 조선 전기부터 있던 것으로 보인다. 배우는 공간으로 강당인 명륜당과 학생들의 기숙사였던 동재와 서재를 비롯하여 강학루와 전사청이 있고, 제사 공간으로 위패를 모시고 있는 대성전이 있다. 대성전 안쪽에는 공자와 그의 제자를 비롯하여 우리나라 성현들의 위패를 모시고 있다.","a":"정산향교","c":"시도기념물","nc":"","r":"충청남도","s":"청양군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1652985.jpg"},{"q":"○○○ 대웅전에 보존되어 있는 그림으로, 염라대왕의 심판 장면을 그린 것이다. 비단 바탕에 채색하여 그린 것으로, 둥근 구조 안에 현왕의 심판 장면을 그려 넣었는데, 왕의 당당한 체구와 세밀한 얼굴묘사에서 비교적 예스런 양식이 나타난다. 조선 고종 30년(1893)에 제작된 이 그림은 얼굴과 옷주름을 획일적으로 묘사하고, 꽃무늬와 구름을 단색으로 처리하고 있어 19세기 말에 나타난 불화의 경향을 그대로 보여주고 있다.","a":"지장사 현왕도","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"동작구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2588052.jpg"},{"q":"통일신라 ○○○의 능 앞에 세웠던 비석의 받침이다. ○○○은 신문왕의 둘째 아들로, 형인 효소왕이 아들이 없이 죽자 화백회의에서 그를 왕으로 추대하였다. 비는 원래는 비몸과 그 위에 머릿돌이 있었던 것으로 보이나 모두 없어지고 지금은 이 받침돌만 남아 있다. 받침의 거북은 목이 부러졌으며, 앞·뒷발에는 발톱을 새겨 놓았다. 등에는 6각형 무늬를 새겼으며, 중앙에 비몸을 꽂았던 네모난 홈이 파여 있다. 거북의 등에 새긴 무늬나 다른 덩굴무늬를 통해 8세기 전반의 작품으로 짐작된다.","a":"성덕왕릉귀부","c":"시도유형문화유산","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640424.jpg"},{"q":"봉수대는 횃불과 연기를 이용하여 급한 소식을 전하던 옛날의 통신수단을 말하며, 높은 산에 올라가서 불을 피워 낮에는 연기로 밤에는 불빛으로 신호를 보냈다. 이 봉수대는 진안군 주전면 대불리와 무능리, 그리고 완주군 운주면 고당리가 접한 해발 830m의 성재봉 꼭대기에 만들어졌는데, 이곳은 남쪽의 고달산 방면과 동쪽의 장수 장안산 방면에서 봉수를 받아 운주, 탄현으로 전하는 중요한 곳이었다. 울퉁불퉁한 천연의 암반 위에 잡석으로 쌓아올린 봉수대는 사각형으로 높이는 4∼5m이다.","a":"태평봉수대","c":"시도기념물","nc":"","r":"전북특별자치도","s":"진안군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653429.jpg"},{"q":"○○○○○을 비롯한 그의 장인과 장모, 아들 상산군 등 후손들의 묘역이다. ○○○○○은 조선의 2대 왕인 정종의 증손으로 덕천군의 손자이다. 전주 이씨 덕천군파로 분류되는 ○○○의 후손들은 조선 후기 양명학을 연구하여 강화학파를 형성하는 등 학문에 많은 영향을 끼쳤다.","a":"조석견과완성군이귀정묘역","c":"시도기념물","nc":"","r":"서울특별시","s":"동작구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1644817.jpg"},{"q":"조선후기 실학의 대가인 이익(李瀷, 1681~1763)의 묘이다. 이익은 25세가 되던 숙종 31년(1705)에 과거에 응하였으나 시험장에서의 녹명(錄名, 과거 응시자의 자격을 심사해 응시원서를 접수하던 제도)이 격식에 맞지 않았던 탓으로 시험에 응할 수가 없게 되었다. 바로 그 다음해 둘째 형 잠(潛)이 장희빈(張禧嬪)을 두둔하는 소를 올린 이유로 역적으로 몰려 옥사하게 되자, 벼슬의 뜻을 버리고 학문에 몰두하였다. 이익은 실증적이고 비판적인 태도로 학문에 접근하여 사회 현실을 역사적으로 고찰하고, 모든 학문은 실제 사회에 유용한 것이어야 한다고 주장하였다.","a":"이익선생묘","c":"시도기념물","nc":"","r":"경기도","s":"안산시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1646047.jpg"},{"q":"향교는 훌륭한 유학자를 제사하고 지방민의 유학교육과 교화를 위하여 나라에서 지은 교육기관이다. ○○○○는 태조 7년(1398)에 고사리재 기슭에 지은 것을 태종 7년(1407)에 옥서동 월계곡(지금의 당저리)으로 옮겼다가 세조 14년(1468)에 현재 위치로 옮겼다. 현재 향교에는 명륜당·동재·서재·대성전·동무·서무 등 여러 건물들이 있다. 향교의 앞쪽에는 배움의 공간으로 학생들이 공부하던 명륜당과 학생들의 거처인 동재·서재가 있다.","a":"삼척향교","c":"시도유형문화유산","nc":"","r":"강원특별자치도","s":"삼척시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638113.jpg"},{"q":"제주도 초가는 자연환경과 전통적 지리사상 사회구조, 생활양식, 가족구성 등 모든 문화요소를 바탕으로 슬기롭게 꾸며졌다. 이 초가는 서북쪽의 낮은 구름을 뒤에 두고 원당봉을 바라보면서 주변보다 낮은 곳에 자리한 제주초가의 전현으로 볼 수 있다. 밖거리 앞으로 곧고 긴 올레 양쪽에 우영팟(텃앝)이 있으며 마당을 중심으로 안거리와 밖거리가 마주해 있고 올레의 맞은 편에 눌왓(가리의 터)이 있는 二자형배치이다. 안거리는 마당쪽에 쳇방이 있는 4칸 집이고 밖거리는 왼쪽 한 칸이 헛간이4칸 집이다.","a":"삼양동초가","c":"시도민속문화유산","nc":"","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1659195.jpg"},{"q":"○○○는 청동기 시대의 대표적인 무덤으로 주로 경제력이 있거나 정치권력을 가진 지배층의 무덤으로 알려져 있다. 거대한 덮개돌[上石]이 지상에 드러나 있고 그 밑에 고임돌[支石], 묘역시설(墓域施設), 무덤방 등이 있는 구조를 가지고 있다. 하지만 지역과 시기에 따라 그 형태는 매우 다양하다. 일반적으로는 무덤방이 지상에 위치한 탁자식(卓子式)과 지하에 위치한 기반식(碁盤式) 또는 바둑판식으로 분류하고 있다. 그리고 지하에 무덤방이 위치하지만, 거대한 덮개돌 아래에 고임돌을 두지 않는 형식을 별도로 개석식(蓋石式), 또는 무지석식(無支石式)이라 칭한다.","a":"조남리지석묘","c":"시도기념물","nc":"","r":"경기도","s":"시흥시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1646399.jpg"},{"q":"○○○은 광평대군 이여(李璵 : 세종과 소헌왕후 사이에서 태어난 5번째 아들)의 7대손이다. 인조반정 때 공을 세워 정사공신 3등으로 책록되고, 정묘호란 때는 총융사 종사관으로서 큰 역할을 하였으며, 병자호란 때는 척화파(斥和派)로 청(淸)에 결사 항전할 것을 주장하였다. 효종의 북벌계획이 추진될 때는 전함 200척을 준비하는 등 북벌계획에 주도적으로 참여했다.","a":"완남부원군 이후원 묘역","c":"시도기념물","nc":"","r":"서울특별시","s":"강남구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1644887.jpg"},{"q":"현재 강원특별자치도 양양군 서면 서림리 상평초등학교 현서분교 교정에 3층석탑과 함께 보존되어 있는 불상으로, 1965년 가까운 논에서 발견되어 옮겨 놓은 것이다. 불상의 머리는 없어졌고 몸도 손상이 많은 상태이다. 두 손을 가슴에 모아 오른손으로 왼손 검지를 감싼 형태로 보아 ○○○○○을 표현한 것임을 알 수 있다. 8각형의 대좌(臺座)는 결실된 부분이 있지만 조각솜씨가 매우 우수하다. 밑받침돌 위에 4매의 석재로 구성된 하대석을 올려 놓았는데, 각 면마다 1구씩의 사자를 돋을새김하였다.","a":"양양서림사지석조비로자나불좌상","c":"문화유산자료","nc":"","r":"강원특별자치도","s":"양양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660556.jpg"},{"q":"조선 숙종(재위 1674∼1720) 때 문신을 지낸 송규렴(1630∼1709)이 지은 별당건물로 그의 호를 따서 ○○○이라 하였다. 앞면 3칸·옆면 2칸의 규모이며, 팔작지붕에 5량집 구조이다. 평면구성은 전체 6칸 집으로 우측 4칸은 대청이고 좌측 2칸은 온돌방이다. 온돌방 뒤쪽으로 1칸을 더 내어 상부는 다락으로, 하부는 함실로 사용하고 있다. ○○○을 지나면 ㄷ자형으로 된 안채와 ○○○의 아들인 송상기(1657~1723)의 호를 따서 이름을 붙인 일자형으로 된 사랑채인 ○○○가 전체적으로 튼ㅁ자형을 이루고 있다.","a":"제월당 및 옥오재","c":"시도유형문화유산","nc":"","r":"대전광역시","s":"대덕구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637189.jpg"},{"q":"조선시대 청도군의 객사로, 청도군을 ‘도주’라고도 부른다. 객사 안에는 수령이 초하루와 보름에 임금을 상징하는 위패에 절하는 곳인 정청과 중앙에서 파견된 관리나 외국사신이 묵고 갈 수 있는 숙박시설로 되어있다. 1670년 경인 조선 현종 때 지어진 것으로 보이며, 정청은 화양면사무소로 사용되면서 바닥과 벽이 바뀌었다. 그러나 건물의 나머지는 옛 모습을 보존하고 있다. 관아터에는 지방업무, 민사소송을 보던 동헌이 남아 있으며, 이 건물 앞에는 역대 군수들의 선한 정치를 기린 비가 서있다.","a":"도주관","c":"시도유형문화유산","nc":"","r":"경상북도","s":"청도군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640710.jpg"},{"q":"○○○는 통도사에 딸린 절로, 사명대사의 충훈을 추모하기 위하여 세운 ○○○당이 있는 절이다. ○○○은 부처님의 생애를 여덟 가지 모습으로 나누어 그린 탱화를 모시고 있는 곳이다. 이곳은 중생을 제도하기 위해서 이 땅에 오신 뜻을 기리기 위해 지은 건물이다.","a":"밀양 표충사 팔상전","c":"문화유산자료","nc":"","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664166.jpg"},{"q":"이 불화는 현재 ○○○○ 명부전 안에 봉안되어 있는 ○○○로서 ○○○○의 전(前) 주지인 혜광스님이 1950년경 도봉산 망월사(望月寺)에서 이관해온 것으로 전해진다. 화면은 가로가 약간 긴 직사각형으로 화면의 왼쪽(향우측) 가장자리를 따라 진채(眞彩) 기법으로 그려진 소나무 아래 산신(山神)이 호랑이를 대동하고 앉아있는 모습을 그렸다. 이 ○○○는 화기(畵記)가 남아있지 않아 정확한 조성연대와 화승(畵僧)등은 알 수 없으나 화풍으로 볼 때 제작연대가 19세기 후반 경으로 추정된다.","a":"법수선원산신도","c":"문화유산자료","nc":"","r":"서울특별시","s":"강남구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2018102317333700.jpg"},{"q":"19세기 말에 지은 안채와 1947년에 지은 사랑채로 이루어진 주택이다. 대나무가 우거진 뒷산을 배경으로 경사진 곳에 위치하고 있다. 안채와 사랑채 모두 그 시대의 일반적인 건축수법을 이용하여 만들었기 때문에 당시의 민가 건축기법을 확인할 수 있는 좋은 자료이다.","a":"나주홍기종가옥","c":"시도민속문화유산","nc":"","r":"전남광주통합특별시","s":"나주시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658359.jpg"},{"q":"현재 금륜전 안에는 중앙의 치성광불상을 중심으로 월광보살, 칠성, 동자, 동녀 등 11구의 상이 좌우로 배치되어 있다. 특히 중앙의 석조불상(치성광불상)은 무릎 위에 놓은 왼손 위에 둥근 지물(持物)을 들고 있어 그동안 약사여래(藥師如來)로 알려져 왔으나 칠성여래(七星如來)의 주불(主佛)인 치성광불(熾盛光佛)로 보는 것이 옳다. 북극성을 상징화한 치성광여래상(熾盛光如來像)은 『○○○지(安養庵誌)』에 1899년 제작 되었다고 기록되어 있다. 원래 석조상이 지만 현재는 석고가 두껍게 칠해져 있어 원형을 알기 어렵다.","a":"안양암 석 치성광불좌상 및 권속","c":"문화유산자료","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2018102314071000.jpg"},{"q":"구한말의 충신 장태수(1841∼1910) 선생이 순국한 집이다. 그는 철종 12년(1861) 문과에 급제한 후 여러관직을 거쳐 병고참의·대사간 등의 벼슬을 지낸후 고향에 돌아와 신명학교를 세워 인재를 길러 냈으나 일제시대 때 폐교되었다. 1910년 일본에게 주권을 빼앗기자 ‘자죄문’을 지어 나라를 잃은 것을 자책하고 단식으로 목숨을 끊고자 하였다. 단식을 하는 중에 ‘고대한동포문(告大韓同胞文)’을 주권회복을 호소하였고, 단식 20여일이 지난 11월 27일 생가에서 숨을 거두웠다.","a":"남강정사","c":"시도기념물","nc":"","r":"전북특별자치도","s":"김제시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653541.jpg"},{"q":"외래요소가 반영된 조선후기의 범종으로 종신의 명문을 통해 제작연대(1794년, 정조 18년)와 주종장(權東三) 등을 명확히 확인할 수 있어, 조선후기 범종의 양식적 변화와 주종장 계보 등 범종 연구에 귀중한 동종이라는 점에서 지정 보존가치가 있다.","a":"강릉관음사소장동종","c":"시도유형문화유산","nc":"","r":"강원특별자치도","s":"강릉시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638302.jpg"},{"q":"고려성은 동해가 내려다 보이는 괘방산(해발 384m)의 구릉 정상부 주변을 한겹 둘러싼 돌로 쌓은 산성이다. 지리적인 위치로는 바닷가에 위치한 해안성으로, 강릉지역의 주민들이 바다로부터 침략하는 적이나 약탈자들로부터 방어하기 위한 목적으로 쌓은 성이다. 성의 총 길이는 451m로 현재 남아 있는 성벽의 높이는 2∼3.5m정도이며, 가장 잘 남은 내벽의 높이는 2m정도이다. 현재 남아 있는 성벽은 서벽 25m, 남벽 55m정도이다. 성벽은 일대에서 쉽게 구할 수 있는 산돌을 이용하여 장방형의 불규칙한 석재를 사용하였다.","a":"강릉고려성","c":"시도기념물","nc":"","r":"강원특별자치도","s":"강릉시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1648704.jpg"},{"q":"맹암 김영렬(∼1404)의 유지를 받들고 후손을 교육시키기 위해 세운 서원이다. 김영렬은 조선 전기 무신이다. 정종 2년(1400) 제2차 왕자의 난을 평정하고 태종을 왕위에 오르게 한 공으로 태종 1년(1401) 익대좌명공신 3등에 오른다. 태종 4년(1404) 참판승추부사로 있을 때 왜선 1척을 싸워 빼앗고 왜병을 포로로 잡은 공을 세웠다. 후에 우의정에 증직되었다. ○○○○은 1945년에 세운 건물로 왕신평야가 내려다 보이는 솔 숲에 남향으로 자리잡고 있다.","a":"신천서원","c":"문화유산자료","nc":"","r":"경상북도","s":"예천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662668.jpg"},{"q":"○○○○ 생가는 고종의 황후로 개화기 국정에 참여하였으나 을미사변(乙未事變, 1895)으로 시해된 ○○○○가 태어나서 8살 때까지 살던 집이다. ○○○○는 철종 2년(1851) 경기도 여주에서 부친 민치록(閔致祿)과 모친 한창부부인 이씨 사이에 태어났다. 8세 때 부친이 타계한 뒤, 어머니와 함께 서울의 감고당(感古堂)에 와서 살았다. 감고당은 숙종비 인현왕후(仁顯王后)의 친정집이었다. ○○○○는 1866년 흥선대원군과 부대부인 민씨의 역할에 의해 16세 때 고종의 왕비로 간택되었다.","a":"명성황후생가","c":"시도유형문화유산","nc":"","r":"경기도","s":"여주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637405.jpg"},{"q":"○○○○○는 조선 후기의 유명한 유학자인 구암(龜巖) ○○의 묘로서 묘갈의 비문은 남인의 영수였던 미수(眉叟) 허목(許穆)이 지었으며 묘갈을 비롯한 묘역 내 석물들의 조각도 예술적인 가치를 가지고 있으므로 묘를 비롯하여 묘갈, 망주석을 포함한 묘역 전체를 경상남도 기념물로 지정","a":"진주 이정 묘","c":"시도기념물","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2017080217042600.JPG"},{"q":"향교는 공자와 성현께 제사를 지내고, 지방민의 교육과 교화를 위해 나라에서 세운 교육기관이다. ○○○○는 조선 전기에 세운 것으로 보이며, 임진왜란 때 불타 없어졌다. 전란 후에 다시 세운 후 여러 차례에 걸쳐 수리하였으며, 목천현지에 참봉 한혁이 지금의 자리로 옮겼다. 지금 남아 있는 건물은 제사지내는 공간인 3칸의 대성전과 각각 3칸의 동무·서무, 교육 기능을 수행하는 강당인 5칸의 명륜당, 학생들의 기숙사인 각각 3칸인 동재·서재, 2칸 내삼문 등이다. 대성전에는 공자를 비롯하여 중국과 우리나라의 성현들의 위패를 모시고 있다.","a":"목천향교","c":"시도기념물","nc":"","r":"충청남도","s":"천안시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1652870.jpg"},{"q":"원주 ○○○○○ 소장 ○○○○○참법은 성종 5년(1474) 간행한 원본에 비해 후에 인쇄된 것이나 오래된 고판으로 목판 인쇄기술사를 연구하는 중요한 자료적 가치를 지니고 있다.","a":"원주고판화박물관소장예념미타도량참법","c":"문화유산자료","nc":"","r":"강원특별자치도","s":"원주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660676.jpg"},{"q":"○○군의 대양면과 초계면, 율곡면의 경계가 되는 대암산(해발 591m)의 정상부를 둘러싸고 돌로 쌓은 산성이다. 이곳은 동쪽으로는 초계면, 북서로는 율곡면, 남서로는 대양면의 3개 행정구역이 접하는 곳으로, 주변의 많은 산 가운데에서 가장 높아 주위가 잘 바라보인다. 초계분지 전역은 물론 멀리 의령군 부림면의 미타산성(경상남도기념물 제231호), ○○읍내와 황강 등이 훤히 내려다보이고 있어 산성의 위치로서는 적합한 곳이다. 성의 길이는 대략 400m이고 폭은 150여m이다.","a":"합천 전 초팔성","c":"시도기념물","nc":"","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657040.jpg"},{"q":"향교는 훌륭한 유학자를 제사하고 지방민의 유학교육과 교화를 위하여 나라에서 지은 교육기관이다. 고려 공양왕 1년(1389)에 지어진 ○○○○는 원래 마산 서쪽에 있던 것을 선조 23년(1590)에 지금의 자리로 옮겼으나 임진왜란으로 인해 쇠퇴하였다. 그 뒤 순종 융희 1년(1907)에 대성전과 명륜당이 불에 타 없어졌고 1922년에 대성전을 다시 지었다. 현재 남아있는 건물은 대성전·명륜당·동재·서재 등이 있고 그 밖에 부속건물이 있다. 대성전은 공자를 비롯하여 여러 성현들의 위패를 모시고, 제사를 지내던 곳으로 제사 공간을 형성하는데 중심이 된다.","a":"제천향교","c":"시도유형문화유산","nc":"","r":"충청북도","s":"제천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638552.jpg"},{"q":"강원특별자치도 횡성군 공근면에 있는 ○○○ 3층석탑과 나란히 있는 돌로 만든 불상이다. 광배(光背)만 파손되어 흩어져 있을 뿐 불상이 앉아 있는 대좌(臺座)와 불신이 완전한 완전한 상태로 남아있다. 둥글고 복스러운 얼굴은 입가에 미소를 띠어 자비스럽게 보이는데 신라 전성기 불상의 이상적 사실미가 엿보인다. 당당한 가슴과 잘록한 허리, 무릎 위에 올려 왼손 손바닥이 위를 향하고 오른손의 손끝이 땅을 향하고 있는 자연스런 손모양, 양 어깨를 감싸고 있는 옷의 유려한 옷주름 등에서도 역시 이상적 사실미를 잘 나타내고 있다.","a":"상동리석불좌상","c":"시도유형문화유산","nc":"","r":"강원특별자치도","s":"횡성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637904.jpg"},{"q":"부인사계곡 아래쪽에 위치하고 있는 이 불상은 지상에 노출된 큰 바위 위에 돋을새김한 불상이다. 머리에는 작은 소라 모양의 머리칼을 붙여 놓았으며 길쭉한 얼굴은 풍만감을 주고 있다. 어깨는 당당하며 양 어깨를 감싸고 있는 옷에는 경직된 모습의 옷주름이 표현되었다. 손은 오른손을 위로 들어 손바닥을 밖으로 향하게 하고, 왼손은 손바닥을 밖으로 향하게 하여 내리고 있는 모습이다. 불상이 앉아있는 대좌(臺座)는 위와 아래를 향한 연꽃을 새겼는데, 위를 향한 연꽃 속에는 꽃무늬를 새겨 놓았다.","a":"신무동마애불좌상","c":"시도유형문화유산","nc":"","r":"대구광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636876.jpg"},{"q":"담양 ○○○에 소장된 조선후기의 목조 ○○○○○이다. 2005년 2월 확인된 복장물의 발원문(28.5cm×131cm)을 통하여 1660년 5월 15일 담양 용구산 회적암에서 ○○○불 1구를 조성하여 봉안(順治十七年庚子五月十三日造成彌陀一軀畢功安于龍龜山晦迹庵)했음을 알 수 있다. 불상의 형식은 촘촘하게 밀집된 나발에 상단 계주와 하단계주가 선명하며, 얼굴은 사각형이지만 턱 부분이 약간 좁으며 이마 중앙에는 백호가 돌출해 있고 예리하게 뻗은 가는 눈썹과 정면 아래쪽을 향하고 있는 일자형의 눈, 뭉뚝한 코와 사실적인 입술을 하고 있는 이목구비가 비교적 선명한 편이다.","a":"담양호국사목조아미타여래좌상","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"담양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662322.jpg"},{"q":"○○○는 1592년 일어난 임진왜란 때 일본군과 싸우다 전사한 부산지방의 순국선열이나 공을 세운 선열을 모신 곳이다. 엄밀하게 말하면 전쟁이 끝난 뒤인 1605년(선조 38)에 동래부사 윤훤(尹暄)이 동래읍성 남문 안에 동래부사 송상현(宋象賢)의 위패를 모신 송공사(宋公祠)를 지어 매년 제사를 지낸 것이 그 시초이다. 그 후 1624년(인조 2) 선위사(宣慰使) 이민구(李敏求)의 청으로 ‘○○○’라는 사액(賜額)이 내려짐에 따라 송공사는 ○○○로 이름이 바뀌었다.","a":"충렬사","c":"시도유형문화유산","nc":"","r":"부산광역시","s":"동래구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636623.jpg"},{"q":"조선 중기의 문신인 ○○○ 선생의 유적지에 있는 ○○ 유물이다. ○○○은 연산군 8년(1502) 문과에 급제하여, 그후 여러 벼슬을 지내다가 북쪽의 오랑캐를 무찌르는데 공을 세워 이조참판과 병조판서를 지냈다. 그의 유적지에는 네모 반듯하게 쌓아올린 무덤 1기, 문인○○ 2기, 하루방 모양의 무인○○ 2기, 망주석 2기, ○○○ 선생 둘째형의 묘 1기, ○○○ 부부의 묘 1기, 묘비 1기, 또 ○○○ 선생의 업적을 기록한 신도비 1기가 자리하고 있다.","a":"창녕 이장곤 묘 석상","c":"시도유형문화유산","nc":"","r":"경상남도","s":"창녕군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642186.jpg"},{"q":"고려 공민왕이 ○○○에 행차했을 때, 통도사에 있는 석가모니의 사리 가운데 일부를 이 곳에 옮겨오도록 하여 세워놓은 사리탑이다. 8각을 기본형태로 하여, 상 ·중 ·하 3단으로 이루어진 기단(基壇) 위에 탑신(塔身)을 올리고, 꼭대기에 머리장식을 얹어 마무리하였다. 기단에서 아래받침돌은 윗면에 비스듬히 경사를 주었고, 가운데받침돌은 모서리마다 기둥을 새겼으며, 윗받침돌은 솟은 연꽃무늬로 장식하였다. 둥근 탑신의 몸돌은 아무런 장식이 없고, 지붕돌은 윗면에 흐르던 급한 경사가 끝부분에 이르러 완만해 졌다.","a":"보은 법주사 세존사리탑","c":"시도유형문화유산","nc":"","r":"충청북도","s":"보은군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638417.jpg"},{"q":"조선 현종 2년(1661) 때 삼척 부사를 지낸 허목(1595∼1682) 선생과 관련이 있는 2기의 비이다. 허목 선생은 성리학을 발전시켰으며 제자백가와 경서연구에 전념하였고 특히 예학에 뛰어난 인물이었다 한다. ○○○○○는 정상리 육향산에 자리하고 있다. 원래 정라진앞 만리도에 세워 놓았던 것을 비가 파손되자 숙종 36년(1710) 이곳으로 옮겨온 것이다. 당시 이 지방은 파도가 심하여 바닷물이 마을까지 올라오고 홍수가 지면 주민의 피해가 극심하였다.","a":"삼척척주동해비및평수토찬비","c":"시도유형문화유산","nc":"","r":"강원특별자치도","s":"삼척시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637947.jpg"},{"q":"덕양마을 인근 산기슭에 넘어져 있던 탑으로, 1972년 마을사람들이 이곳으로 옮겨 세웠다. 탑은 전체의 무게를 받치는 기단(基壇)이 1층으로 되어 있으나, 원래는 2층이었을 것으로 보이며 그 위로 3층의 탑신(塔身)을 쌓아 올렸다. 기단의 네 면과 탑신부의 몸돌은 모서리마다 기둥모양을 본떠 새겼을 뿐 다른 꾸밈은 없다. 몸돌을 덮고 있는 각층의 지붕돌은 밑면에 4단의 받침을 두었다.","a":"청도덕양동삼층석탑","c":"시도유형문화유산","nc":"","r":"경상북도","s":"청도군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640462.jpg"},{"q":"논산 ○○○○○은 자연적인 거대한 암반에 불신을 선각하고 불두는 따로 조각하여 붙이는 형식으로 이루어져 있다. 불두는 소발의 육계가 높고, 눈을 감고 있으며 입이 좁고 얼굴은 길고 갸름한 편이다. 목에는 삼도가 표현되어 있고, 몸체는 법의를 양 어깨에 걸쳐 길게 드리운 통견의로 선각하였다. 이 ○○○은 수려한 조각수법과 온후한 상호가 인상적이며, 간결하면서도 사실적인 조각기법 등 불상의 양식으로 볼 때 전형적인 고려시대의 ○○○이다.","a":"논산상도리마애불","c":"시도유형문화유산","nc":"","r":"충청남도","s":"논산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639298.jpg"},{"q":"통일신라시대 학자인 고운 최치원(857∼?) 선생의 초상화이다. 최치원은 통일신라 경문왕 9년(869) 당나라에 유학 가서 그곳에서 과거에 급제하여 활약하였는데, 879년 황소의 난을 진압하고자 쓴『토황소격문』은 특히 유명하다. 초상화는 중국풍의 문인상 형식을 취하고 있으며, 가로 105㎝, 세로 74㎝의 크기이다. 선생의 초상화는 여러 곳에 보존되어 있는데 그 대부분이 승려의 모습인데 반하여, 이 그림은 각이 진 사방모를 쓰고 평상복을 입고서 편안한 자세로 부채를 손에 쥐고 앉아 있는 모습이어서 특별하다.","a":"고운영정","c":"시도유형문화유산","nc":"","r":"경상북도","s":"청도군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640609.jpg"},{"q":"이 영정은 ○○○ 우민선사의 좌안7분면 바닥가부좌상이다. 화면은 운보문이 가득한 녹색 상단벽면과 돗자리의 이단구도이며, 돗자리위에 방석을 깔고 왼손엔 불자의 병부를 쥐고 오른손으로는 불자의 술을 가볍게 쥔 채 앉아 있으며, 옆으로는 서안과 서책이 보인다. 화면 향좌측엔 ‘선교양종대선사○○○○○지진(禪敎兩宗大禪師日逢堂遇旻之眞)’의 화제가 있으며, 화면 크기는 가로 66.3cm, 세로 98.0cm이다.","a":"일봉당우민 진영","c":"시도유형문화유산","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/0000000001643032.JPG"},{"q":"청계(靑溪) 김진(金璡)이 살던 살림집으로, 증손자인 표은(瓢隱) 김시온(金是榲)이 ○○○라 편액하였다. ○○○는 정면 3칸 측면 1칸 규모의 맞배기와집이다. 평면은 대청을 중심으로 좌우에 돈돌방을 둔 중당협실형(中堂挾室形)인데 마루의 전면에는 판벽을 설치하여 마루방을 이루게 하였으며, 가구는 삼량가의 홑처마집이다. 주사(廚舍)는 재사의 우후측에 별도의 영역을 이루며 자리 잡고 있는데, 정면 4칸 측면 3칸 규모의 'ㄱ'자형 주사와 3칸 규모의 'ㅡ'자형 고방채로 구성되어 있다.","a":"영양돈간재및주사","c":"시도기념물","nc":"","r":"경상북도","s":"영양군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654653.jpg"},{"q":"주미산의 중턱에 완만하게 경사진 분지 일대에 자리 잡은 절이다. 주변에는 석등의 바닥돌과 자연 암반 위의 사리공, 탑의 부재, 자연초석, 석굴이 남아 있다. 석굴의 경우 인공의 흔적이 없는 자연동굴로 규모는 4∼5명 정도가 앉을 수 있는 작은 규모이다. ○○○는 공주의 서혈사터, 남혈사터와 함께 석굴사원이며, 출토유물로 보아 통일신라시대로 추정된다. 또한 『신증동국여지승람』에 절 이름이 있는 것으로 보아, 16세기까지 ○○○가 존재하였던 것으로 보인다.","a":"공주주미사지","c":"시도기념물","nc":"","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1652721.jpg"},{"q":"경상북도 문경시 산양면 봉서사(鳳棲寺)의 절터에 3층 석탑과 함께 서 있는 불상이다. 2구의 불상은 산의 중턱에 위치해 있는데 ○○○○○은 큰 바위의 한면에 조각되어 있고, ○○○○○상은 이곳에서 동남쪽으로 10m 정도 아래쪽에 위치한 작은 바위에 조각되어 있다. ○○○○○상은 원래 ○○○○○의 협시보살로 가까이 붙어 있었는데, 2차에 걸친 도난이 미수에 그쳐 현 위치에 존재하게 되었다고 한다. ○○○○○은 연꽃무늬 대좌 위에 앉아 있는데, 왼손에 약병을 들고 있으며 옷은 양 어깨를 감싼 형태이다.","a":"문경봉정리약사여래좌상및관세음보살입상","c":"시도유형문화유산","nc":"","r":"경상북도","s":"문경시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640990.jpg"},{"q":"마을의 중앙부 중심에 남서향으로 자리잡고 있는 집이다. 원래는 초가지붕에 통풍을 위한 구멍을 뚫은 까치구멍집이었으나, 1976년 지붕개량사업 당시 기와지붕으로 바꾸었다. 비교적 작은 규모의 이 집은 앞면 3칸·옆면 2칸 규모이다. 앞부분에 봉당을 중심으로 마구간과 부엌을 배치하였고, 뒷부분에는 안방·마루·사랑방을 배치하였다. 조선 후기에 만든 것으로 후대에 몇 차례 보수가 있었지만 비교적 원형을 잘 보존하고 있다.","a":"영주수도리박덕우가옥","c":"문화유산자료","nc":"","r":"경상북도","s":"영주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663214.jpg"},{"q":"기국정은 제남(霽南) 도상욱(都尙郁)이 후진양성의 장을 만들기 위하여 착공하였으나 공사 중 흉년으로 공사가 중단되자, 당시 성주목사인 성종인(成鍾仁)이 순시 중 그의 뜻을 치하하고 건립비용을 지원하여 정조 19년(1795) 2월에 완공한 건물로서, 오랫동안 문인학자들의 교류의 장이자 후진양성의 장소로 이용되어 온 곳이다. 도상욱은 특별한 경력은 없으나 학문이 뛰어나 많은 제자를 양성하였고 영남유림들과 널리 교류하였다.","a":"성주기국정","c":"문화유산자료","nc":"","r":"경상북도","s":"성주군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663244.jpg"},{"q":"중종 39년(1544년) 상주 목사 신잠(신숙주의 손자)은 문경시 산북면(당시 상주목 관할)에 ○○○당을 건립했다. 이후 지방유림의 공의로 홍언충과 이덕형 선생의 학문화 덕행을 추모하기 위하여 사당을 건립하고 ○○○○이라 하였다. 이후 1693년 김홍민과 홍여하 선생을 추가 배향하였다. 현종 10년(1669년)에 ○○○당이 ○○○○으로 정식적으로 승격이 되었으며, 정조 10년(1786)에 이구, 이만부, 권상일선생을 재차 추가 배향하여 모두 7현의 선현을 모시고 있다. 이러한 ○○○○○은 지난 2006년 1월 경상북도 유형문화유산으로 지정되었다.","a":"문경근암서원소장유물","c":"시도유형문화유산","nc":"","r":"경상북도","s":"문경시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641149.jpg"},{"q":"경상북도 청도군 청도읍 ○○○○○문 양쪽에서 서 있는 ○○○상이다. 절을 지키고 있는 이 ○○○상은 몇 조각의 나무를 이어서 만들었는데 높이가 3.4m∼3.8m로 상당히 큰 편에 속한다. ○○○이란 수미산(須彌山) 중턱에 살면서 동서남북을 지키고, 불법을 수호하는 신을 가리킨다. 각각 비파·칼·탑·여의주 등 가지고 있는데, 들고 있는 물건이 다를 뿐 다른 표현 방법은 비슷하다. 발로 악귀를 밟고 있지만 얼굴은 험상궂거나 분노하는 표정이 아니고, 오히려 웃음까지 짓고 있는 해학적인 모습이다. 이런 모습은 조선 후기 ○○○상에서 흔히 보이는 특징이다.","a":"적천사목조사천왕의좌상","c":"시도유형문화유산","nc":"","r":"경상북도","s":"청도군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640579.jpg"},{"q":"괘불은 옥외에서 법회를 행할 때에 밖에 내다 걸 수 있게 만든 걸개그림 형식의 불화로, 임진왜란 이후 많은 사찰이 복원되면서 괘불의 제작이 활발해졌다. ○○○에 보관되어 있는 이 괘불은 철종 7년(1856)에 제작되어 ○○○ 팔상전에 봉안했다는 기록이 있어 ○○○를 중건한 후 제작한 것으로 보인다. 내용은 석가여래가 영취산에서 제자들을 모아놓고 설법하는 모습을 그린 영산회상도로, 중앙에는 수미대좌 위에 항마촉지인(부처가 도를 터득하기 전 마귀들의 항복을 받을 때 취했다는 손의 모양)을 하고 있는 석가여래상을 크게 표현하였다.","a":"삼척영은사괘불","c":"시도유형문화유산","nc":"","r":"강원특별자치도","s":"평창군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638137.jpg"},{"q":"통일신라 후기 ○○○○가 사용했다고 전해지는 이 3개의 ○○○은 뚜껑이 있으며, 2개는 원통형이고 1개는 8각형으로 되어 있다. 뚜껑에는 꼭지가 달려있고, 앞면에는 철제장식을 세로로 길게 달아 자물쇠를 부착하였다. 양옆에는 고리를 상·하로 두 개씩 달았으며, 몸통 아래와 중앙의 개폐 부분은 철제로 띠를 돌려 단단하게 하였다. 윗부분에도 통이 벌어지지 않도록 철제를 부착하여 장식하였다. 실제 이 작품이 만들어진 시기는 기법이나 각종 철제장식으로 보아, ○○○○ 생존연대(827∼898)로 보기는 어렵고, 그 후인 고려 후기에 만들어진 것으로 추측된다.","a":"전도선국사직인통","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"순천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639846.jpg"},{"q":"○○○○○ 후사면 숲정이는 ○○○○와 ○○○○가 혼효된 식생 군락으로 경관적 식물생태학적 가치가 있다. 크고 작은 ○○○○는 총 140여 본으로 흉고 직경이 40~45cm 범위이고 수고는 4~6m로서 그 생륙도 활력도 비교적 양호하다. ○○○○ 노거수는 큰 것은 흉고직경이 75~80cm, 수고는 12~18m이다. ○○○○, ○○○○ 수령 및 식생분포로 보아 자연유산적 가치를 인정받아 전라남도 기념물로 지정되어 보존관리되고 있다.","a":"해남 서동사 동백나무·비자나무 숲","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"해남군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2019052022131900.JPG"},{"q":"청계산 등산로로 진입하는 고속도로 굴다리 입구 오른쪽에 미륵당이 세워져 있는데, 그 안에는 미륵불이 모셔져 있고 작은 규모의 3층○○이 있다. 미륵불은 약 2m 크기의 서 있는 모습으로, 고려말 조선초의 토속적인 양식을 띠고 있다. 원터마을의 수호신으로 여겨지며, 1년에 한번씩 주민들이 제사를 드린다고 한다. 이 미륵불에 지성을 드리면 길흉화복을 계시한다 하여 일본인들이 미륵불을 일본으로 반출하려다 실패한 일이 있었다. 미륵불의 신비한 영험으로 사람들이 계속 몰려들자 일본인들은 미륵불의 배꼽을 쪼아내었는데 그 후부터 미륵불의 영험한 능력이 상실되었다고 한다.","a":"원지동 석불입상 및 석탑","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"서초구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636274.jpg"},{"q":"대구에서 본격적인 선교활동이 이루어지던 1906년부터 1910년경에 건축된 사택으로, ○○○ 여사를 비롯해 계성학교 4대 교장인 헨더슨, 계명대학교 초대학장인 캠벨 등의 ○○○들이 거주했다. 전통 한식과 양식의 조화가 잘 어우러진 건물로, 1736년 조선 영조대 대구읍성 축조때 사용된 성돌(城石 : 대구읍성 철거시 가져와 사용)로 바른층 쌓기 기초를 하고 그 위에 붉은 벽돌을 길이 쌓기와 1단 마구리로 쌓았다. 지붕은 한식 기와를 이은 박공지붕이었으나 함석으로 개조되었다가 다시 기와지붕으로 개조되었다.","a":"선교사스윗즈주택","c":"시도유형문화유산","nc":"","r":"대구광역시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636882.jpg"},{"q":"봉수(烽燧)는 높은 산에 올라가서 불을 피워 낮에는 연기[燧]로, 밤에는 횃불[烽]로 급한 소식을 전하던 전통 시대의 통신 제도이다. 봉수제는 기록상으로 고려 중기(12. 3세기)에 나타나지만, 실제로는 삼국시대 이전부터 있었던 것으로 추정된다. 그러나 체계적으로 정비된 때는 왜구의 침입이 극심해진 고려 말과 조선 초기에 들어서였다. 봉수를 밝히는 ○○○는 대략 수십 리의 일정한 거리 간격으로 시야가 확 트인 산꼭대기에 설치하였다.","a":"합천 금성산 봉수대","c":"시도기념물","nc":"","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1656776.jpg"},{"q":"고려시대의 무신인 ○○○ 장군의 묘이다. 목종 때 문과에 급제하였으며, 현종 3년(1012) 안찰사로서 영일 등지에 쳐들어온 여진을 격퇴하였다. 현종 9년(1018) 거란의 소배압이 10만 대군을 이끌고 쳐들어오자 강감찬 장군의 부장으로 출전하여 흥화진에서 격파하였다. 그 공로로 1019년에 응양상장군주국·우산기상시가 되고 추성치리익대공신에 기록되었으며, 이듬해 병부상서가 되었다. 묘소는 예산군 대술면 이치리에 있는데, 반구형의 봉분 아랫부분에 잘 다듬은 둘레석을 둘렀다.","a":"강민첨장군묘","c":"문화유산자료","nc":"","r":"충청남도","s":"예산군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661426.jpg"},{"q":"1. 연혁 및 배치 ○○○ 고가는 광주안씨가 집중 세거하고 있는 청운리에 있는 주택이다. 1840년대에 의관 안봉원이 청운리로 옮겨온 뒤 그의 아들 형제가 가세를 일으켜 나란히 건축한 주택 가운데 하나이다. 큰 아들 훈재 안종문의 ○○은 문화유산자료 113호로 지정되어 있으며, 이 집은 작은아들 호재 안종익이 1935년(乙亥)에 건축한 건물이다. 구전에 의하면 건축비로 당시 논 50마지기에 상당하는 경비가 소요되었다고 한다.","a":"밀양 안세환 가옥","c":"문화유산자료","nc":"","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1665701.jpg"},{"q":"학포 양팽손과 장춘 양신용을 추모하기 위해 세운 서원이다. 양팽손(1488∼1545)은 중종 11년(1516) 과거에 급제하여 벼슬길에 올랐으나 기묘사화 때 사직되어 고향인 능주로 돌아왔다. 이 때 능주로 유배된 조광조와 많은 교류를 하였다. 글과 그림에 능한 그는 당시 신진사류의 한사람으로 활약하였다. 양신용은 양팽손의 증손으로 도호부사를 지냈으며 병자호란으로 상실된 국권 회복을 기원하다가 죽었다. ○○○○은 처음에 순조 21년(1821) 해룡면 중흥리에 사우를 지었다.","a":"용강서원","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"순천시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662061.jpg"},{"q":"안동 ○○○ 백화전에 보존되어 있는 그림으로, 비단바탕에 채색으로 그려진 ○○○○와 ○○○○이다. 탱화란 천이나 종이에 그림을 그려 액자나 족자 형태로 만들어지는 불화를 말한다. ○○○는 창건연대와 그 밖의 내력에 대해서는 전하는 바가 없으나 의상조사가 창건하였다는 사실과 도광 22년에 백화전을 중수하였다는 기록이 ○○○ 중수기에 기록되어 있다. ○○○○는 지장보살을 중심으로 좌우에 십대왕과 권속을 배치한 전형적인 조선후기 불화양식이며, 색조 또한 적록이 잘 조화되어 안정감이 있고 필치가 섬세하고 유려하나 현재 좀이 심하게 쓸은 상태이다.","a":"안동모운사지장탱화,제석탱화","c":"문화유산자료","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663392.jpg"},{"q":"○○○에 대한 기록은 『신증동국여지승람』제주목조에 나와 있다. 기록에 따르면 별방성은 돌로 쌓았는데, 둘레 2,390자(약 724m), 높이 7자(약 2m)라 한다. 조선 중종 5년(1510)에 목사 장림(張琳)이 왜선의 정박지가 근처의 우도(牛島)에 있어 위험하다고 판단하고, 성을 쌓은 뒤 금령의 방호소(防護所)를 이곳으로 옮겨 별방이라 이름지었다. 조선 헌종 14년(1848)에는 목사 장인식이 고쳐 지었다. 현재 성의 둘레는 950m이며 남쪽이 높고 북쪽이 낮은 지형을 이용하여 쌓았으며 성곽은 타원형을 이루고 있다.","a":"별방진","c":"시도기념물","nc":"","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657859.jpg"},{"q":"○○○에 보관된 이 ○○○는 ○○○를 다시 짓기 위한 목재보관소 옆에서 다른 장대석 등과 함께 출토되었는데, 명문을 보면 “이 산은 다만 제단과 옛 절 뿐만 아니라 국내에 있어서 대단히 중요하다. 이 산 전체를 영세토록 금지하여 보호할 일이다. 일영(日營)이 제목을 짓고, 신해(辛亥) 10월에 세운다.”라고 되어 있다. ○○○는 고려 의종 원년(1146)에 각화사 주지인 성원이 암자를 지으면서 개창되었다. 1896년에 불타버린 것을 이후 다시 지어 오늘에 이르고 있다.","a":"안동용수사금호비","c":"문화유산자료","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663290.jpg"},{"q":"○○○○은 전해오는 기록마다 명칭이 다르게 나타나는데 『신증동국여지승람』에는 ‘고산성’이라 하고, 『대동지지』에는 ‘운성’, 『호서승람』에는 ‘○○○○’이라 하였다. 성의 서쪽은 보존상태가 양호하며, 성벽의 높은 곳은 7m가 넘고, 나머지는 대략 2∼3m정도의 높이이며 폭은 4m정도이다. 성벽의 바깥으로 사각형식으로 덧붙여 만든 성벽인 치성은 3곳이 아직 남아있다. 성벽을 따라 돌 수 있게 낸 길인 회곽도가 4∼5m 폭으로 있으며, 성벽의 바깥쪽에는 돌을, 안쪽에는 흙과 잡석을 채워 그것을 한단한단 층을 이루며 쌓아올렸다.","a":"음성 수정산성","c":"시도기념물","nc":"","r":"충청북도","s":"음성군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1650606.jpg"},{"q":"○○○의 목조○○○○○은 민머리에 타원형 얼굴이며, 가늘고 길게 뜬 눈, 크고 반듯하게 선 코, 두툼한 입술, 커다란 귀, 미간 사이의 백호가 시원스러우나 개금불사로 인하여 내부의 재질과 목각기법 및 특징을 고찰하기 어려운 점이 있다. 목조○○○들은 타원형 얼굴에 작은 이목구비를 갖추고 있으며, 신체는 비례감이 맞으면서 세장하여 단아하다. 명부전에 모셔진 ○○○○과 ○○○, 판관상, 포졸 등 18구(軀)는 병자호란 이후 17세기 무렵에 제작되었다고 추정되며, ○○○○의 권속들이 완전히 갖추어져 있고, 파손이 없는 완형이다.","a":"김천개운사지장보살좌상및시왕상","c":"문화유산자료","nc":"","r":"경상북도","s":"김천시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663465.jpg"},{"q":"○○○○는 조선 정조 때 유학자 조술도(1729~1803)가 정조 14년(1790) 영양 원당리 선유굴 위에 학문을 가르치기 위해 세운 정자이다. 만곡 조술도는 학문과 후학양성에 힘을 기울였으며 시, 문장 및 예의와 절차를 지키며 술을 마시는 향음주례(鄕飮酒禮)에 관한 의식 등을 수록한 『만곡문집』을 편찬하였다. 이곳은 제자들이 주곡동으로 옮겨 짓고 ‘마운정’이라 하였다가 다시 지금 있는 자리로 옮기면서 ○○○○라 하였다. 왼편 온돌방 뒤쪽의 수장공간 및 폐쇄형 마루 등 독특한 구조를 지니고 있으며 조선 후기 양식을 잘 간직하고 있다.","a":"만곡정사","c":"문화유산자료","nc":"","r":"경상북도","s":"영양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663175.jpg"},{"q":"산지를 이용한 특이한 가람배치로 잘 알려진 ○○○는 숲으로 둘러싸인 자연조건이 아름다운 곳이다. 숲 한가운데 수많은 비석과 유물들이 있는데, 이 ○○○○도 소나무가 우거진 곳에 우뚝하게 자리하고 있다. ○○○○는 사찰 입구에 설치하는 것으로, 절에 행사가 있을 때 이곳에 당이라는 깃발을 걸어둔다. 깃발을 다는 길쭉한 장대를 당간이라 하며, 당간을 양옆에서 지탱해주는 두 돌기둥을 ○○○○라 한다.드물게 당간이 있으나 대부분은 두 기둥만 남아 있다. 이 ○○○○는 현재 기단(基壇)과 당간의 받침돌이 모두 사라지고 양쪽의 두 기둥만이 남아 있는 상태이다.","a":"범어사 당간지주","c":"시도유형문화유산","nc":"","r":"부산광역시","s":"금정구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636642.jpg"},{"q":"이 단은 1742년(영조 18) 동래부사 김석일(金錫一)이 세운 추념 제단이다. 본래 임진왜란 때 동래부사 송상현(宋象賢)이 순절한 정원루(靖遠樓) 터에 설치하였는데, 송상현을 비롯하여 동래성을 지키다 순절한 분들을 모셨다. 이 단이 세워지기 전에는 동래읍성의 남문 밖 농주산(弄珠山 : 동래경찰서 자리)에 임진왜란 때 순절한 분들의 전망제단(戰亡祭壇)을 세워 동래부사 송상현과 양산군수 조영규(趙英圭), 동래교수 노개방(盧蓋邦)을 비롯하여 동래성에서 순절한 분들을 모셨다. 1742년 ○○○이 세워지자 그 곳으로 옮겼다.","a":"송공단","c":"시도기념물","nc":"","r":"부산광역시","s":"동래구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1644974.jpg"},{"q":"○○○○○에 대한 역사적 기록은 보각국가 일연스님이 쓴 삼국유사(고려 충렬왕 7년에 군위 인각사에서 편찬한 삼국시대의 역사서)에 잘 나타나 있다. 이 기록을 살펴보면, 진평왕 9년은 정미(丁未) 587년이고, 갑신은 진평왕 46년(624년)을 가리킨다는 점에서 ○○○○이 세워진 시기에 논란이 있다. 그러나 진평왕 9년이라는 구체적인 시기의 거론과 당시 갑신년에 일어난 백제와의 긴박한 영토분쟁 관계를 놓고 보았을 때 정미년을 갑신년으로 표기상 오기(誤記)했을 가능성이 매우 높다.","a":"문경대승사사면석불","c":"시도유형문화유산","nc":"","r":"경상북도","s":"문경시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641196.jpg"},{"q":"고종의 아버지 흥선대원군 이하응(李昰應, 1820∼1898)의 무덤이다. 흥선대원군은 1907년에 흥선대원왕으로 추봉되었고 1908년에 무덤도 ○○으로 승격되었다. 묘역은 여흥부대부인(驪興府大夫人)과 합장한 단분(單墳 ; 하나의 봉분)의 형태이다. 묘역의 석물들은 백색 화강암으로 만들어 재질이 우수하며 조각기법은 수려하고 섬세하여 뛰어난 예술성을 보인다. 이는 왕실에서 제작하였기 때문인데, 근대 조선 왕실의 희귀한 능묘 석물이기에 더욱 중요하다.","a":"흥원(흥선대원왕)","c":"시도기념물","nc":"","r":"경기도","s":"남양주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1646091.jpg"},{"q":"“○○○○○”은 1698년 제작되어 전남 영암 성도암에서 개금(改金), 해남 대흥사에 봉안됐다가 1908년 제주○○○를 재 창건한 안봉여관스님이 1925년 대흥사의 말사인 제주 ○○○로 옮겨온 것으로 기록되어 있다. 전체높이 75cm, 얼굴높이 14cm, 어깨너비 34cm, 무릎높이13cm, 무릎너비 47cm이다. 17세기말의 전형적인 불상 양식을 갖춘 이 불상은 등신대의 단아한 상으로 삼산보관(三山寶冠)을 따로 쓰고 있다. 보관 정면에 커다란 꽃무늬 8송이가 배치돼 있고 좌우로 장식이 있는 전형적인 조선후기 보관이다.","a":"관음사목조관음보살좌상","c":"시도유형문화유산","nc":"","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1643290.jpg"},{"q":"화강암에 돋을새김한 불상으로 직사각형 모양이며 높이는 4m 가량 된다. 민머리 위에 상투 모양의 머리묶음은 분명하게 구별되지 않고, 4각형의 얼굴은 몸에 바짝 붙어있다. 손모양은 왼손을 들어서 배에 대고 오른손은 길게 내리고 있는데, 신체에 비해 너무 작게 표현되었다. 옷주름은 가슴 앞에 凹형 무늬와 왼쪽 팔에 걸쳐내린 4가닥의 옷자락 표현 등으로 간략하게 처리하였다. 얼굴과 몸 아랫부분에 금이 가 있는 이 불상은 단순하면서도 친근감 있게 표현한 조선시대의 지방화된 양식의 불상이다.","a":"영암학계리석불입상","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"영암군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639908.jpg"},{"q":"조선 인조와 효종, 현종연간의 무신인 매죽헌(梅竹軒) 이완(李浣, 1602∼1674) 장군의 묘이다. 병자호란에 출전하여 정방산성(正方山城) 전투에서 공을 세웠고, 이후 훈련대장과 병조판서의 임무를 맡아서 북벌을 준비하였다. ‘묘’는 부인 서산 정씨(瑞山鄭氏)와 합장한 하나의 봉분 형태이다. 묘제(墓制)는 원형을 유지하고 있으며 석물은 옛 것과 새 것이 혼합되어 있다. 봉분의 정면 오른쪽에는 묘표(墓表; 무덤 주인공의 이름 등을 새긴 비석)가 있는데, 규모가 크다.","a":"이완장군묘","c":"시도기념물","nc":"","r":"경기도","s":"여주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645953.jpg"},{"q":"경상북도 영주시 이산면 ○○○에 있는 ○○○○불로, 암벽 윗부분에 높이 78㎝, 어깨 폭 50㎝로 상반신만 조각하였다. 머리 뒤에는 둥근 머리광배가 있고 목에는 3줄로 새겨진 삼도(三道)가 뚜렷하다. 양 어깨를 감싼 옷은 주름이 부드러운 선으로 조각되어 전체적으로 아름다운 조화를 이루고 있다. 왼손은 가슴에 올려 구슬를 들고 있으며, 오른손은 아래로 드러워졌다고 여겨지나 미완성이다. 이 불상은 표현 수법으로 보아 신라말이나 고려초에 만든 것으로 추정된다.","a":"영풍두월리약사여래석불","c":"문화유산자료","nc":"","r":"경상북도","s":"영주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662860.jpg"},{"q":"조선 선조 때의 문신으로 임진왜란 때 소모관(召募官)이 되어 공을 세운 조호익(曺好益)의 종택이다. 조호익이 1603년경 지산촌으로 이거했다는 기록으로 보아 이때 건립한 것으로 추정된다. 가옥의 배치는 一자형의 안채가 남향으로 세워져 있고, 전면 좌측엔 ㄴ자형의 사랑채가, 우측엔 一자형의 헛간채가 있는데 전체적으로는 ㅁ자집 형태이다. 동북쪽으로 경역을 달리하여 사당이 한 단 높은 곳에 토석담장으로 둘러져 있다. 사랑채는 정면 4칸, 측면 4칸에 ㄴ자형 맞배지붕집이며 전체면적이 13.18평이다. 막돌기단 위에 각기둥을 사용한 3량가구집이다.","a":"영천 지산고택","c":"시도민속문화유산","nc":"","r":"경상북도","s":"영천시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/2019051911065300.jpg"},{"q":"봉업사지 북쪽 죽주산성 아래에 위치한 ○○○○이다. 통일 신라 여래상의 전통적인 양식을 충실히 계승하여 정제된 조각수법을 보이는 고려 전기 불상의 우수한 사례로 여겨진다. 절단되었던 머리와 신체를 접합하였으며 발은 최근에 복원하였다. 불상은 연꽃이 새겨진 둥근 대좌 위에 서 있으며, 광배는 남아 있지 않다. 민머리 위에는 육계(肉髻 ; 상투 모양의 머리묶음)가 큼직하다. 신체에 비해 약간 큰 얼굴은 둥글고 귀가 어깨까지 길게 늘어졌다. 이목구비가 비교적 작은 편이나 눈은 거의 감은 상태로 가로로 길다.","a":"안성죽산리석불입상","c":"시도유형문화유산","nc":"","r":"경기도","s":"안성시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637507.jpg"},{"q":"불교의식 법구의 하나로 17세기에 제작되었으나 2쌍 모두 놋쇠를 두들켜 만든 전통적인 방짜유기의 제작기법을 잘 보여주고 있다. 양손에 들고 맞 부딪혀서 소리를 내게 하는 승무용 악기이다. 주로 야단법석 전에서 수륙재나 영산재 같은 특별한 행사시에 사용하는 불구로서 양질의 지료를 사용하였음을 느끼게 한다. 1694년(강희 33년)에 제작된 약사성이 뚜렷한 작품으로 손잡이를 이용하여 양손에 들고 사용하는 것인데 현재는 손잡이가 훼손 결실상태이며, 동체만은 1쌍 모두 조금도 훼손없이 양호한 상태로 보관, 관리되고 있다.","a":"남해 화방사 바라","c":"문화유산자료","nc":"","r":"경상남도","s":"남해군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666677.gif"},{"q":"충남 아산시 신창면 읍내리에 있는 해발 183m의 학정산 정상의 산세를 이용하여 돌로 쌓은 성으로, 둘레는 약 500m 정도이다. 성은 산맥의 북쪽 맨끝에 쌓았다. 성의 서쪽은 산 정상부 가까이 성벽이 통과하고 있고, 동쪽 성벽은 산중턱 부근까지 내려와 있으며, 남쪽과 북쪽은 바깥쪽으로 볼록하게 튀어나와 있다. 성벽은 거의 무너졌으나 남동쪽의 성벽이 잘 남아 있는데, 성벽 바깥쪽의 높이가 6m 정도이고 성폭은 약 2m 정도이다. 성벽은 다듬은 돌을 이용하여 바깥쪽 면을 정연히 맞추어 쌓아올렸다.","a":"신창학성","c":"문화유산자료","nc":"","r":"충청남도","s":"아산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661302.jpg"},{"q":"○○○는 통일신라 애장왕 5년(804)에 세운 절로 법당과 부속 건물 및 여러 암자를 갖추고 있는 절이다. 적묵당과 마주보게 배치된 ○○○은 인조 1년(1623)에 계관법사가 지었고 여러 차례 보수를 거쳐 오늘에 이르고 있다. 앞면 7칸·옆면 7칸 규모이며, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양과 비슷한 팔작지붕이다. 식당과 강습소로 사용하고 있는 이 건물은 소박하면서도 간결한 옛 건축의 아름다움을 보여주고 있다.","a":"파계사설선당","c":"문화유산자료","nc":"","r":"대구광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659460.jpg"},{"q":"충청북도 ○○군 ○○○에 있는 이 여래좌상은 커다란 암석에 상반신만 두껍게 돋을새김하였다. 얼굴 생김새는 원만한 인상이며, 귀는 길게 늘어져 있고, 목에는 3줄의 주름인 삼도(三道)가 표현되어 있다. 얼굴 위로 연꽃줄기 위에 앉아 있는 3구의 작은 부처를 배치하고 있는 점이 특이하다. 하반신을 조각하지 않은 점 또한 특이하며, 전체적인 선이 둥글어 원만한 인상을 보여주고 있다. 이러한 신체 표현은 충청북도 ○○ 지역의 불교 조각 양식을 잘 보여주는 것이다.","a":"진천 산수리 마애여래좌상","c":"문화유산자료","nc":"","r":"충청북도","s":"진천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660748.jpg"},{"q":"1937년에 준공된 것으로 초가지붕을 연상하게 하는 아르누보풍의 부드러운 지붕선이 특징이며, 지붕처마 아래는 고전주의적인 수법(치형쌓기)으로 벽돌을 쌓아 처마선을 받쳐주고 있어 부드러움을 강조하고 있다. 측면부는 모서리 벽돌쌓기 수법으로 멋을 살렸으며, 네모진 창을 넓게 설치하여 지붕선과 나란히 조화를 이루며 환기를 원활히 하고 있다. 지붕은 마름모형의 망형 스레트를 파도치는 모습으로 이어서 생동감 있게 연출하였다.","a":"대전여중강당","c":"문화유산자료","nc":"","r":"대전광역시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659759.jpg"},{"q":"3폭의 조선후기 탱화는 화기(畵記)상의 기록으로 보아 안동(安東) 중대사(中臺寺)에 봉안된 것인데 언제 어떠한 연유로 ○○○에 이안(移安)되었는지는 알 수 없다. 한국사찰전서와 한국불교 사학대사전 기록에 의하면 중대사는 경상북도 안동군 풍산읍 서미동 학가산(鶴駕山)에 있는 절이다.","a":"안동대원사소장탱화","c":"시도유형문화유산","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641077.jpg"},{"q":"감정공 ○○○은 생물연대는 미상이며 선생의 본관은 안동(安東)이며 안동권씨 대동세보 기록에 의하면 선생은 벼슬은 군자감정(軍資監正)을 지냈으며 영남서부 일대에 세거하는 안동권씨 계파조(系派祖)인 감정공으로 호칭하고 있다. 묘비는 1693년도 제작된 것으로 전체높이 1.15m, 넓이 0.45m, 두께 0.17m 정도이며 봉분 둘레 19.1m, 높이 1.7m, 가로 3.16m, 세로 6.6m 로 평면 장방형계의 무덤으로서 여말선초 사대부가 무덤의 특징을 잘 보여 주고 있으며 묘비에는 ‘行監正安東權之墓’라 기록되어 있다.","a":"합천 권집덕 묘","c":"문화유산자료","nc":"","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666621.jpg"},{"q":"○○○는 백제 비유왕 24년(440)경 아도화상이 세웠다고 하나 확실하지는 않다. 다만 발견된 사리와 청동불두로 보아 통일신라 이전이나 같은 시대로 추정할 수 있다. 지금은 ○○○○, 영산전, 청향각, 삼성전 등이 있다. ○○○○은 앞면 3칸·옆면 1칸 규모로 지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕으로 꾸몄다. 지붕 처마를 받치기 위해 장식하여 만든 공포는 기둥 위에만 있는 주심포 양식이다. 건물 안쪽 천장은 우물 정(井)자 모양으로 천장 속을 가리고 있는 우물천장이며, 아미타불을 모시고 있다.","a":"죽림사극락보전","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"나주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662027.jpg"},{"q":"전라남도 나주시 다시면 회진리에서 영산강으로 흘러드는 작은 계곡과 계곡을 감싸며 쌓은 삼국시대의 산성이다. 성벽은 둘레가 2.4㎞에 달하는데 전남 지역뿐만 아니라 우리나라 삼국시대 토성 가운데서도 매우 큰 규모에 해당한다. 계곡 주변의 3면을 둘러싸고 있는 산지는 급경사의 절벽을 깎아내어 성벽을 만들었고, 계곡에는 폭 6m, 높이 6m 정도로 흙을 한층 한층 다져 성벽을 만들었다. 능선의 평탄한 곳을 이용하여 4개의 문을 만들었던 자리를 확인할 수 있고, 남쪽의 낮은 계곡에는 수문(水門)이 있었음을 확인할 수 있다.","a":"나주회진성","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"나주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654229.jpg"},{"q":"경상북도 경주시 내남면 마석산 암벽 위에 높이 4.6m에 달하는 커다란 불상으로 미완성인 채 조각되었다. 민머리 위에는 크고 둥근 상투 모양의 머리묶음이 있으며, 귀는 길게 늘어져 있다. 무표정한 둥근 얼굴에는 반쯤 뜬 눈, 큰 코, 굳게 다문 입술 등이 뚜렷하게 새겨져 있다. 목에는 3줄로 새겨진 굵은 삼도(三道)가 있으며, 양쪽 어깨에 걸쳐진 옷은 왼쪽 팔목에 3가닥의 층을 이룬 주름만이 있을 뿐 미완성이다. 오른손은 손바닥을 정면으로 하고 손가락을 위로 향하게 했으며, 왼손은 손바닥을 정면으로 한 채 손가락은 모두 아래로 향했다.","a":"백운대마애불입상","c":"시도유형문화유산","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640696.jpg"},{"q":"○○○○란 이름은 꽃이 필 때 나무 전체가 하얀꽃으로 뒤덮여 이밥, 즉 쌀밥과 같다고 하여 붙여진 것이라고도 하고, 여름이 시작될 때인 입하에 꽃이 피기 때문에 ‘입하목(立夏木)’이라 부르다가 ○○○○로 부르게 되었다고도 한다. 순천 ○○○○○는 농소마을 뒷산에서 마을 앞으로 흐르고 있는 좁다란 개울가에 심어져 있다. 지상 1.6m 정도에서 굵은 가지가 3개로 분리되어 크고 아름다운 모습을 형성하고 있으며 나무의 성장도 건강한 편이다. 나무의 나이는 약400년 정도로 보이며, 높이는 13m, 가슴높이의 줄기둘레는 3.5m에 이른다.","a":"순천평촌리이팝나무","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"순천시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654339.jpg"},{"q":"집 뒤의 소나무 숲이 매우 인상적인 집으로, 외부 공간의 구획이 매우 세련되었고 대지면적도 넓직하다. 집을 지은 정확한 연대는 알 수 없으나, 동쪽 헛간기와에 ‘강희 30년’(1691)·사랑채기와에 ‘가경 9년’(1804)이라는 기록이 발견되어, 19세기 초에 지어진 것으로 보인다. 대문간채와 사랑채·안채로 구성되는데, 사랑채와 안채는 ㅁ자형이다. 별도로 지은 대문간채는 대문을 중심으로 좌우에 2칸씩의 행랑채가 있다. 안채와 사랑채는 담장으로 구분되어 있다． 안채는 앞면 4칸·옆면 2칸의 겹집으로, 지붕 옆면이 여덟 팔(八)자 모양인 화려한 팔작지붕집이다.","a":"강릉 추산 고택","c":"시도유형문화유산","nc":"","r":"강원특별자치도","s":"강릉시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638060.jpg"},{"q":"이 정려문은 조선 중엽의 충신 ○○○과 그의 아들을 추모하여 1796년에 세운 정려이다. 정면 1칸, 측면 1칸의 겹처마 맞배지붕으로서 전면은 8각으로 치석한 돌기둥을 사용하였는데, 기둥의 높이는 180cm 정도이다. 정려각의 네 면은 홍살로 꾸며져 있으며, 정면에 “○○○○○”이라는 현판이 걸려있다. 내부에는 ○○○ 부자가 행한 충절의 내용을 기록한 1기의 비석과 3점의 현판이 있는데 비석의 크기는 141×55×25cm 정도이다.","a":"양대박부자충의문","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"남원시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661842.jpg"},{"q":"중국 당(唐)나라의 재상(宰相) 두우(杜佑,735～812)에 의해 편찬된 ○○○○은 중국 상고대(上古代)부터 당 현종(唐 玄宗)에 이르기까지의 식화(食貨)․선거(選擧)․직관(職官)․예(禮)․악(樂)․형(刑: 兵을 포괄)․주군(州郡)․변방(邊防)등 중국 역대 제도를 8典으로 분류한 책으로서 통전(通典)이라고도 한다. 남송(南宋)때 편찬된 정초(鄭樵)의 『통지(通志)』와 송말 원초(宋末 元初)에 편찬된 마단임(馬端臨)의 『문헌통고(文獻通考』와 함께 '3통(三通)'이라 불릴 정도로 중국 역대 제도문물사(制度文物史) 연구에 핵심이 되는 자료이다.","a":"두씨통전","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2590448.jpg"},{"q":"1910년경 현 소유주의 아버지가 지었다고 전하는 집이지만 세운 시기를 정확하게 알 수는 없다. 이 집은 해변의 숲과 넓은 들판을 앞에 두고 낮은 산을 등진 곳에 자리잡고 있는 ㅁ자 평면을 갖춘 집이다. 안채는 앞면 4칸·옆면 2칸 규모로 부엌 왼쪽에 안방과 상방·사랑방을 두고 앞쪽으로 곳간과 마구간을 두었다. 사랑채에는 대청과 광, 방을 배치하였는데 앞쪽으로 대청과 연결되는 툇마루가 있어 방을 연결시키고 있다. 헛간채는 ㄱ자형 평면을 갖추고 있으며 곳간과 닭장으로 사용하고 있다.","a":"강릉박치규가옥","c":"문화유산자료","nc":"","r":"강원특별자치도","s":"강릉시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660488.jpg"},{"q":"조면사(造麵寺)터로 전하는 곳에 자리하고 있는 탑으로, 주변에 기와 조각들이 흩어져 있어 절터였음을 알려주나 지금은 석탑만이 민가 골목길에 서 있다. 탑의 기단(基壇)은 맨 윗부분을 제외하고는 땅 속에 묻혀있어 정확한 모습을 알 수 없다. 탑신(塔身)은 1층 몸돌만 한돌로 되어 있고, 1층 지붕돌과 2층 몸돌, 2층 지붕돌과 3층 몸돌, 3층 지붕돌과 꼭대기의 네모난 머리장식 받침돌이 합쳐져 각각 한돌을 이룬다. 탑신의 몸돌에는 기둥 모양이 새겼다.","a":"월송리삼층석탑","c":"문화유산자료","nc":"","r":"강원특별자치도","s":"춘천시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660323.jpg"},{"q":"○○○○○은 머리 부분이 몸에 비해 큰 편으로 높은 육계가 있고, 나발의 표현이 희미하다. 얼굴은 거의 마멸되어 윤곽만 보이고 법의는 통견으로 가슴 앞이 U형으로 길게 벌어졌으며, 옷주름은 측면에서만 조금 확인된다. 수인은 오른손은 아래로 내리고 왼손은 배에 대어 약합(藥盒)을 들고 있어서 약사상의 특징을 보인다. 전체적으로 상의 파손과 마모가 심하며 또한 세부적인 표현도 거칠어서 민간에서 조성된 불상의 형태를 보인다.","a":"충주 봉불사 석조약사여래입상","c":"문화유산자료","nc":"","r":"충청북도","s":"충주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660876.jpg"},{"q":"향로란 절에서 마음의 때를 씻어준다는 의미를 가진 향을 피우는데 사용한 도구이다. 높이 20.2㎝, 입 지름 19.5㎝인 이 향로는 나팔모양의 높은 받침대를 가지고 있다. 입부분은 넓은 테가 있고, 테에는 8개의 구름무늬를 새겼다. 몸통 가운데에는 4곳에 원을 만들고, 그 안에 범자를 써 넣었으며, 나머지 공간에는 덩굴무늬로 채웠다. 몸통 맨 아래에는 굵은 선으로 연꽃잎을 새겼다. 나팔모양의 받침대에는 윗부분에 구름과 엎어놓은 연꽃잎을 두었고, 아래에는 덩굴무늬를 새겼다.","a":"마곡사동제은입사향로","c":"시도유형문화유산","nc":"","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639029.jpg"},{"q":"○○○ 대웅전 왼편에 서 있는 석탑으로, 2층 기단(基壇)에 3층 탑신(塔身)을 올리고 정상에 머리장식을 얹은 형태이며, 석재가 많이 닳아 있다. 기단은 윗돌 일부가 파손되었고, 기단과 탑신의 몸돌에는 기둥모양이 새겨 있다. 지붕돌은 밑면의 받침이 4단씩이고, 3층 지붕돌 위에는 노반(露盤:머리장식받침), 복발(覆鉢:엎어놓은 그릇모양의 장식), 앙화(仰花:솟은 연꽃모양의 장식), 보주(寶珠:꽃봉오리모양의 장식) 등의 머리장식이 남아있다.","a":"진주 청곡사 삼층석탑","c":"시도유형문화유산","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641336.jpg"},{"q":"○○○는 청동기시대의 대표적인 무덤으로 고인돌이라고도 부르며, 주로 경제력이 있거나 정치권력을 가진 지배층의 무덤으로 알려져 있다. 우리나라의 고인돌은 4개의 받침돌을 세워서 돌방을 만들고 그 위에 거대하고 평평한 덮개돌을 올려놓은 탁자식과, 땅 속에 돌방을 만들고 작은 받침돌을 세운 뒤 뚜껑돌을 덮고 그 위에 거대한 덮개돌을 올린 바둑판식으로 구분된다. 원래 제주시 용담동 751번지에 있었는데 공항부지 확장공사 때 공항 앞으로 옮겨 복원하였다. 형태는 바둑판식이나 덮개돌 밑에 여러 매의 넓고 납작한 돌을 병풍모양으로 둘러 돌방을 만들어서 개석식으로 재분류된다.","a":"용담지석묘4호","c":"시도기념물","nc":"","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657655.jpg"},{"q":"조선시대 문인인 태소 ○○○ 선생이 ○○하고 있던 책이다. 『성좌도』와『중성기』는 비록 ○○○이 제작한 것은 아니지만 조선시대의 조상들이 ○○○을 어떻게 이해하고 있었는지를 살피는 중요한 자료가 되고 있다.『태소유집』은 선생이 앞서 두 책을 바탕으로 실제 천문을 관측한 결과를 밝혀놓은 부분이 있어 중요한 자료가 되고 있다.","a":"의령 남극인 소장 천문학 관련 문헌자료","c":"문화유산자료","nc":"","r":"경상남도","s":"의령군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664452.jpg"},{"q":"○○○○○은 울주군 ○○○에 있는 경부고속도로 서울산 나들목의 서쪽 구릉 일대에 자리잡고 있다. 본 유적이 입지하는 구릉은 경부고속철도 역사가 있는 곳까지 이어져있으며, 구릉 전체에 청동기시대부터 조선시대의 유구가 분포한다. 이곳은 울산지역에서 가장 규모가 큰 청동기시대~삼한시대 취락유적이며, 청동기시대 취락연구에 중요한 유적으로 평가받고 있다. 발굴조사에서는 청동기시대 집자리, 삼한시대 환호, 조선시대 무덤 등이 확인되었다. 울산지역의 청동기시대 집자리는 긴 네모꼴, 네모꼴의 형태가 있으며, 긴 네모꼴은 청동기시대의 이른 시기, 네모꼴은 늦은 시기에 해당된다.","a":"울주교동리생활유적","c":"시도기념물","nc":"","r":"울산광역시","s":"울주군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645931.jpg"},{"q":"조선중기에 송준길, 송시열, 윤선거, 유계와 함께 소위 충청도 산림오현(山林五賢)으로 손꼽혔으며, 호서예학(湖西禮學)의 큰 맥을 이은 巨儒이자 經濟思想家인 초려 ○○○ 선생이 말년을 보낸 곳으로, 선생의 사상과 정신을 계승·교육하는 전통서원의 면모를 유지하여 오고 있으며 고택과 용문서원이 자리하고 있다. 용문서원의 유래는 ○○○선생이 저술하고 제자를 가르쳤던 중동서재와 용문서재에서 비롯되었는데 중동서재는 선생이 거주하던 집이 있던 것이고, 용문서재는 현재 용문서원과 종가가 있는 자리에 있던 것으로 문하생들이 거주하면서 공부했던 곳이었다.","a":"공주이유태유허지","c":"문화유산자료","nc":"","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661569.jpg"},{"q":"백암사의 연혁에 대한 기록은 남아 있지 않다. 그러나 옛 보원사에는 99개소의 암자가 있었고 100번째 암자인 백암사를 지은 후 모든 암자가 불에 타서 없어졌다는 이야기가 전해지는 것으로 보아 보원사는 가장 융성하던 시기인 고려 전기에 세웠다가 소멸된 것으로 짐작한다. 현재 이곳에는 약 2000여 평의 절터와 세울 당시 쌓은 것으로 보이는 석축이 부분적으로 남아 있다. 또한 석등과 석탑의 일부분이 남아 있는데 그 제작 기법과 모양을 보아 고려시대에 제작된 것으로 추정한다.","a":"백암사지","c":"문화유산자료","nc":"","r":"충청남도","s":"서산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661260.jpg"},{"q":"화면 중앙에 지장보살이 연화좌 위에 결가부좌하고, 대좌 앞쪽에는 선악동자가 금색 원광을 배경으로 피어오른 연꽃을 밟고 서 있다. 그 좌우에는 도명존자와 무독귀왕이 시립하고, 옆쪽과 후열에는 시왕이 좌우 5위씩 배치되어 있다. 시왕의 뒤쪽에는 판관·사자·옥졸·시녀 등 제권속이 좌우대칭으로 2열을 이뤄 배치되어 있다. 본존인 지장보살은 신체는 머리가 크고 어깨가 넓은 편이나, 무릎너비가 좁은 편이다. 오른손을 가슴 위로 치켜 올렸고, 투명 보주를 든 왼손은 배 앞에 위치하고 있다.","a":"복천사 지장시왕도","c":"시도유형문화유산","nc":"","r":"부산광역시","s":"영도구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2020030609215500.png"},{"q":"○○○○은 영양남시(英陽南氏) 집성촌 및 고가옥 밀집지역으로 널리 알려진 괴시(槐市, 濠池)마을내에 있으며 1871에 현 소유자의 5대조인 남공수(南公壽, 號.瀛隱, 1793~1875)가 건립하였다 한다. 건물은 정면4칸, 측면4칸반 규모의 口자형 홑처마 팔작지붕으로 정면 대문칸을 중심으로 우측엔 사랑방, 좌측에는 광과 방이 연결되고, 사랑방과 연결된 우익사는 2칸의 방으로 되어 있는데 감실을 두었다. 좌익사는 부엌과 안방으로 이어져 있고, 내부2칸 대청마루를 중심으로 좌측은 도장과 안방을, 우측에는 상방과 상방전면에 통마루를 두었다.","a":"영덕괴시리영은고택","c":"문화유산자료","nc":"","r":"경상북도","s":"영덕군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2018101609355600.JPG"},{"q":"○○○○○은 당초 1890년에 코프(한국명 고요한) 신부에 의해 지어졌으나 한국전쟁 때 소실되었고 현재의 건물은 1956년에 중건된 것이다. 중건 당시 기초를 철근 대신 ‘H’형강을 사용하였다. 건물 형태는 지붕의 목조트러스를 제외하고, 외벽과 주요부재는 화강암으로 견고하게 쌓아올린 중세풍의 석조이나 한국의 전통적인 목구조 처마양식을 가미하였으며 창호 및 벽체 부분의 처리가 뛰어나다.","a":"인천 내동 성공회 성당","c":"시도유형문화유산","nc":"","r":"인천광역시","s":"제물포구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637121.jpg"},{"q":"○○○는 백제 무왕 33년(632)에 여환이 처음 지은 후 여러 차례의 공사와 명칭의 변경이 있었던 사찰이다. 지금의 ○○○라는 이름을 갖게 된 것은 조선 선조 7년(1574) 환양이 다시 지은 이후부터이다. 환양이 ○○○에 있으면서 매일 『법화경』을 읽을 때 흰 양이 경을 읽는 소리를 듣고 몰려오는 일이 많아지자 절 이름을 ○○○라고 고쳤다고 한다. ○○○은 1917년 절이 다시 지어질 때 같이 세운 것으로, 안에는 석가여래삼존불상과 10척 높이의 불상, 용두관음탱화를 모시고 있다.","a":"장성 백양사 대웅전","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"장성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639871.jpg"},{"q":"○○○○○에 있는 이 ○○○는 비단 바탕에 채색하여 그렸으며, 크기는 가로 83.5㎝, 세로 107.9㎝이다. 현재 판넬 형식으로 보존되어 있는데, 전체적으로 화면의 테두리 외곽은 오염되었고 채색이 바래져 있다. 이 그림의 뒤쪽 상단에는 그림을 걸기 위한 2개의 고리가 있다. 화면은 중앙의 현왕을 중심으로 각각 6명의 인물을 좌우에 배치하고 있다. 현왕은 비교적 자유로운 자세로 의자에 앉아 있고 권속들은 현왕을 향하여 서 있는 형태이다. 색깔은 주색·자색·녹청색·군청색·백색 등이 많이 쓰였고 부분적으로 금칠이 되어 있다.","a":"통영 용화사 현왕도","c":"문화유산자료","nc":"","r":"경상남도","s":"통영시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664727.gif"},{"q":"조선 세종 때 문신인 ○○○ 김삼근(1419∼1465)의 옛집이다. 이 집은 그의 둘째 아들 계행(1430~1517)이 태어난 뒤에 이곳으로 옮겨와 살았으므로 이 무렵에 지은 것으로 보인다. 이 집에서 태어난 김삼근의 장손인 학조(學祖)는 연산군 때 고승으로 대장경을 간행하는 등 불교를 일으키고 문화 발전에 공헌하였다. 김삼근의 차손인 영전도 이 집에서 태어났으며 성종 때에 공신 녹권을 하사받고 합천부사, 사헌부 감찰 등의 벼슬을 하였다. 이 건물에는 ‘돈소당(敦素堂)’이라는 현판이 걸려 있는데, 영전의 9대손 언행의 호를 따라 부르던 집 이름이다.","a":"안동 비안공 구택","c":"시도민속문화유산","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658919.jpg"},{"q":"요지는 자기나 기와, 그릇들을 만들어 굽던 가마터를 말한다. 광음리 야산의 남쪽 기슭에 있으며 조선 전기 분청인화문 상감사기를 굽던 곳이다. 선조 41년(1608)에 편찬된 경상도 안동부 읍지인 『영가지(永嘉誌)』에는 광음 흙항아리의 생산지가 안동관아에서 25리 떨어진 곳에 있으며 ‘그릇은 화려하고 색은 붉다’고 기록되어 있다. 가마터에는 당시 사용했던 백토원료가 남아있으며, 버려진 사기조각은 조그마한 언덕을 이루고 있다. ○○○○○ 가마터는 우리나라 도자사 연구에 중요한 자료가 되는 곳이다.","a":"안동광음동분청사기요지","c":"시도기념물","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654434.jpg"},{"q":"\"고운(孤雲) 최치원(崔致遠,857~)의 신주를 모신 지산사(芝山祠)의 강당이다. 1737년(영조13)에 영당(影堂)을 세워 영정(影幀)을 모시다가 1846년(헌종12)에 지산사를 세웠다. 1886년 대원군의 서원철폐 때 헐려 없어졌던 것을 1922년에 다시 세웠다. 처음에는 최치원을 중심으로 최운한(崔雲漢,1444년~1499), 최형한(崔亨漢,1446~1504), 정오도(鄭吾道,1641~1732)네 분을 모셨으나, 고쳐 세우면서 최치원만을 모시게 되었다. 경내에는 강당인 ○○○와 내외삼문ㆍ영당이 있는데, 그 중 ○○○가 국가유산으로 지정되어 있다.","a":"지산재","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"남구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637146.jpg"},{"q":"경상북도 영양군 입암면 연당리 마을 한가운데 임시로 지어놓은 건물 안에 모셔져 있는 ○○○○이다. 광배(光背)와 대좌(臺座)를 모두 갖추고 있는 불상으로, 머리와 눈부분이 깨져 있고 광배가 3조각으로 절단되어 있기는 하지만 거의 완전한 상태로 보존되어 있다. 얼굴은 직사각형 형태이고, 사각형의 신체와 반듯한 어깨, 좁아진 무릎 등에서 경직된 모습을 보이고 있다. 왼손에 약그릇을 들고 있어 이 불상이 모든 중생의 질병을 고쳐준다는 약사여래(藥師如來)를 표현한 것임을 알 수 있다. 옷은 양 어깨를 감싸고 있으며, 평행으로 흐르는 물결식의 옷주름이 새겨져 있다.","a":"영양연당동석불좌상","c":"시도유형문화유산","nc":"","r":"경상북도","s":"영양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640451.jpg"},{"q":"○○○ 종루에 매달려 있는 이 ○○은 높이 127.0cm, 종구(鐘口) 지름 92.5cm인 규모가 제법 큰 범종이다. 천판(天板) 정상부에 쌍룡의 용뉴(龍鈕)가 조형되어 있고, 동체 윤곽선이 아래로 가면서 서서히 배가 부른 원만한 곡선미를 보여 주고 있다. 종신(鐘身)에는 유곽(乳廓), 보살상, 전패(殿牌)가 양각되어 있는 등 조선 후기 ○○ 양식을 보여주고 있다.","a":"범어사 동종","c":"시도유형문화유산","nc":"","r":"부산광역시","s":"금정구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636769.jpg"},{"q":"○○○ 팔상전 주존으로 모셔진 이 불상은 호분으로 도색된 상태의 석조○○○○이다. 부분적인 훼손상태는 호분도색으로 후보 하였고 나발, 육계, 승각기의 표현기법과 의습 처리 등 전체적인 균형이 뛰어난 작품","a":"밀양 표충사석조석가여래좌상","c":"시도유형문화유산","nc":"","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1643063.jpg"},{"q":"조선 후기인 1770년대에 제작된 제주도의 옛 지도이다. 제주도의 지도는 초기에는 둥근 감자형이었다가 점차 고구마형으로 바뀌는데, 이 지도는 위에 설명한 두가지 형태와는 전혀 다른 분위기를 풍긴다. 한라산과 그 주변의 오름들을 입체화시켜 한라산의 웅장함을 강조하고 있으며, 한라산 봉우리의 명칭들도 자세히 기록하고 있다. 더욱이 제주가 섬이라는 사실을 알 수 있게 섬의 위치까지 적어 놓고 있다. 제주목, 대정현의 경계를 붉은선으로 표시하였고, 3읍의 연결도로망도 나타내었으며, 목장·과수원·포구 등의 명칭도 모두 적어 놓았다.","a":"제주삼읍도총지도","c":"시도유형문화유산","nc":"","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1643288.jpg"},{"q":"이 책판은 임진왜란 때 승장으로 공을 세운 사명대사의 시와 글들을 모아 편집한 시문집이다. 사명대사가 세상을 떠나자 사명대사의 제자 혜구스님이 일부 간직하고 있던 시와 글을 ○○에 각인한 것이다. 이 책판의 권 1에는 사, 권 2에는 오언율시, 권 3에는 칠언율시, 권 4에는 오언절구, 권 5에는 사명대사가 선에 대해 말한 글귀를 모은 선게, 권 6에는 잡문과 시들이 실려있다. 뒤에는 부록으로 비문과 행적이 붙어있다. 이 책판은 사명대사의 사상연구 및 개인 전기의 귀중한 자료로 평가된다.","a":"밀양 표충사 사명집 목판","c":"시도유형문화유산","nc":"","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642126.jpg"},{"q":"체화당 안에 있는 건물로 창석 이준(1560∼1635) 선생을 모신 사당이다. 이준 선생은 조선 중기 때 문신으로 임진왜란 때에는 그의 형 월간 이전과 함께 의병을 모아 왜적에 대항했다. 채화는 형제를 의미하는 것으로 이들 형제의 우애를 상징하였다고 한다. ○○○○은 원래 효종 7년(1656) 다른 곳에 지었는데 영조 47년(1771) 월간 선생이 만년에 학문을 수행했던 체화당이 있는 이곳으로 이전하였다. 월간 선생을 모신 사당과 같은 구조로 되어 있으며, 양측 끝에 바람을 막아주는 풍판을 설치하였다.","a":"창석사당(178-2)","c":"문화유산자료","nc":"","r":"경상북도","s":"상주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/0000000001662768.jpg"},{"q":"전라남도 광양시 진상면 비평리에 있는 산성으로, 산꼭대기 아랫부분을 빙둘러 쌓아올렸다. 건너편 삼각봉에도 자그마한 산성이 있어 ○○○○과 함께 비촌현을 방어했던 것으로 보인다. 동서쪽으로 길게 뻗은 사다리꼴로, 성벽 전체 둘레는 500m이고, 가장 높은 곳은 334m, 성벽의 너비는 530∼600m이다. 성 안에서 기와와 토기조각 등의 유물이 발견되고 있는데 백제 지역에서 출토되는 유물들과 그 양상이 같아 백제 때 만든 산성으로 보인다. 이 지역의 고대사 외에도 백제의 지방통치 체계를 이해하는데 중요한 자료로 쓰이는 산성이다.","a":"광양불암산성","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"광양시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2020022813303000.JPG"},{"q":"충청남도 논산시 시내에서 약 2㎞ 떨어진 등화동의 구릉형 야산에 있는 산성으로, 계곡을 포함하여 쌓은 토성이다. 산성은 서북쪽으로 가파른 산비탈을 이루고 있으며, 정상에서는 호남평야를 한눈에 내려다 볼 수 있는 군사적 요충지에 자리잡고 있다. 성의 둘레는 840m이고 동·서·남·북에 각각 성문터가 있으며, 성벽은 안쪽 높이 4.5m, 바깥높이 5m, 윗부분의 너비는 1.2m이다. 성안에는 폭이 10m이상 되는 도랑처럼 파서 돌린 내호로 보이는 통로가 동쪽을 제외하고 전체로 돌아가고 있으며, 군량(軍糧)과 군기(軍器)를 저장하던 창고와 여러 건물의 흔적이 남아있다.","a":"논산황화산성","c":"시도기념물","nc":"","r":"충청남도","s":"논산시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1652841.jpg"},{"q":"신니면 선당리 ○○○○에 단독으로 모셔져 있는 이 불상은 소조불(塑造佛) 로서 양손을 일부 보수한 것을 제외하면 보존상태가 양호한 편인데 얼굴에 철분을 칠하였다. 상호는 몸에 비하여 크게 표현하여 비례가 잘 맞지 않는 느낌이다. 얼굴은 네모진 모습이며 통통하게 살이 오르고 머리카락은 나발(螺髮)에 계주(髻珠)를 표현하였다. 이마에는 백호가 표현되었는데 보주는 최근에 삽입하였다고 한다. 몸통은 얼굴에 비하여 작게 표현되었는데 손가락 부분은 보수된 관계로 정확한 수인을 알 수 없으나 왼손은 손바닥을 하늘을 향해 왼쪽 무릎에 붙였으며 오른손은 촉지인을 하고 있는 형상이다.","a":"충주 고불선원 소조여래좌상","c":"문화유산자료","nc":"","r":"충청북도","s":"충주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660858.jpg"},{"q":"이곳은 정묘호란 때 의병장이었던 박언배와 그 부인 이씨의 높은 충절을 기리기 위하여 세운 정려각이다. 박언배는 옥과의 사족으로 박연( 朴堧 )의 후손이다. 조선 인조5년(1627) 청나라 군사가 내습하자 의병장으로 안주( 安州 ) 싸움에 참가하여 전사하였다. 이 소식이 알려지자 부인 이씨도 또한 뒤따라 목숨을 끊었다. ○○○은 순조5년(1805)에 건립한 것이다.","a":"곡성 충렬문","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"곡성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2026011215152094.jpg"},{"q":"○○○○○은 17세기 후반에서 18세기 초반의 잔존 예가 드문 산신도로서 고승 영정 구도와 비슷하면서 호랑이 뒤의 단아한 두 동자의 배치가 돋보인다.","a":"하동 금정사 산신탱","c":"시도유형문화유산","nc":"","r":"경상남도","s":"하동군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1643199.jpg"},{"q":"갈암 이현일(1627∼1704) 선생이 임진왜란 뒤 조선 현종 14년(1673)경에 지은 집이라고 한다. 이현일 선생은 조선 후기 문신이자 성리학자로 학행이 높아 여러 벼슬을 두루 거친 분이다. 지은 책으로는 『갈암집』과 편서로 『홍범연의』가 있다. 이곳은 퇴계 이황 선생의 학통을 이어 받아 이현일 선생이 학문을 익혔던 집으로 그 학행과 정신을 엿볼 수 있는 곳이다.","a":"오촌리갈암고택","c":"문화유산자료","nc":"","r":"경상북도","s":"영덕군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663288.jpg"},{"q":"섬진강 주변 마을의 논 가운데 자리하고 있는 입석(선돌)이다. 입석은 길쭉하고 커다란 돌을 약간만 다듬어 마을입구 등에 세워 기념하거나 신앙의 대상물로 삼았던 것으로, 주로 마을의 경계를 나타내거나, 농사의 풍요를 빌기 위해 세워둔다. 이 입석은 거대한 자연돌을 세워 놓은 것으로, 앞뒷면은 고르지 않고 옆면만 잘 다듬어져 있다. 윗부분의 한쪽끝이 다른쪽보다 높아 뾰족한 경사를 이루었으며 앞면은 섬진강을 향하고 있다. 이 근처에 7기의 고인돌이 분포되어 있어 묘의 영역을 표시하는 기능을 하였을 가능성도 있으나, 삼국시대 당시 국경을 표시하던 표지석이라고도 전한다.","a":"월전리입석","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"구례군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662052.jpg"},{"q":"○○○는 신라 선덕여왕 12년(643) 자장율사가 지었고 흥덕왕 때 진산조사가 다시 지었다. 임진왜란으로 불타버리기 전에는 경기도와 충청도 지방에서 가장 큰 절 중 하나였다고 한다. 중심 법당인 ○○○은 1983년에 완전히 해체하여 복원하였는데 처음보다 크게 세웠다. 지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕이다. 지붕 처마를 받치기 위해 장식하여 만든 공포는 기둥 위와 기둥 사이에도 있는 다포 양식으로 꾸몄다. 건물 안쪽에는 석가여래와 그의 제자인 약사여래, 아미타여래 불상을 모시고 있으며, 불상 뒤쪽에 영조 17년(1741)에 제작된 탱화가 있다.","a":"광덕사 대웅전","c":"문화유산자료","nc":"","r":"충청남도","s":"천안시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661304.jpg"},{"q":"지석묘는 청동기시대의 대표적인 무덤으로 고인돌이라고도 부르며, 주로 경제력이 있거나 정치권력을 가진 지배층의 무덤으로 알려져 있다. 우리나라의 고인돌은 4개의 받침돌을 세워 돌방을 만들고 그 위에 거대하고 평평한 덮개돌을 올려놓은 탁자식과, 땅 속에 돌방을 만들고 작은 받침돌을 세운 뒤 그 위에 덮개돌을 올린 바둑판식으로 구분된다. ○○시 ○○○의 마을 안과 주변 논밭에 모두 15기의 고인돌이 있다. 형태상 모두 바둑판식으로 덮개돌의 크기는 길이 2.2m, 너비 1.4m이며, 받침돌의 크기는 너비 40㎝, 높이 20㎝이다.","a":"사천 덕곡리 지석묘군","c":"시도기념물","nc":"","r":"경상남도","s":"사천시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654976.jpg"},{"q":"현재 ○○○ 대웅전(金仙寺 大雄殿)의 좌측 벽에 봉안되어 있는 이 신중탱화는 1887년(고종 24년) 금어비구 금지(金魚比丘 金地), 출초비구 경순(出草比丘 景純), 편수비구 계준(片手比丘 啓俊) 등에 의해 제작되었다. 이 신중탱화는 세로로 긴 화면에 제석(帝釋)과 위태천(韋駄天)을 각각 상부와 하부의 중심으로 하여 그 주위에 12구(軀)의 권속(眷屬)을 배치한 상하 2단 도상 구조를 취하고 있다. 상부에는 중앙에 제석(帝釋)이 크게 묘사되고 그 주위로 6명의 권속(眷屬)이 제석(帝釋)을 향하여 시립한 모습이 그려져 있다.","a":"금선사 신중도","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2018102317320200.jpg"},{"q":"일산 신도시에 위치한 이 가옥은 과거에 이 지역에 많았던 밤나무를 이용해 집을 건축했다는 의미에서 이름이 지어졌다. 주요 구조재인 기둥, 대들보, 서까래뿐만 아니라 벽선, 창호 등과 같은 수장재도 밤나무를 재료로 하였다. 건립연대는 19세기 전반 이전으로 추정하고 있다. 이 가옥은 가운데 마당을 중심으로 남쪽에 ‘ㄱ’자형 안채와 북쪽의 ‘ㅡ’자형 건물이 담장으로 연결되어 똬리를 틀듯이 초가지붕 아래 놓인 배치를 하고 있다.","a":"일산밤가시초가","c":"시도민속문화유산","nc":"","r":"경기도","s":"고양시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658175.jpg"},{"q":"원래 방단식 이형 탑으로 추정되며 축조에 사용된 돌은 적돌크기보다 작은 장방형의 돌을 한 켜씩 쌓아올렸다. 탑의 앞면 하단부에는 감실이 조성되어 있고 감실 안에는 '富興山神位'라 새겨진 석비가 자리하고 있다.","a":"충주 부흥사 방단적석유구","c":"시도기념물","nc":"","r":"충청북도","s":"충주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1651389.jpg"},{"q":"경북 ○○시 공검면에 있는 저수지로 원삼국시대에 만들어진 것으로 추정되며, ‘제천의 의림지(충청북도 유형문화유산)’, ‘김제 벽골제(사적)’와 더불어 조선시대 3대 저수지로 알려져 있다. 공갈못이라고도 하는데 ‘공갈’이란 아이를 묻고 둑을 쌓았기 때문에 ‘공갈못’이란 이름이 생겼다는 설이 있다. 예부터 ○○○는 연꽃이 풍성하여 꽃이 만발하면 중국의 전당호와 견줄만 하다고 하였고, 이로 인해 ‘공갈못 노래’가 만들어져 전파되기도 하였다.","a":"상주 공검지","c":"시도기념물","nc":"","r":"경상북도","s":"상주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654602.jpg"},{"q":"○○○란 왕이나 고관 등의 평생업적을 비석에 기록하여 그의 묘 남동쪽에 세워두는 것으로, 이 비에는 조선시대 중기의 무신인 ○○○의 공적을 적고 있다. ○○○는 선조 32년(1599) 무과에 급제하여 선전관이 되었으며 곧 감찰에 임명되었다. 광해군 때에는 벼슬에 나아가지 않다가 인조반정 후 통정으로 승진하여 명천부사가 되었다. 이괄의 난 후에는 전라좌수사가 되었고, 이후 여러 관직을 거치다가 인조 13년(1635) 공청병마절도사로 다시 부임하여 이곳에서 병자호란을 맞았다.","a":"이의배신도비","c":"문화유산자료","nc":"","r":"충청남도","s":"예산군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661206.jpg"},{"q":"○○○○○은 법화경이라고도 한다. 천태종의 근본 경전이었으며, 현재는 한국불교의 근본 경전의 하나이다. 삼국시대부터 널리 유통되었으며, 고려시대에는 필사 및 간행이 활발하였고, 조선시대에도 꾸준히 간행되었다. 독송용 경전이라기보다 주로 경전신앙을 따르는 시주자의 공덕을 위해 간행되었다. 총 7권 가운데 권1~2의 영본(零本) 1책이고, 간기(刊記)가 없어 분명한 간행연도를 알 수 없다. 그러나 동일판본의 완질이 보물로 지정되어 있고, 서체(書體), 판식(版式), 도각(刀刻) 등으로 보아 임진왜란 이전의 간본(刊本)으로 판단된다고 한다.","a":"구미자비사묘법연화경","c":"문화유산자료","nc":"","r":"경상북도","s":"구미시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663538.jpg"},{"q":"사찰에서 법회法會나 의식意識이 있을 때는 당幢이라는 깃발을 달았다. 당을 매달았던 긴 장대를 ‘당간幢竿’이라고 하며, 당간을 지탱하기 위해 양쪽에 세운 2개의 돌기둥을 ‘○○○○’ 라고 한다． ○○○에는 나란히 2쌍의 ○○○○가 서 있는데, 높이는 동쪽 ○○○○가 3.6m, 서쪽 ○○○○가 3.45m이다. 각 기둥의 안쪽 면에는 쐐기목을 박아 당간을 고정시켰던 홈과 구멍이 뚫려 있으며, 서쪽 ○○○○ 사이에는 당간을 받쳤던 둥근 받침대가 남아 있다.","a":"불국사 당간지주","c":"시도유형문화유산","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2018110419180100.jpg"},{"q":"1926년에 지은 집으로 안채의 천장부재에 건축공사와 참여자의 이름 등을 기록한 상량문이 적혀있다. ㅡ자형의 안채와 사랑채, 행랑채가 ㄷ자형으로 배치되어 있다. 안채는 길게 다듬은 돌을 3단으로 쌓은 받침대 위에 둥근 주춧돌을 놓고 네모 기둥을 세웠다. 건물이 세워진 연대는 오래되지 않았지만, 안채·사랑채·행랑채가 모두 갖추어져 전통 주거건축의 모습을 잘 나타내고 있으며, 세부 기법에서는 전통기법과는 다른 변형된 형태가 나타나고 있어 조선시대의 전통적인 가옥이 일제강점기를 통하여 변화되고 있는 모습을 보여주고 있다.","a":"청주 신전동 고가","c":"시도유형문화유산","nc":"","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638619.jpg"},{"q":"조천봉(朝天峰) 남쪽 산자락에 위치한 ○○○○는 회봉(晦峰) 안규용(安圭容, 1873~1959)이 혹독한 왜정(倭政) 치하에서 많은 후학들에게 유교의 경전과 도학의 의리를 강학한 유서 깊은 서당이다. 회봉은 본관이 죽산(竹山), 자는 경삼(敬三)으로, 은봉(隱峰) 안방준(安邦俊)의 10대손이며 연재(淵齋) 송병선(宋秉璿)의 제자이다. 회봉은 식민지 교육정책이 강화되던 시기에 1860년경 건립된 가옥을 매입하여 수리한 뒤 1921년에 ‘○○○○’라고 명명하였다.","a":"보성 죽곡정사","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"보성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2020121414485900.jpg"},{"q":"원효대사가 무등산 원효사에 머물던 어느 날, 서쪽 하늘에 상서로운 기가 가득함을 보고 제자 보광화상을 그곳에 보냈더니 뜻밖에 큰 바위에서 빛이 솟아 나오므로 그곳에 이 불상을 새겼다고 한다. 자연 암벽을 다듬어 불상을 도드라지게 표현하고 그 위에 건물을 지어 전각(殿閣)을 이루고 있는 일종의 석굴사원 형태이다. 작은 소라 모양의 머리칼을 붙여 놓은 머리에는 상투 모양의 머리묶음이 자리잡고 있다. 넓적한 얼굴은 긴 눈, 우뚝 솟은 코, 두꺼운 입술 등에서 매우 근엄한 인상을 풍긴다.","a":"운천사마애여래좌상","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"서구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637139.jpg"},{"q":"조선 선조는 속리산 ○○○의 부속 암자인 중사자암(中獅子菴)을 즐겨 찾았으며, 암자 남쪽에 원당(願堂)을 짓고 곡식을 하사하였다고 한다. 선조는 여러 사람에게 글씨를 하사했으며 서산대사(西山大師)에게 묵죽(墨竹)과 제찬(題讚)을 친필(親筆)하여 하사한 일도 있다고 한다. ○○○○○은 영조 34년(1758)에 왕이 ‘신법천문도○○’을 하사할 때 ‘주서무일편○○’과 함께 하사한 것으로 전해지나 기록은 찾지 못하였다.","a":"보은 법주사 선조대왕 어필 병풍","c":"시도유형문화유산","nc":"","r":"충청북도","s":"보은군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638857.jpg"},{"q":"우재 오익(1591∼1671)이 지은 정자로, 과거 시험을 몇 번 보았지만 실패하고 이곳에서 살았다고 한다. 정확하게 세운 시기는 알 수 없으나, 병자호란이 일어난 뒤인 1640∼1650년경으로 추정한다. 건물은 앞면 3칸·옆면 2칸의 규모로, 자연 암반 위에 만들었다. 가운데에 마루를 두고 양쪽으로 방을 놓았으며, 둘레에 난간을 설치하여 연못을 내려다 볼 수 있도록 하였다. 방의 바닥은 파손되어 흙바닥이 노출되어 있다.","a":"청계정","c":"문화유산자료","nc":"","r":"경상북도","s":"영양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662742.jpg"},{"q":"이 가옥은 풍광이 수려한 인동장씨 집성촌인 ○○○ 마을의 동쪽 전면에 위치하고 있다. 마을을 감아 흐르는 내성천을 동쪽으로 바라보고 있는 입지가 매우 훌륭하며, 민간 가옥으로는 큰 규모에 해당한다. 정면 7칸 측면 4칸의 囗자형으로 조선 후기 경북 북부지방의 양반 가옥의 전형적인 형태로 보인다. 이 가옥의 창건이나 중창, 보수 등을 파악할 수 있는 현판이나 기문, 상량문 등의 방증 자료는 전혀 남아있지 않다. 다만 현 소유주 장재원의 9대조이자 입향조 장여화의 5세손인 장태안(?~1722)이 건립했다고 구전되고 있을 뿐이다.","a":"영주 금광리 의관댁","c":"문화유산자료","nc":"","r":"경상북도","s":"영주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2020030409322200.jpg"},{"q":"임란 후에 간행된 경전 7책중 하나로, 십지경론(하) 난승지 제5권 7~ 법운지 제10권 12, ○○○, 대방광불화엄경소초 권34, 경덕전등록 권22~24, 대방광원각수다라요의경 권6, 묘법연화경 권1,2 이다. 각수를 적어놓은 형태나 어미 모양 등 지방 사찰에서 간행된 목판본의 형태와 판본류를 확인해 볼 수 있으며 조선후기 각 지방의 경전 간행의 경향을 알 수 있는 중요한 자료로 인정됨","a":"간 집 록","c":"시도유형문화유산","nc":"","r":"경상남도","s":"김해시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/0000000001643184.JPG"},{"q":"조선시대의 문신인 ○○ 변종락 선생을 그린 초상화이다. 선생의 회갑 때 어느 승려가 그린것이라고 전하는데, 조선시대 사대부를 그린 일반적인 초상화 양식과는 거리가 있어 풍속화적인 인물화인 듯 하다. 즉, 사대부의 엄숙함과 유학자의 분위기가 감도는 분위기를 그려내고자 하기보다는 오히려 선생에 대해 전해오는 일화들을 형상화하고 있다.","a":"장성 기옹 영정","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"장성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639910.jpg"},{"q":"원래 ○○○에는 ○○○○좌상, 문수보살, 보현보살, 관음보살, 지장보살상 등 5존상(五尊像)이 있었으나, 1970년대 초에 관음, 지장, 문수보살상을 도난당해 지금은 ○○○○좌상, 보현보살상과 문수보살상의 대좌였던 사자좌만 남아있다. ○○○○좌상과 보현○○○○의 바닥에는 새겨진 명문을 통해서 이 상들이 1922년에 완호비구에 의해 조성되었다는 것을 알 수 있다. 완호스님은 1921년 ○○○의 주지로 부임하여 전각을 건립하고 그 안에 봉안될 불상과 불화를 조성하였던 것으로 알려져 있다.","a":"복천사석조석가여래및보살좌상","c":"문화유산자료","nc":"","r":"부산광역시","s":"영도구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659407.jpg"},{"q":"운흥사는 신라 진평왕(재위 579∼632)시기, 원효대사가 창건하였다고 전한다. 이후 고려 말 지공대사가 중건하였으나, 임진왜란 때 소실되었고, 1614년(광해군 6)에 대희선사가 재건하였다. 『조선왕조실록』,『신증동국여지승람』등에 운흥사에 관한 기록이 남아있다. 그러나 1749년(영조 25)『학성지』의 기록에 의하면 이미 폐사되고 없었으므로, 그 이전에 폐사되었을 것으로 추정된다. 조선시대 운흥사는 불교 경판의 간행으로 유명하였는데 1672년부터 1709년까지 많은 불경 간행이 이루어졌다.","a":"운흥사지","c":"시도기념물","nc":"","r":"울산광역시","s":"울주군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645924.jpg"},{"q":"칠갑산의 남향한 언덕 계곡 쪽으로 있는 ○○○ 터이다. 『동국여지승람』에 의하면 ○○○는 고려시대의 사찰이었던 것으로 짐작되며, 주변에서 발견되는 기와조각으로 보아 조선시대까지는 맥을 이어왔던 것으로 추정된다. 절터 내에는 ○○○○삼층석탑(충청남도 유형문화유산)과 석불입상 1구가 상반신이 파손된채 남아있는데, 고려시대에 조성된 것으로 보여진다. 1973년 해체 수리시에 발견된 기와와 사리구는 국립부여박물관에 보관되어 있다.","a":"청양도림사지","c":"시도기념물","nc":"","r":"충청남도","s":"청양군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1652859.jpg"},{"q":"부도1·2·3은 석종형으로, 胴體 1장과 대석 1장 총 2장의 돌로 구성되어 있다. 동체는 아래로 갈수록 좁아지는 종 모양이다. 부도1의 지상에 노출된 기단석은 팔각형이나, 각 변의 길이는 일정하지 않다. 동체를 얹은 대석 둘레에는 복련 단판연화문이 둘러져 있으나 다소 마모가 심한 상태이다. 부도3(洗淡堂一行大師)은 종신의 상단과 하단에 연화문이 돋을새김으로 뚜렷하게 처리되어 있으며, 상륜은 꽃잎이 살짝 벌어진 연꽃봉 오리 모양을 하고 있다. 부도4는 총 9기의 부도중 제일 작은 규모로, 기단석 1장, 胴體 1장, 옥개석 1장 총 3장의 돌로 구성되어 있다.","a":"남해 용문사 승탑군","c":"시도유형문화유산","nc":"","r":"경상남도","s":"남해군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642567.jpg"},{"q":"조선 중기 학자였던 동래 정씨 3형제 정사수(1601∼1647)·정시웅·정시승의 학덕을 기리는 건물이다. ○○○은 앞면 4칸·옆면 2칸 규모이며, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양을 한 팔작지붕이다. 앞쪽에는 2층 누각인 화수정이 있다. 지금 있는 건물은 합천댐 건설로 수몰 예정 지역에 있던 것을 1987년 옮겨 지은 것이다.","a":"거창 삼우당","c":"문화유산자료","nc":"","r":"경상남도","s":"거창군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664206.jpg"},{"q":"전북특별자치도 무주군 안성면 공정리에 위치한 이 묘소는 일제와 싸우다 숨을 거둔 의병장 신명선과 그의 부하들이 묻힌 곳이다. 1907년 일본의 강압으로 정미7조약이 체결되어 우리의 군대가 해산당하게 되자 일본의 침략에 울분을 참지 못한 시위보병(侍衛步兵)을 중심으로 전국적인 항일항쟁이 벌어졌다. 시위대 출신 장교 신명선은 전북특별자치도 무주의 덕유산을 거점으로 150여명의 의병을 모집하여 무주·진안·장수 등지에서 일본군과 싸우면서 많은 업적을 세웠다.","a":"칠연의총","c":"시도기념물","nc":"","r":"전북특별자치도","s":"무주군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2020051113545600.jpg"},{"q":"○○○○○에 모셔진 ○○○○○으로, 조선 광해군 5년(1613)과 그 이듬해에 걸쳐 만들어 졌다. 나무로 만든 이 불상은 전체높이 110m, 머리 35㎝, 어깨폭 48㎝, 무릎폭 77㎝ 정도의 매우 큰 규모로 전체적으로 안정감 있고 중후한 느낌이다. 머리는 작은 소라모양의 머리칼을 붙여 놓았으며, 둥근 육계가 있어 원만한 느낌을 준다. 비교적 갸름한 얼굴에 이목구비는 다소 안쪽으로 몰린 듯한 모습이다. 활형의 눈썹은 점점 좁아지면서 코로 이어져 오똑한 콧날을 만들고 있다.","a":"숭림사보광전목조석가여래좌상","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"익산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639682.jpg"},{"q":"○○○ 척지마을 남계천 옆의 낮은 구릉지대에 분포한 가야시대의 무덤들이다. 발견된 무덤의 수는 무덤 5기와 그 주변에 있는 작은 구덩식돌덧널무덤(수혈식석곽묘) 21기이다. 고분은 둥근 봉분이 남아 있고 묘제는 네모꼴이다. 옆벽은 모두 냇돌로 쌓았고 주실의 동쪽이나 서쪽에 반드시 구덩식돌덧널로 된 부곽을 나란히 배치하여 주실과 부곽이 조화를 이루고 있는 다곽묘이다. 고분 주위에 퍼져 있는 작은 구덩식돌덧널무덤은 크게 파괴되어 완전하게 모습이 남아 있는 예는 하나도 없으며 역시 냇돌로 쌓은 일반적인 형태이다.","a":"함양백천리고분군","c":"시도기념물","nc":"","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1656077.jpg"},{"q":"삼한 및 삼국시대에 형성된 대규모 ○○○이다. 1991년과 1993년의 발굴조사 결과, 돌덧널무덤[石槨墓], 덧널무덤[土壙木槨墓], 돌무지덧널무덤[積石木槨墳], 구덩식돌방무덤[竪穴式石室墳], 굴식돌방무덤[橫穴式石室墳] 등 다양한 형태의 무덤이 확인되었다. 유물로는 여러 종류의 토기, 둥근머리큰칼[環頭大刀] 등의 무기, 철판 갑옷[板甲]을 비롯한 여러 가지 무장류[武裝類]가 다량 출토되었다.","a":"중산동고분군","c":"시도기념물","nc":"","r":"울산광역시","s":"북구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645872.jpg"},{"q":"경상남도 ○○군 적중면 ○○○에 있는 삼존석불로 중앙에 본존불인 비로자나불좌상이 있고 그 좌우에 입상불 2구가 배치되어 있다. 비로자나불좌상은 높이 160㎝, 너비 70㎝이며, 손은 가슴 앞에서 왼손이 오른손 검지를 감싸고 있는 모습을 하고 있다. 옷은 마멸이 심해 구분하기 어려우나 왼쪽 어깨에만 걸친 형태이며, 발은 몸에 비해 작게 표현하였다. 양 옆의 입불상은 높이 120㎝, 너비 40㎝이며, 마멸이 심해 판단할 수 없으나 조각수법이 특이하다.","a":"합천 죽고리 석조비로자나삼존상","c":"시도유형문화유산","nc":"","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642281.jpg"},{"q":"연화지 가운데 있는 정자로 주변 경관이 아름다워서 옛 선비들이 시를 읊고 학문을 토론했던 장소이다. 처음에는 삼락동 마을에 세워 흡취헌이라고 부르다가 군수 윤택이 봉황이 나는 꿈을 꾸고 좋은 징조라 해서 봉황루로 이름을 고쳤다고 한다. 영조 47년(1771)에 고쳐 세우면서 ‘○○○’라고 이름을 고쳤다. 그 뒤 정조 16년(1792)에 고쳤으며，헌종 4년(1838)에는 군수 이능연이 연화지 못 가운데로 옮겨 세웠다. 또한 고종 33년(1896)에 다시 고쳤고 1978년에 김천시에서 고쳤다.","a":"봉황대","c":"문화유산자료","nc":"","r":"경상북도","s":"김천시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662370.jpg"},{"q":"임진왜란 때 승장인 사명대사가 충성을 다해 난리를 이겨나가는 활동사항을 모아둔 전쟁활약 실기이다. 대사의 5대 법손인 남붕의 주선으로 영조 14년(1738) 신유한이 편집하여 이듬해 ○○○에서 간행하였다. 이 책의 내용에는 전쟁의 정황을 기록한 탐정기(探情記)와, 일본에 가서 일본관료들과 나눈 문서 등 그 활약상에 대한 후대인의 평들이 담겨있다. 이 책판은 임진왜란 연구 및 사명대사 개인사 연구를 보완해주는 귀중한 자료로 평가된다.","a":"밀양 표충사 송운대사 분충서 난록 목판","c":"시도유형문화유산","nc":"","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642121.jpg"},{"q":"이 ○○책판들은 경남 ○○군의 ○○○에 소장된 것으로, 모두 33종 1743판이다. ○○○에는 해인사 다음으로 많은 경판들이 소장되어 있다. 이 ○○들은 육조 현능대사의 가르침을 받은 제자들이 기록하여 만든 것으로 국내 유일본이며, 정확한 간행연도는 알 수 없지만 선조 36년(1603) 경에 간행된 것으로 추정된다. ○○○의 말사인 능인암에서 간행하여 ○○○로 옮겨온 것이 주류를 이루고 있으며, ○○○ 본사에서 간행한 것과 승려문집도 있다.","a":"하동 쌍계사 불경 목판","c":"시도유형문화유산","nc":"","r":"경상남도","s":"하동군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641797.jpg"},{"q":"○○○는 통일신라 흥덕왕 7년(832)에 무량국사가 세운 절로 ○○○은 1979년에 새로 지은 건물이다. 앞면 3칸·옆면 2칸 규모이며, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕이다. 안쪽에는 수기삼존불좌상을 모시고 있으며, 지장탱화·신중탱화 등도 함께 모시고 있다.","a":"함안 장춘사 대웅전","c":"문화유산자료","nc":"","r":"경상남도","s":"함안군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663813.jpg"},{"q":"우리나라에서 가장 오래된 구석기 문화 유적으로 전기구석기부터 청동기시대에 이르는 거의 모든 시기의 유물층이 발견되어 각 문화층의 성격을 찾아볼 수 있다. 1980년 충주댐 건설로 인한 수몰지역에 실시된 문화유적 지표조사에서 구석기시대의 동굴유적임이 확인되었다. 이후 3차례에 걸친 발굴조사 결과 구석기시대부터 청동기시대까지 여러 시기에 걸쳐 문화가 형성되었음이 밝혀졌으며, 출토된 유물을 통해 구석기시대 문화가 중심을 이루고 있음을 알 수 있다. 동굴의 규모는 입구 높이 8m, 넓이 7∼10m이며 확인된 동굴의 길이 85m이다.","a":"단양 금굴 유적","c":"시도기념물","nc":"","r":"충청북도","s":"단양군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1650417.jpg"},{"q":"○○○○란 이름은 꽃이 필 때 나무 전체가 하얀꽃으로 뒤덥여 이밥, 즉 쌀밥과 같다고 하여 붙여진 것이라고 하며, 여름이 시작될 때인 입하에 꽃이 피기 때문에 ‘입하목(立夏木)’이라 부르기 시작하여 입하목에서 입하나무를 거쳐 오늘의 ○○○○가 되었다고 한다. 함평 ○○○○○는 두 그루가 지정되어 있는데, 한 그루는 높이가 14m, 둘레는 3.04m이며, 다른 하나는 높이 12m, 둘레 1.43m로 차이가 크다. 크기로 보아 큰 것은 나이가 200여 년 정도로 추정되며, 작은 것은 100년 정도 될 듯하다. 즉 100년 정도의 간격을 두고 심은 것으로 추측된다.","a":"함평양재리의이팝나무","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"함평군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654278.jpg"},{"q":"이 집의 안채는 조선시대 후기 건물로 부용면 ○○○ 김종철(金鍾喆)씨가 살던 ○○를 이전 복원한 것으로 ‘ㄱ’자집 형태의 목조기와집이다. 광채는 지붕을 얇은 판석으로 덮은 돌기와집(석와가(石瓦家))형태로 중부지방의 산골부락에 많이 있었던 형태이다. 가옥의 구조는 안채가 ‘ㄱ’자형태의 목조와가이고 광채는 ‘一’자 돌기와집이다. 1995년 문의문화유산단지가 조성되면서 현위치로 이전 복원하였다. 1982년 전국 취락 및 전통가옥(민가)조사 기록대장에 의하면 1950년대까지 거주하였던 송동촌씨의 3대 선친이 건축했다고 전해지나 정확한 건립년대는 확인할 수 없다.","a":"청주 부강리 고가","c":"시도유형문화유산","nc":"","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638794.jpg"},{"q":"경상북도 문경시 문경읍의 관음사터라고 전해지는 곳에 있는 높이 3.33m의 거대한 돌로 만든 약사여래상이다. 전설이 의하면 충청북도 중원군 상모면 미륵리에 박씨 성을 가진 사람이 아내와 남매를 거느리고 살았다고 한다. 그런데 박씨가 큰 병에 걸려 아들이 문경읍으로 약을 사러 갔으나 기다려도 집에 돌아오지 않았다. 아내가 아들을 마중 나갔으나 아내마저 돌아오지 않게 되자 딸이 다시 마중을 나갔는데 역시 돌아오지 않았다. 아내와 아들, 딸이 모두 죽자 이를 가엽게 여긴 부처님이 박씨의 꿈에 나타나 병을 고쳐주었다.","a":"문경관음리석불입상","c":"문화유산자료","nc":"","r":"경상북도","s":"문경시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662662.jpg"},{"q":"○○○는 통일신라 헌강왕 1년(875) 무염선사가 세웠고 고려 문종 19년(1065) 대각국사 의천이 고쳐 세웠다고 전한다. 그 뒤 조선시대에 여러 차례 건물을 새로 짓고 수리하여 지금에 이르고 있다. ○○○은 ○○○의 중심 법당으로 조선 후기에 지은 건물로 추정하고 있다. 앞면 3칸·옆면 2칸 규모로, 지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕이다. 지붕 처마를 받치면서 장식을 겸하도록 만든 공포가 기둥 위와 기둥 사이에도 있다. 이를 다포양식이라 하는데, 맞배지붕 형식의 집에 다포 양식으로 꾸민 것은 보기 드문 예로 주목할 만하다.","a":"천황사대웅전","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"진안군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639385.jpg"},{"q":"○○○은 1588년에 이조판서를 지낸 백암 김륵이 만년을 보내기 위해 지은 정자이다. 건립 후 퇴락하여 무너진 것을 알 수 없는 시기에 이건하였으나 또 다시 붕괴되어 1762년에 지금의 자리로 옮겨 중건하고 그 앞에 연못을 조성했다. 김륵이 영천(현재 ○○시)의 서에는 귀학정·서벽정, 동에는 ○○○의 세 정자를 지었는데, 서벽정은 폐하였고 ○○○은 대대로 구업을 전하였고 정자 앞에 연못이 있어 정자 이름을 얻은 것이라 하였다고 한다. 한편 귀학정은 1988년 봉화읍 문단리로 이건했다.","a":"영주 천운정","c":"문화유산자료","nc":"","r":"경상북도","s":"영주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2018101510254100.jpg"},{"q":"남사마을에서 가장 오래된 집으로 1700년대 건축이다. 남북으로 긴 대지에 안채와 사랑채, 외양간채와 곳간채가 안채를 중심으로 ㅁ자형으로 배치되어 있다. 집터의 서남방에 자리잡은 대문간을 들어서면 바로 사랑마당이고, 이 마당 북쪽으로 앞면 4칸·옆면 2칸 반의 크기를 가진 사랑채가 동남향으로 자리잡고 있다. 사랑채 지붕은 옆에서 보면 여덟 팔(八)자 모양인 팔작지붕으로 꾸몄다. 사랑채 남쪽에 자리잡은 외양간채는 앞면 3칸·옆면 1칸 규모로 외양간과 광으로 구성되어 있다.","a":"산청남사리이씨고가","c":"문화유산자료","nc":"","r":"경상남도","s":"산청군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664098.jpg"},{"q":"청동의 재료로 주조한 고려시대 작품으로 총 높이는 30.2㎝, 구경은 21.8㎝이다. 용뉴와 입상화문대, 상대, 유곽, 당좌, 하대를 갖추고 있다. 용뉴의 용은 종속으로 들어가는 독특한 모습이며 음통은 죽절형(竹節形)으로 끝부분은 화문이 표현되어 있다. 상대에는 연화문이 있고 상대 아래에 4개의 유곽이 있는데 유곽대는 운문이며 그 안에 9개의 유두가 있다. 당좌는 유곽 사이에 모두 4개가 표현되어 있다. 종신의 일부가 깨져나갔고 그 옆으로 균열이 있다. 하대의 당좌 사이에는 점각(點刻)으로 ‘○○○ 상소이암(上蘇利庵)’이라는 명문이 있다.","a":"합천 해인사 동제소종","c":"시도유형문화유산","nc":"","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642402.jpg"},{"q":"○○○에 자리잡고 있는 옛 집으로, 19세기 초반에 지은 것으로 보인다. 선성 김씨들이 대대로 살던 집이지만 구체적인 연혁은 알 수 없다. 안채는 초가 까치구멍집이고 사랑채는 기와집으로 되어 있었는데, 1975년경에 안채의 초가지붕을 기와지붕으로 고쳤다. 까치구멍집은 지붕에 구멍을 내어 집안에서 생기는 연기를 빼내고 빛을 받아들이도록 지은 집이다. 안채는 출입구인 봉당을 중심으로 뒤에 마루를 두고, 왼쪽에는 사랑방, 오른쪽에는 부엌을 배치하였다. 마루 좌우로는 도장방과 안방을 마련하였다.","a":"영주수도리김뢰진가옥","c":"시도민속문화유산","nc":"","r":"경상북도","s":"영주시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658850.jpg"},{"q":"○○○○은 전형적인 삼랑식(三廊式) 성당 건축이며 외관의 전체 구성은 단순하나, 처마돌림 띠, 창둘레 아치 장식 등의 비례가 뛰어난 근대 성당 건축물로서 1933년에 착공하여 1934년에 준공하였다. 한국인 신부에 의해 건립된 건축물로서 원형을 잘 보존하고 있어 보존가치가 매우 높으며, 일본의 건축문화를 수용·혼재하지 않고 서양의 건축문화를 직접 수용하여 토착화한 건축양식으로서 근대건축사 연구의 중요자료이다.","a":"예산성당","c":"시도기념물","nc":"","r":"충청남도","s":"예산군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653161.jpg"},{"q":"대전광역시 동구 용운동에 있는 이 산성은 해발 263m로 산 정상부에 만들었으며, 용운동에서 세천동으로 넘어가는‘갈고개’에 있다. 산 정상을 둘러쌓은 형태로 되어 있으며, 둘레는 약 350m이다. 높이 2m의 동쪽 성벽은 네모난 돌로 앞면을 맞추어 쌓았고, 서쪽 성벽은 자연지형을 이용하여 부분적으로만 쌓았다. 성의 평면형태는 남북으로 긴 타원형의 모습을 하고 있으며, 폭 4.8m의 남문터가 남아 있다. 정상부의 가운데에 움푹 파이고 군데군데 돌로 쌓은 듯한 흔적이 보이고 있는데, 이는 저장시설과 관련된 유적으로 짐작된다.","a":"갈현성","c":"시도기념물","nc":"","r":"대전광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645793.jpg"},{"q":"괘불(掛佛)이란 옥외에서 법회를 할 때 밖에 내어 걸고 의식을 행하는 걸개 그림 형태의 불화를 말한다. ○○○○○은 대웅전 신중도를 그린 당대 최고의 화사 고산당(古山堂) 축연(竺演)이 1919년 제작한 작품으로 세로 6.90m×가로 3.24m의 거대한 화면 중앙에 오른손을 내리고 왼손을 가슴 부근에 댄 ○○○불을 크게 배치하고 그 양 옆으로는 흰 옷을 입은 관음보살과 연꽃 가지를 들고 자비로운 표정을 한 대세지보살, 그리고 아난과 가섭을 좌우 대칭적으로 작게 묘사한 다음 그림 아래쪽으로는 코끼리 타는 보현동자와 사자를 탄 문수동자를 표현했다.","a":"안양암 아미타괘불도","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2590617.jpg"},{"q":"○○○는 함월산 기슭에 있는 절로 신라 선덕여왕 12년(643)에 세웠다. ○○○란 이름은 부처가 생전에 제자들과 함께 활동하던 인도의 기원정사를 뜻한다. ○○○는 이 절의 중심 건물인 대적광전 남쪽에 자리잡고 있다. 지은 시기는 알 수가 없고 다만 조선 영조 16년(1740)에 쓴 사적기에도 기록이 없는 것으로 미루어 그 이후에 세운 것임을 알 수 있다. 지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕이다. 지붕 처마를 받치기 위해 장식하여 만든 공포는 새 날개 모양인 익공 양식으로 꾸몄다. 이 건물은 호국 사찰로 승병 활동과 관련이 있던 것으로 추정한다.","a":"기림사진남루","c":"문화유산자료","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662959.jpg"},{"q":"향교는 공자와 여러 성현께 제사를 지내고 지방민의 교육과 교화를 위해 나라에서 세운 교육기관이다. ○○○○를 처음 지은 정확한 연대는 알 수 없지만，인조 16년(1638)에 이곳 유림들이 지금 있는 자리로 옮겨 세웠다. 그 뒤 8차례 보수를 거쳐 오늘날의 모습을 갖추고 있다. ○○○은 공자를 비롯하여 중국과 우리나라 유학자의 위패를 모시고 제사를 지내는 곳이다.","a":"정읍향교대성전","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"정읍시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661689.jpg"},{"q":"함양 ○○○ 삼성각에 봉안되어 있었던 이 山神幀은 현재 사측에서 별도 보관 중이다. 絹의 틈이 넓은 명주를 바탕재료로 하여 액자 형태로 제작되어 있는 이 탱화의 화면에는 산신이 호랑이 등에 타고 앉아있는 모습을 그려져 있으며, 뒷면에는 朱書된 全身舍利寶篋多羅尼가 있고, 다시 그 아래쪽에는 墨書된 銘文이 附記되어 있다. 그리고 이 ○○○은 조성 당시에 화면을 액자틀에서 조금 비스듬히 구획하였던 것이 후대로 오면서 틀의 뒤틀림과 함께 화면이 향좌측으로 조금 더 비틀어져 있기도 하다.","a":"함양영각사산신탱","c":"문화유산자료","nc":"","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666499.jpg"},{"q":"이 경전은 오욕칠정(五慾七情)에 사로잡혀 온갖 악업을 짓고 그 악업으로 고통 받고 있는 중생이 선지식을 만나 자기가 지은 죄를 참회하고 다시는 악업을 짓지 않으면 죄를 멸하고 무병장수한다는 내용으로, 고려시대부터 꾸준히 간행되면서 일반인에게 상당한 영향을 끼쳐 왔다. 이 책의 뒷부분에 합철되어 있는 『불설대보부모은중경』은 부모의 은혜를 구체적으로 10가지로 나누어 설명하고 있다.","a":"불설장수멸죄호제동자다라니경","c":"시도유형문화유산","nc":"","r":"경기도","s":"고양시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2020031015290200.JPG"},{"q":"○○○은 별내면 청학리 수락산의 미륵봉 서쪽에 위치하고 있으며 별내면 청학리에 있는 봉선사의 말사이다. 이 곳 전각에 봉안한 불화들은 대개 해방 이후에 제작, 봉안된 것이나 괘불만은 19세기 경기·경상도에서 활발하게 활동하던 화사들의 작품으로 19세기 경기지방, 특히 ○○○권 불화의 지역성과 19세기 불화의 양식적인 면을 살필 수 있는 새로운 자료라고 할 수 있으며, 2004년 유형문화유산 197호로 지정되었다. ○○○의 괘불은 1885년에 조성된 것으로, 구도는 대담하고 간략하며 크게 마름모꼴을 이루는 특이한 인물 배치를 보이고 있다.","a":"남양주내원암괘불도","c":"시도유형문화유산","nc":"","r":"경기도","s":"남양주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637762.jpg"},{"q":"향교는 공자와 여러 성현께 제사를 지내고 지방민의 교육과 교화를 위해 나라에서 세운 교육기관이다. ○○○○는 조선 전기에 처음 지었으나, 임진왜란 때 불타 없어진 것을 선조 33년(1600) 제사 공간을 짓고 인조 2년(1624)에 교육 공간을 추가로 지은 것이다. 여러 차례 보수를 거쳐 오늘에 이르는 ○○○○는 앞쪽에 교육 공간을 두고 뒤편에 제사 공간을 두었다. 누문을 지나면 학생들이 모여 공부하는 강당인 명륜당과 학생들의 기숙사인 동재·서재가 있다. 대성전은 공자를 비롯하여 중국과 우리나라 유학자의 위패를 모시고 제사 지내는 곳이다.","a":"구미 선산향교","c":"시도유형문화유산","nc":"","r":"경상북도","s":"구미시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641279.jpg"},{"q":"도갑사 안에 놓여 있는 것으로, 물을 담아두거나 곡물을 씻는데 쓰였던 일종의 돌그릇이다. 길쭉하고 네모난 돌의 안을 파내고, 각 모서리를 둥글게 다듬었는데, 아랫부분을 둥글게 반원모양으로 깎아 놓아 옆에서 보면 작은 통나무배를 보고 있는 듯하다. 안쪽 밑바닥에는 물을 뺄 때 쓰이는 작은 배수구멍이 뚫려 있다. 표면에 기록이 남아 있어 조선 숙종 8년(1682)에 만든 것임을 알게 되었다.","a":"도갑사석조","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"영암군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640043.jpg"},{"q":"원래 함양 박씨 정랑공의 후손 박세주가 조선 효종 원년(1650) 금당골에서 이 마을로 옮기면서 지은 집이다. 지금 있는 자리로는 5대손 미산 박득영이 순조 25년(1825)에 옮겨 세운 것이라고 한다. 건물은 안채와 사랑채가 튼 ㅁ자형 구조를 이루고 있다. 안채는 2칸 대청마루를 중심으로 좌우에 안방·상방·부엌·상방부엌을 배치하였는데 ㄷ자형 평면을 이루고 있다. 사랑채 마루 위의 ‘미산재(味山齋)’라고 쓴 현판은 흥선대원군이 방문했을 때 박득영의 호를 따서 써준 것이라 한다.","a":"미산고택","c":"문화유산자료","nc":"","r":"경상북도","s":"예천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662663.jpg"},{"q":"향교는 공자와 여러 성현께 제사를 지내고 지방민의 교육과 교화를 위해 나라에서 세운 교육기관이다. ○○○○는 조선 숙종(재위1674∼1720) 때 지었다고 하지만 기록은 없고, 고종 9년(1872) 처음 지은 것으로 보는 것이 일반적이다. 지금 남아 있는 건물로는 대성전, 명륜당, 동재·서재, 내삼문 등이다. 대성전은 제사지내는 공간으로 앞면 5칸·옆면 3칸 규모이다. 지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕이다. 지붕 처마를 받치기 위해 장식하여 만든 공포는 새 날개 모양인 익공 양식으로 꾸몄다.","a":"신창향교","c":"시도기념물","nc":"","r":"충청남도","s":"아산시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1652894.jpg"},{"q":"강릉 옥천동에 자리잡은 작은 비각안에 서 있는 비로, 조선 중종 때의 사람인 김덕장의 효행과 덕을 기리고 있다. 김덕장은 부친상을 당하여 3년간 묘곁에 움막을 짓고 살았는데, 그 때 산불이 나서 불이 묘에 까지 닿게 되자 통곡을 하며 하늘을 향해 빌었다. 그러자 갑자기 비바람이 몰아쳐 산불이 꺼지게 되었다. 조정은 그의 이러한 효성을 듣고 정려문을 내려주어 ‘효우당(孝友堂)’이라 이름하도록 하고, 마을 이름을 ‘○○○’라 내리었다.","a":"강릉효자리비","c":"문화유산자료","nc":"","r":"강원특별자치도","s":"강릉시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660422.jpg"},{"q":"○○○○○는 그가 어떻게 청백리가 될 수 있었는지를 알 수 있는 자료이다. 특히 이 유서는 조선시대 중부지역 사족(士族)의 가풍을 보여주며 조선시대 청백리 정신을 이해하는 중요한 자료이다.","a":"이원익유서","c":"시도유형문화유산","nc":"","r":"경기도","s":"광명시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637801.jpg"},{"q":"안채는 정면 4칸, 측면 2칸으로 전·후 퇴를 두었으며 5량 구조에 합각지붕 형식이다. 종도리에 공탄(孔誕) 2376(二三七六)년이라는 기록을 통해 조선 순조 24년(1824)에 건립되었음을 알 수 있으며 약 70여년 전 중수하였다고 한다. 정면 기단을 약 80㎝ 정도의 높이로 조성하고 그 위에 방형으로 조성한 주좌를 놓고 약간의 민흘림을 두어 기둥을 세웠다.","a":"함양 풍천노씨대종가","c":"문화유산자료","nc":"","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1665093.jpg"},{"q":"이 지역에 사는 경주 최씨 문중에서 세운 서당으로 조선 고종 2년(1865)에 세웠다. 원래는 현재의 위치가 아니었으나 1973년 도로공사로 인해 지금 있는 자리로 옮겼다. 서당의 이름을 독암이라 한 것은 서당 서쪽에 고려 태조 왕건이 공산싸움에서 견훤에게 패하자 혼자 피신해 앉아 있었다는 독좌암이 있어 거기에서 따온 것이라 한다. 건물은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕이다. 문중에서 세웠으나 문중 자손들은 물론 인근 지역의 자제들까지 교육하여 이곳에서 유능한 학자를 많이 배출하였다.","a":"독암서당","c":"문화유산자료","nc":"","r":"대구광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659469.jpg"},{"q":"향교는 공자와 여러 성현들께 제사를 지내고, 지방민의 교육과 교화를 위해 나라에서 세운 교육기관이다. ○○○○는 조선 태종 14년(1414)에 처음 지었으며, 임진왜란과 정유재란 때 불타 없어졌다. 그 뒤 여러 건물을 연이어 다시 짓고, 고종 31년(1894) 동재와 서재를 새로 지었다. ○○○은 선조 33년(1600)에 다시 지은 것이다. ○○○의 규모는 앞면 3칸·옆면 2칸이며, 지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕이다. 안쪽에는 공자를 비롯한 그의 제자와 중국의 성현들의 위패를 모시고 있다.","a":"부안향교대성전","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"부안군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661704.jpg"},{"q":"영장산 중턱의 ○○○ 암벽에 새겨진 마애불이다. 벽면에 방형의 감을 파고 그 안에 불상을 꽉 차게 돋을새김 하였다. 같은 벽면에는 14개의 방형 구획을 파고 글을 새겼다. 새겨진 글 가운데 하나에 의하면 광무 1년(1897)에 이규승이 관음상을 새기고 절을 세웠다고 한다. 마애불은 보살상이 아닌 것으로 파악되므로 이규승의 관음상과는 무관한 것으로 보이지만 이를 통해 마애불의 조성시기를 유추해볼 수 있다. 불상은 민머리를 하고 있다. 얼굴은 상당히 높게 돋을새김 하였고 어깨는 넓은 편이다.","a":"망경암마애여래좌상","c":"시도유형문화유산","nc":"","r":"경기도","s":"성남시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637529.jpg"},{"q":"규모가 다소 작고 지대석과 기단부의 면석 및 답신석 등이 결실되어 있으나 남아있는 석탑부재들이 도드락다듬으로 치석되었으며, 운모와 장석이 자연스럽게 마모되어 있는 조성 당시의 것이고 특히 노반 및 복발이 온전하게 잘 남아 있어 고려 말에 조성된 석탑의 좋은 자료이다.","a":"김해 영구암 삼층석탑","c":"문화유산자료","nc":"","r":"경상남도","s":"김해시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666584.jpg"},{"q":"이 터는 신라 문무왕 8년(668)에 명덕(明德) 스님이 세웠다고 하는 남고연국사(南固燕國寺)가 있던 자리이다. ｢연국(燕國)｣은 나라를 편안하게 한다는 뜻으로, 산성 지역에 자리잡은 절에 많이 사용되던 명칭이다. 조선 후기부터는 남고사로 불리었는데, 이 절의 승려들이 ｢남고산성｣을 지키는데 한 몫을 담당했다. 옛 남고사 터는 현재의 남고사 대웅전 서쪽 전방의 건물이 있는 곳이다. 현재 남고사 건물은 약 100여 년 전에 건립된 것으로 추정되며, 1979년에 대웅전 등을 다시 지어 지금의 절 모습을 갖추었다.","a":"남고사지","c":"시도기념물","nc":"","r":"전북특별자치도","s":"전주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653569.jpg"},{"q":"○○○은 조선 명종 즉위년(1545)에 오양손(吳梁孫)이 처음 짓고 1922년 후손들이 고친 것이다. 해주오씨로는 처음으로 삼은리에 들어 온 오양손은, 김굉필(1454∼1504)의 문인으로 참봉을 지냈다. 그는 중종 14년(1519) 기묘사화(己卯士禍) 때 조광조 등 많은 선비들이 화를 입는 모습을 보고, 경기도 수원과 남원 목기촌으로 은거하였다가, 중종 16년(1521)에 삼은리로 들어왔다. 이후 그는 이곳에 ○○○을 짓고 시와 술을 벗삼으며, 후학을 지도하는 일에 전념하였다. 1856년에 중창하였고, 그 뒤 1922년에 중건하여 오늘에 이르고 있다.","a":"오괴정","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"임실군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661837.jpg"},{"q":"○○○○○는 왕실의 수명장수를 기원하는 기○○로서 왕의 패, 왕비의 패, 세자의 패 모두 3점이다. 조선 후기에 만들어진 것으로 왕의 패에는 황룡을 새기고 왕비의 패에는 봉황과 구름무늬를 새겼으며, 세자의 패에는 용과 새의 무늬를 새겨 놓았다. 섬세한 조각이나 정교한 문양을 새긴 기법과 장식적인 면에서 조선 후기 불교예술의 우수성을 엿볼 수 있는 자료이다.","a":"고성 운흥사 원패","c":"문화유산자료","nc":"","r":"경상남도","s":"고성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664670.jpg"},{"q":"○○광장 안의 정충단에 서 있는 비로, 임진왜란 당시 제2차 ○○성 싸움에서 충절을 다한 이들의 행적을 기리고 있다. 비는 거북받침과 비몸을 하나의 돌로 조각하였으며, 그 위로 머릿돌을 얹어 마무리하였는데, 머릿돌이 유난히 커서 전체가 사다리꼴로 보인다. 머릿돌은 두 마리의 용이 구름속에서 여의주를 놓고 서로 다투는 모습이 표현되어 있고, 그 밑면에 꽃을 조각하여 이채롭게 장식하였다. 비문은 아래쪽이 닳아서 그 부분만 판독하기가 힘들 뿐 대체로 양호하며, 『조선금석총람』에 그 기록이 실려있다.","a":"진주 촉석 정충단비","c":"시도유형문화유산","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641330.jpg"},{"q":"선대의 업적을 기리고 후손들의 강학 공간으로 지은 강당건물이다. ○○○은 회봉공(晦峰公) 배후도(裵後度)의 후손들이 조선 영조 1년(1725)에 지어 돈화재(敦話齋)라 이름하였다. 순조 15년(1815)에 지금의 위치로 옮기고 철종 3년(1852)에 이름을 모의(慕義)로 바꾸었다. ○○○이라는 이름은 1856년에 붙여진 것이다. 지금의 건물은 1899년에 지은 것으로 그 후 두차례에 걸쳐 고쳐 지어졌다. 앞면 4칸 반·옆면 2칸 규모로, 지붕은 옆에서 볼 때 여덟 팔(八)자 모양인 팔작지붕을 하고 있다.","a":"영동 모의당","c":"문화유산자료","nc":"","r":"충청북도","s":"영동군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660775.jpg"},{"q":"○○는 자기나 기와, 그릇들을 만들어 굽던 가마터를 말한다. ○○○ 가마터는 중원 미륵사터와 가까운 거리인 점말마을의 높은 산 동남쪽 경사면에 17세기에서 20세기 전반에 걸친 여러시기의 가마가 한 곳에 밀집되어 있다. 이곳에서는 4기의 가마터와 1기의 퇴적층, 1곳의 작업장이 확인되었다. 가마구조는 계단식 오름칸 가마로 보존상태가 잘 남아 있다. 출토유물로는 청화백자, 철화백자, 초문철화백자 등이 있다.","a":"충주 미륵리 요지","c":"시도기념물","nc":"","r":"충청북도","s":"충주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1650393.jpg"},{"q":"향교는 훌륭한 유학자를 제사하고 지방민의 유학교육과 교화를 위하여 나라에서 지은 교육기관이다 조선 태조 7년(1398)에 지금의 위치에서 동쪽으로 100m 지점에 세웠으며 임진왜란 때 불탄 것을 선조 36년(1603)에 대성전과 명륜당을, 인조 14년(1636)에 세심루를 다시 지어 오늘에 이른다. 출입문인 외삼문, 휴식공간인 세심루, 공부하는 곳인 명륜당, 사당인 대성전 등이 일직선으로 서있다. 또한 명륜당이 앞에 있고 대성전이 뒤에 있는 전학후묘의 형태로 되어있다.","a":"용궁향교","c":"시도유형문화유산","nc":"","r":"경상북도","s":"예천군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640705.jpg"},{"q":"향교는 훌륭한 유학자를 제사하고 지방민의 유학교육과 교화를 위하여 나라에서 지은 교육기관이다. 조선 태조 7년(1398)에 처음 지은 후 임진왜란(1592)으로 불타 없어진 것을 다시 지었으며, 1961년에 황폐한 향교를 복원하였다. 1966년과 1974년에 보수를 하여 오늘에 이르고 있다. 지금 남아있는 건물은 대성전(충청북도문화유산자료)과 명륜당·동재·서재·내삼문·외삼문·고직사 등이다. 사당인 대성전은 공자를 비롯하여 중국과 우리나라 유학자의 위패를 모시고 있다. 명륜당은 학생들이 모여 공부하는 강당으로 교화의 원천이 되기도 하였다.","a":"옥천향교","c":"시도유형문화유산","nc":"","r":"충청북도","s":"옥천군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638538.jpg"},{"q":"충청남도 논산시 연산면에 있는 이 ○○○은 임진왜란 때 불타 없어진 석불사(石佛寺)의 불상이다. 지금의 ○○○이란 명칭은 ○○○ 바로 옆의 노송이 불상과 조화를 이루며 지붕처럼 퍼져 있기 때문에 붙여진 이름이다. 양쪽 어깨에 걸치고 있는 옷은 가슴부분에서 U자형을 이루었고, 옷자락의 주름은 얕은 선으로 조각하여 발목까지 내려왔다. 왼손은 가슴에 대고 있으며, 오른손은 몸의 측면에 붙이고 있다. 이 불상은 고려 후기에서 조선 전기 사이에 만들어진 것으로 추정된다.","a":"송불암미륵불","c":"문화유산자료","nc":"","r":"충청남도","s":"논산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661021.jpg"},{"q":"이 비는 ○○○○를 지낸 적이 있는 ○○○의 공적을 기리기 위하여 세운 것이다. 이 비석은 조선 명종 14년(1559)에 세워진 것으로, 비문을 지은 이는 남명 조식(1501∼1572)이고, 글씨는 고산 황기로(1521∼1567)가 썼다. 가로 87cm, 세로 202cm, 폭 17cm 의 형식을 지녔으며 비문은 전체 13행, 각 행 평균 25자로 새겨져 있다. 비문에는 1554년에서 1558년까지 ○○○○를 지냈던 ○○○이 1554년의 극심한 흉년에 백성을 자식처럼 사랑하여 구휼하고, 청렴하게 관직생활을 했던 내용이 기록되어 있다.","a":"합천군수 이증영 유애비","c":"시도유형문화유산","nc":"","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642341.jpg"},{"q":"○○○는 신라 문무왕 16년(676) 의상조사가 지은 절로 임진왜란 당시 승병의 본거지였다고 전한다. 절 경내에 있는 건물로는 대웅전을 비롯하여 ○○○, 범종루, 산신각, 요사채 등이 있다. ○○○은 조선 영조 때 다시 지어 오늘에 이르고 있다.","a":"고성 운흥사 영산전","c":"문화유산자료","nc":"","r":"경상남도","s":"고성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664180.jpg"},{"q":"청동기시대 고인돌과 신라의 무덤이 섞여 분포하고 있는 곳이다. 발굴조사 결과 총 유구의 수는 27기이며 그 중 16기는 BC 5∼6세기 청동기시대의 고인돌(지석묘)이고 나머지 유구는 신라시대 무덤이다. 대부분의 고인돌 유구는 2∼4매의 덮개돌이 남아 있고 덮개돌이 없는 유구는 경작으로 유실된 것으로 보인다. 유물은 민무늬토기(무문토기), 간석기(마제석기) 등이 있다. 신라시대 무덤은 대부분 앞트기식 돌방무덤(횡구식석실묘)으로서 주위에 묘를 보호하는 의미를 갖고 있는 둘레돌(호석)이 둘러져 있다.","a":"거제 아주동 고분군","c":"시도기념물","nc":"","r":"경상남도","s":"거제시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1655950.jpg"},{"q":"조선 인조, 현종대의 학자인 석계 이시명(1590∼1674) 선생의 옛 집이다. 인조 18년(1640)에 석계 위에 집을 짓고 호를 석계라 하였다. 선생과 정부인 장씨가 살던 집으로 선생은 안동에서 세상을 떠났으나, 정부인은 이곳에서 죽을 때까지 살았다. 一자형의 사랑채와 안채는 흙담으로 막아 허실감을 메우고 뜰집과 같은 느낌이 들도록 하였다. 사랑채에는 대문을 중심으로 사랑방과 사랑마루를 두었으며, 왼쪽에는 마구간과 창고방을 시설하였다.","a":"석계고택","c":"시도민속문화유산","nc":"","r":"경상북도","s":"영양군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658788.jpg"},{"q":"광동댐 북쪽 야산의 구릉 중턱에 능선의 완만한 평탄부를 따라 분포하고 있는 50여기의 무덤이다. 눈으로 확인되는 봉분의 모습은 원형이지만 대부분이 원상태를 잃고 있다. 유구는 자연경사면을 이용해 구덩이를 판 뒤 할석으로 돌덧널(석곽)을 만든 뒤 5∼6매의 판석으로 덮었다. 주변에서 통일신라시대의 토기조각이 보이고, 유구의 평면상태가 가는직사각형(세장방형)을 띠고 있는 점, 위를 판석으로 덮은 점으로 보아 삼국시대나 통일신라시대의 것으로 보인다.","a":"삼척숙암리고분군","c":"시도기념물","nc":"","r":"강원특별자치도","s":"삼척시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1648249.jpg"},{"q":"○○○○은(鍾潭書堂) 조성중기에 초창되어 현재까지 이어져 오고 있는 건물로 역사적, 학술적 자료로서의 가치가 충분하고 화림동 계곡의 경관과도 잘 어울려서 서당, 대문채를 문화유산자료로 지정 가치가 있어 교육적 역사적 자료 등으로 활용가치가 높아 도 문화유산자료로 지정하여 보존하고자 함","a":"함양 종담서당","c":"문화유산자료","nc":"","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2019051319575900.jpg"},{"q":"전북특별자치도 남원시 송동면 ○○○ 뒷산에서 발굴된 불상으로, 전체 높이는 2.7m이다. 다른 석불을 보면 바위나 암벽에 부처를 새기는 것이 보통인데, 이 석불은 별도의 돌에 새긴 독특한 형태를 이루고 있다. 화강암으로 만들었으며, 연꽃무늬가 새겨진 2중의 대좌(臺座) 위에 서 있다. 양 손을 옷깃 소매 속에 넣어 팔짱을 끼고 있는 모습이어서 얼핏보면 달마상 같기도 하다. 작품을 다듬은 선이 원만하고 모양이 소박한 점으로 보아 고려 초기의 작품으로 추정된다. 전하는 이야기에 따르면 아주 먼 옛날 이곳에 사찰이 있었다고 하는데, 현재는 석불만 남아 있다.","a":"세전리석불입상","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"남원시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639547.jpg"},{"q":"18은행는 1890년 준공되어 그 해 10월에 개점하였고 중앙동2가 24번지에 있으며 58은행의 바로 옆에 위치해 있으며 1954년에는 한국흥업은행으로 사용되었다. 18은행은 일본이 한국의 금융계를 지배하고자 하는 목적으로 계획되어 세워진 은행이었다. 18은행뿐 아니라 그 당시에 세워진 일본 은행들 모두가 한국 금융계를 일본 식민지화 하려는 목적을 가지고 있었음을 알 수 있는 것은 7개의 은행을 비롯해 13곳의 보험사의 소유자가 천일은행을 제외하고는 모두 일본의 소유였다는 것으로도 충분히 알 수 있다.","a":"인천 구 일본제18은행","c":"시도유형문화유산","nc":"","r":"인천광역시","s":"제물포구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637117.jpg"},{"q":"○○○는 진주강씨 찬성공파 종중 재사로 1704년에 강영숙(?~1504)과 그 장자 호·차자 택·삼자 온·사자 준의 묘역 아래에 후손 강진·강로·강석경이 건립하였다. 현재 묘제를 지내고 묘소의 수호뿐만 아니라 후손들의 회합을 도모하는 장소로 이용되고 있다. 창건 이후 1830년 퇴락해진 건물을 문중 사람들이 뜻을 모아 재물을 보태어 중건하고 그 상량문을 대청 상부 종도리에 밀봉해 놓았다. 1830년 중건한 강당형 재실인 ○○○는 넉넉한 부재를 사용하여 튼실하게 잘 지은 건물로 중건 당시 모습이 거의 대부분 잘 남아 있다.","a":"상주 추원재","c":"문화유산자료","nc":"","r":"경상북도","s":"상주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2019051421582700.jpg"},{"q":"향교는 공자와 여러 성현께 제사를 지내고 지방민의 교육과 교화를 위해 나라에서 세운 교육기관이다. ○○○○를 처음 지은 연대는 알 수 없으나 조선 전기 이곳에 이미 향교와 문묘가 있었다고 전한다. 지금 남아 있는 건물들은 조선 중기 이후의 것으로 고종 11년(1874)과 1904년 등 여러 차례 수리하였다. 경내에는 제사지내는 공간인 대성전, 교육 기능을 수행하는 강당인 명륜당, 학생들의 기숙사인 동재·서재, 관리사 등의 건물이 있다. 대성전 안쪽에는 공자를 비롯하여 중국과 우리나라 성현들의 위패를 모시고 있다.","a":"청양향교","c":"시도기념물","nc":"","r":"충청남도","s":"청양군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1652991.jpg"},{"q":"요지는 자기나 기와, 그릇들을 만들어 굽던 가마터를 말한다. ○○○○○는 2001년 5월―2002년 2월까지 매장유산조사기관의 발굴조사 결과 모두 4기가 확인되었다. 4기 중 가장 북쪽에 자리하고 있는 4호는 상당부분 유실된 상태였으나 나머지 3기는 비교적 양호한 상태로 확인되었다. 1호 가마는 전체길이 2,450㎝ 내외로서 일부분이 유실되었을 뿐 아궁이와 소성실(燒成室), 굴뚝부가 완전한 형태로 남아 있으며, 특히 천장부는 약 3m 정도가 남아 있다.","a":"고창용산리분청사기요지","c":"시도기념물","nc":"","r":"전북특별자치도","s":"고창군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653751.jpg"},{"q":"상주시내의 북천(北川) 북쪽 산 기슭에 자리하고 있는 비로, 임진왜란 때 종사관으로서 왜적과 맞서 싸우다 순절한 윤섬·이경류·박호와 이 지역출신으로 의병장이 되어 각종 전투를 벌이다 의롭게 생을 마친 김준신·김일의 충절을 기리고 있다. 이들은 임진왜란이 끝난 후에도 오랫동안 그 공적을 인정받지 못하다가, 영조 14년(1738) 이 지역의 사림들에 의해 김일을 제외한 4인을 위한 사당을 지어 제사를 드리게 되었으나, 이에 반대하는 의견이 생겨나 3년 후 다시 없애게 되었다.","a":"충신의사단비","c":"시도기념물","nc":"","r":"경상북도","s":"상주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654629.jpg"},{"q":"表忠寺 아미타삼존탱은 ○○○ 大光殿 내부 향우측 불단 위에 絹本彩色의 액자형태로 봉안되어 있는 탱화이다. 화면 중앙에 입상의 아미타불을 본존으로 하여 그 좌우에 관음보살과 대세지보살을 협시로 묘사한 이 아미타삼존탱은 일종의 아미타내영도와 같은 성격에 괘불탱과 유사한 구도를 지니고 있다.","a":"밀양 표충사 아미타삼존도","c":"시도유형문화유산","nc":"","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1643077.jpg"},{"q":"향교는 공자와 여러 성현께 제사를 지내고 지방민의 교육과 교화를 위해 나라에서 세운 교육기관이다. ○○○○를 언제 처음 지었는지 알 수 없지만, 칠원현의 서쪽에 있던 건물을 조선 광해군 13년(1621)에 동쪽으로 옮겼다가 숙종 26년(1700)에 다시 지금 있는 자리로 옮겼다고 전한다. 1910년에는 ○○향교에 통합되었다가 1961년 칠원 유림이 복원하여 오늘에 이르고 있다. 건물 배치는 앞쪽에 교육 공간인 명륜당이 있고, 뒤쪽에 제사 공간인 대성전이 있는 전학후묘의 형식이다.","a":"함안 칠원향교","c":"문화유산자료","nc":"","r":"경상남도","s":"함안군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664270.jpg"},{"q":"임진왜란 때 훈련대장을 지낸 탁순창 선생이 고향으로 돌아와 조상을 모시기 위해 세운 사당이다. 6대조 경렴정 탁광무와 5대조 탁신의 위패를 모시고 있다. 지금 있는 건물은 1987년 임하댐 건설로 현 위치로 옮긴 것이다. 정문, 강당(추원당), 사당(세덕사)으로 구성되어 있으며, 그 중 세덕사는 앞면 3칸·옆면 2칸 크기로 一자형 평면을 갖추고 있다. 지붕은 옆면에서 볼 때 지붕선이 사람 인(人)자 모양과 비슷한 맞배지붕으로 꾸몄다.","a":"안동세덕사","c":"시도민속문화유산","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658567.jpg"},{"q":"일반적으로 임진왜란 이전의 ○○○는 자료의 희소성으로 국가유산적 가치를 인정받고 있다. ‘○○○○○’ 9점은 여타 ○○○와는 달리 형식은 단조롭지만 시기적으로 모두 임진왜란 이전의 것이라는 점에서 국가유산적 가치가 있다. 특히 이러한 사가 소장의 ○○○들은 시간이 지남에 따라 산일(散逸)되는 경우가 많다는 점에서 유형문화유산으로 지정되었다.","a":"김언신 관련 고문서","c":"시도유형문화유산","nc":"","r":"경상북도","s":"포항시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641129.jpg"},{"q":"이 가옥은 1609년(광해군 1)에 석문 정영방이 건축한 건물로서, 一자형 초가 대문채 뒤편에 ㄇ형 와가 몸채가 튼口자형을 이루고 있으며, 몸채는 안채와 사랑채가 90°각으로 돌아 앉아 내외공간이 좌우로 구분되어 있다. 이와 같은 배치 및 평면구성은 19세기 후반 이후의 주택에서 주로 볼 수 있는 유형으로 전통한옥의 변천과정을 이해하는데 중요한 자료이다.","a":"예천 석문종택","c":"문화유산자료","nc":"","r":"경상북도","s":"예천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663551.jpg"},{"q":"중초사지 당간지주(보물) 부근의 거대한 바위 면에 새겨진 범종으로 우리나라 유일의 ○○○이다. ○○○○○은 종 자체의 형태와 함께 고대에 범종을 실제로 어떤 식으로 사용했는지를 보여준다는 점에서 자료적 가치가 매우 크다. 바위 면에는 장방형의 나무틀에 쇠사슬로 매달린 종과 그 옆에서 종을 칠 준비를 마친 듯 당목(幢木 ; 종을 치는 나무 막대)을 잡고 정면을 향해 서 있는 승려가 얕게 새겨져 있다. 종에는 유곽 두 개가 있어 뒷면에 나머지 두 개를 암시하며, 당좌는 중앙에 원형, 양 끝에 반원형을 새겨 전체적으로 네 개라는 것을 암시한다.","a":"석수동마애종","c":"시도유형문화유산","nc":"","r":"경기도","s":"안양시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637501.jpg"},{"q":"○○○는 서원 앞에 자리하고 비로, 서원을 건립하게 된 동기와 그 서원에서 모시는 인물을 찬양하는 문장이 적혀 있다. 이 비가 자리하고 있는 ○○○○은 황희(1363∼1452) 선생을 모시기 위해 세운 사당이다. 조선 세종 때의 명재상으로 이름 높은 황희는 세종 5년(1423) 강원도 관찰사에 임명되었는데, 이 때 기근이 들어 각 고을을 돌아본 후 굶주린 백성들에게 양곡을 풀어 그들을 도왔다고 한다. 삼척지방에서는 이 때의 황희에 대한 고마움과 은혜에 보답하기 위해 돌을 쌓아 단을 만들어 ‘소공대’라 이름붙였다 한다. 이후 소공대는 무너지고 이곳에 기념비를 세웠다.","a":"삼척산양서원묘정비","c":"문화유산자료","nc":"","r":"강원특별자치도","s":"삼척시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660567.jpg"},{"q":"○○시가 한눈에 내려다보이는 우암산 자락 작은 동산에 자리잡고 있는 ○○으로 1935년에 세워졌다. 건물은 낮은 기단 위에 주춧돌을 놓고 네모 기둥을 세웠다. 지붕은 옆모습이 여덟 팔(八)자 모양인 팔작지붕으로 한식기와를 얹었다. 벽체는 외벽을 벽돌과 콘크리트로, 내벽은 석회로 마감하였다. 초기 ○○○ 신부들의 토착화 의지를 잘 담아내고 있는 것으로 여겨진다. 이 건물은 한옥의 구조를 갖추면서 서구적인 형태로 지어진 ○○건축으로 서양건축과 한국건축이 융화되어 나타난 절충형식으로 서양건축의 수용과 전통건축의 근대적 변화를 조명할 수 있는 귀중한 문화유산이다.","a":"청주 성공회 성당","c":"시도유형문화유산","nc":"","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638625.jpg"},{"q":"신도비란 임금이나 고관의 평생업적을 기록하여 그의 묘 남동쪽에 세워 두는 것으로, 이 비는 조선 중기의 문신인 ○○ 선생의 공적을 기록하고 있다. ○○은 조선 명조 때 우 ·좌의정, 영중추부사 등을 역임한 인물로, 성품이 단정하며 직무에 충실하였을 뿐만 아니라, 올바른 주장은 절대 굽히지 않았다 한다. 일생을 청백리로 일관하다 생을 마쳤으며, 죽은 후 ‘정간’이라는 시호가 붙여졌다. 비는 네모난 받침돌 위로 비몸을 세운 모습이며, 비몸의 윗쪽 양변을 둥글게 다듬었다. 받침돌은 윗면에 연꽃무늬를 둘렀으며, 옆의 4면에는 안상(眼象)을 얕게 새겨 두었다.","a":"정간공 이명 묘역","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"노원구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636202.jpg"},{"q":"◦ 1598년 4월에 세운 ○○○○ 계금(季金)의 ○○○로, ○○○○ 계금은 중국 명나라 절강성(浙江省) 수군장으로 임진왜란 때 3000명의 수군을 이끌고 이곳 오천(충청수영)으로 상륙하고 전라도로 이동하여 왜군을 토벌하였음. ◦ 비문은 장군의 덕(德)을 칭소하고 왜적을 빨리 무찌르기를 기원하였으며, 장군의 위엄을 빌려 바다에서의 안녕을 기도(祈禱)하자는 내용으로 임진왜란 대 명나라 수군이 상륙한 지점을 알려주고, 당시의 민속을 엿볼 수 있는 비로써, 비문은 안대진(安大進)이 지었음.","a":"보령유격장군청덕비","c":"시도유형문화유산","nc":"","r":"충청남도","s":"보령시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639268.jpg"},{"q":"승주 낙안성내 ○○○들은 ○○○○ 성벽과 성안에 심어진 나무들로 은행나무 3그루, 팽나무 6그루, 푸조나무 3그루, 개서어나무 2그루, 느티나무 1그루 등 모두 15그루가 있다. 객사 뒷편의 길이 약 150m에 이르는 성벽에는 팽나무 5그루, 푸조나무 2그루, 개서어나무 2그루, 느티나무 1그루 모두 10그루의 나무가 있다. 객사 동쪽에는 팽나무 1그루가 있고, 객사 뒷편 마당에는 큰 푸조나무 1그루가 있다. ○○○○ 동문에서 남서쪽 50m 거리와 남내리 객사 남쪽 110m 거리, 그리고 객사 남서쪽 130m 거리에 각각 은행나무가 한그루씩 심어져 있다.","a":"낙안읍성노거수","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"순천시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654295.jpg"},{"q":"향교는 공자와 여러 성현들께 제사를 지내고, 지방민의 교육과 교화를 위해 나라에서 세운 교육기관이다. ○○○○는 고려 공민왕(재위 1351∼1374) 때 월곡리에 있던 학당사을 옮겨온 것으로, 조선 중종 7년(1512)에 다시 지었다. ○○○은 선조 38년(1605)에 수리하였고, 1974년에 기와를 보수하였다. 규모는 앞면 3칸·옆면 2칸이며, 지붕은 옆에서 볼 때 사람 인(人)자 모양인 맞배지붕이다. 안쪽에는 공자를 비롯한 그 제자와 우리나라 성현들의 위패를 모시고 있다.","a":"고창향교 대성전","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"고창군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661707.jpg"},{"q":"이 영정은 ○○○○○선사의 좌안 8분면 바닥가부좌상으로, 상단벽면과 하단돗자리의 이단구도를 배경으로 하여 등받이와 팔걸이가 있는 의자를 배치하고 왼손엔 주장자를 들고 오른손은 무릎에 얹은 채 측면을 바라보며 앉아 있는 모습이다. 화면 향좌측에 주지묵서의 ‘선교양종대각등계팔도도총섭○○○○○지진(禪敎兩宗大覺登階八道都摠攝華峯堂有喆之眞)’의 화제가 있을 뿐이다. 화면 크기는 가로 78.7cm, 세로 120.8cm이다.","a":"화봉당 유철 진영","c":"시도유형문화유산","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/0000000001643011.JPG"},{"q":"연촌 최덕지·암계 최연손·율계 장급·사촌 장경세 등의 위패를 모신 서원이다. 조선 인조 8년(1630)에 세웠으며, 광무 원년(1897)에 철폐되었다가 그 후 1907년에 다시 세웠다. 제사지내는 장소인 사당은 앞면 3칸·옆면 2칸 규모로, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕이다. 공부하는 강당 역시 팔작지붕으로 앞면 4칸·옆면 3칸 규모의 건물이다. 이 서원에서는 해마다 음력 3월에 제사를 지내고 있다.","a":"주암서원","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"임실군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661637.jpg"},{"q":"송계 금인·삼송당 남몽오·수서 박선장·도은 권호신의 학문과 덕행을 추모하기 위해 위패를 모시고 있는 서원이다. 묘호를 기영사라고 부르다가 영조 42년(1766)에 ○○○○으로 승격하였다. 고종 5년(1868) 흥선대원군의 서원철폐령으로 폐쇄되었다가, 1967년 지방 유림들이 복원하여 해마다 음력 3월과 9월에 제사 지내고 있다. 위패를 모시고 있는 상현사는 앞면 3칸·옆면 2칸의 규모이며, 지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕으로 꾸몄다.","a":"구만서원","c":"문화유산자료","nc":"","r":"경상북도","s":"봉화군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662704.jpg"},{"q":"읍성이란 군이나 현의 주민을 보호하고, 군사적·행정적인 기능을 함께하는 성을 말한다. ○○의 읍성으로, 경상남도 ○○시 신현읍 고현리의 대지 위에 평면의 배 모양으로 돌을 쌓아 만들었다. 현종 4년(1663)까지 ○○군의 관아로 사용되었다고 한다. 『동국여지승람』에 실린 기록에 따르면, 둘레가 3,038척(921m), 높이 13척(4m)이라 하였으나, 현재 확인할 수 있는 성벽의 길이는 818m, 높이는 2m이다. 동·서·남의 3곳에 성문을 내었으며, 성문 앞에는 성문을 보호하기 위한 목적으로 작은 성 하나씩을 쌓았다.","a":"거제 고현성","c":"시도기념물","nc":"","r":"경상남도","s":"거제시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654959.jpg"},{"q":"중앙에서 파견된 관리나 외국의 사신들이 머물 수 있도록 해놓은 청송군의 객사이다. 세종 10년(1428)에 부사 하담이 처음 짓고 이후에 여러 차례 걸쳐 수리했다. 앞면 6칸·옆면 3칸 규모의 건물로, 원래는 가운데의 중당을 중심으로 양 옆에 날개부분이 배치된 형식이었다. 그러나 한일합방 후에 중당과 왼쪽 날개 부분의 건물이 없어지고, 지금은 남아있던 건물에 현판을 달아 보존하고 있다.","a":"운봉관","c":"시도유형문화유산","nc":"","r":"경상북도","s":"청송군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640794.jpg"},{"q":"동헌은 조선시대의 각 행정단위에 파견된 수령(守令)이 정무(政務)를 보더 청사(廳舍)이다. 이 건물은 당초 흥덕객사로 알고 있었으나 1983년도 해체보수시 발견된 상량문에 흥성읍성(지금의 배풍산)에 있던 동헌건물을 조선 순조7년(1807)에 이곳으로 이건한 것이 확인되어 명칭을 변경하게 되었다. 흥성은 흥덕의 옛 지명으로 고려 충선왕(1308~1312)이 즉위하자 왕명을 피해 장덕(章德)을 흥덕(興德)으로 고쳐 부르게 되었으며 고종 32년(1895)에 군으로 승격되었다가 1914년 부군(府郡)폐합령에 따라 무장(茂長)과 함께 고창군으로 통폐합 되었다.","a":"흥성동헌","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"고창군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639475.jpg"},{"q":"조선 중기의 대학자인 시계 ○○○ 선생을 문묘에 제사지내도록 숙종 43년(1717)에 내린 교지이다. ○○○은 조선시대 학자로 선조 11년(1578)에 학행으로 천거되어 6품직에 오르고 정산현감을 지냈다. 임진왜란이 일어났을 때 호조정랑으로 명나라 군사의 군량조달에 공을 세웠고, 선조 35년(1602) 청백리에 천거되었으며 형조참판에 임명되었으나 벼슬을 버리고 고향으로 돌아와 교육에 전념하였다. 문하에 송시열, 송준길 등 서인을 중심으로 한 기호학파를 형성하였다.","a":"김장생문묘배향교지","c":"시도유형문화유산","nc":"","r":"충청남도","s":"논산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2020062214371800.JPG"}]);